def _ok(result: dict[str, Any]) -> dict[str, Any]:
    return {"ok": True, **result}


def _error(exc: Exception) -> dict[str, Any]:
    if isinstance(exc, RevisionExecutionBusyError):
        return {
            "ok": False,
            "status": "revision_execution_busy",
            "error": str(exc),
            "project_id": exc.project_id,
            "revision": exc.revision,
            "target_revision": exc.revision,
            "execution_started": False,
            "execution_deferred": True,
            "execution_transaction_error": str(exc),
            "recommended_tool": "material_studio_live_project_status",
            "required_next_step": (
                "Wait for the active execution to finish, inspect its persisted "
                "result, and retry only if the current revision still needs execution."
            ),
            "execution_retry_tool": "material_studio_live_project_status",
            "execution_retry_payload": {
                "project_id": exc.project_id,
                "include_gui_status": True,
            },
        }
    if isinstance(exc, RevisionExecutionSupersededError):
        return {
            "ok": False,
            "status": "current_revision_execution_block",
            "error": str(exc),
            "project_id": exc.project_id,
            "revision": exc.target_revision,
            "target_revision": exc.target_revision,
            "current_revision": exc.current_revision,
            "execution_started": False,
            "execution_deferred": True,
            "execution_transaction": exc.transaction,
            "current_revision_execution_block": {
                "blocked": True,
                "reason": "current_revision_advanced_before_execution",
                "target_revision": exc.target_revision,
                "current_revision": exc.current_revision,
                "current_pointer": exc.current_pointer,
                "recommended_tool": "material_studio_live_project_status",
                "recommended_action": "inspect_current_revision_before_retrying_execution",
            },
            "recommended_tool": "material_studio_live_project_status",
            "required_next_step": (
                "Inspect the current revision and execute or hot-load that revision "
                "instead of the superseded prepared revision."
            ),
            "execution_retry_tool": "material_studio_live_project_status",
            "execution_retry_payload": {
                "project_id": exc.project_id,
                "include_gui_status": True,
            },
        }
    if isinstance(exc, ProjectRevisionAllocationConflictError):
        return {
            "ok": False,
            "status": "project_revision_allocation_conflict",
            "error": str(exc),
            "project_id": exc.project_id,
            "expected_new_revision": exc.expected_new_revision,
            "allocated_revision": exc.allocated_revision,
            "current_revision": exc.current_revision,
            "state_write_deferred": True,
            "recommended_tool": "material_studio_live_project_status",
            "required_next_step": (
                "Refresh project state and regenerate the revision-scoped script, "
                "planned outputs, and patch for the orphan-safe next revision."
            ),
            "state_retry_tool": "material_studio_live_project_status",
            "state_retry_payload": {
                "project_id": exc.project_id,
                "include_gui_status": True,
            },
        }
    if isinstance(exc, ProjectRevisionConflictError):
        return {
            "ok": False,
            "status": "project_revision_conflict",
            "error": str(exc),
            "project_id": exc.project_id,
            "expected_revision": exc.expected_revision,
            "current_revision": exc.current_revision,
            "state_write_deferred": True,
            "recommended_tool": "material_studio_live_project_status",
            "required_next_step": (
                "Refresh current project state and rebuild the patch or rollback "
                "against the returned current revision."
            ),
            "state_retry_tool": "material_studio_live_project_status",
            "state_retry_payload": {
                "project_id": exc.project_id,
                "include_gui_status": True,
            },
        }
    if isinstance(exc, ProjectStateBusyError):
        return {
            "ok": False,
            "status": "project_state_busy",
            "error": str(exc),
            "project_id": exc.project_id,
            "state_write_deferred": True,
            "project_state_transaction_error": str(exc),
            "recommended_tool": "material_studio_live_project_status",
            "required_next_step": (
                "Wait for the active project revision write to finish, refresh "
                "current state, and retry the original request."
            ),
            "state_retry_tool": "material_studio_live_project_status",
            "state_retry_payload": {
                "project_id": exc.project_id,
                "include_gui_status": False,
            },
        }
    if isinstance(exc, MaterialStudioError):
        return {"ok": False, "error": str(exc)}
    if isinstance(exc, (ValueError, GuiError)):
        return {"ok": False, "error": str(exc)}
    return {
        "ok": False,
        "error": f"Unexpected {type(exc).__name__}: {exc}. Check the Materials Studio runner path and license state.",
    }


def _dry_run(script: str, extra: dict[str, Any] | None = None) -> dict[str, Any]:
    return _ok({"dry_run": True, "script": script, **(extra or {})})


def _path_warning(path: str, label: str) -> list[str]:
    if Path(path).expanduser().exists():
        return []
    return [f"{label} does not exist on this machine. Dry-run is still useful; execution will likely fail until the path is corrected."]


def _format_run_result(result: dict[str, Any], response_format: ResponseFormat) -> dict[str, Any]:
    if response_format == ResponseFormat.JSON:
        return _ok({"result": result})

    lines = [
        "# Materials Studio Script Result",
        "",
        f"- Return code: {result['return_code']}",
        f"- Success: {result['success']}",
        f"- Timed out: {result['timed_out']}",
        f"- Job directory: {result['job_dir']}",
        f"- Script: {result['script_path']}",
    ]
    if result.get("parsed_json") is not None:
        lines.extend(["", "## Parsed JSON", "", "```json", str(result["parsed_json"]), "```"])
    if result.get("stdout"):
        lines.extend(["", "## stdout", "", "```text", result["stdout"][-4000:], "```"])
    if result.get("materials_output"):
        lines.extend(["", "## MaterialsScript output", "", "```text", result["materials_output"][-4000:], "```"])
    if result.get("stderr"):
        lines.extend(["", "## stderr", "", "```text", result["stderr"][-4000:], "```"])
    if result.get("materials_log"):
        lines.extend(["", "## Materials Studio log", "", "```text", result["materials_log"][-4000:], "```"])
    return _ok({"markdown": "\n".join(lines), "result": result})


def _validate_molecule_graph(atoms: list[MoleculeAtom], bonds: list[MoleculeBond]) -> None:
    atom_ids = [atom.id for atom in atoms]
    unique_ids = set(atom_ids)
    if len(unique_ids) != len(atom_ids):
        raise ValueError("Atom IDs must be unique.")
    referenced = {bond.atom1 for bond in bonds} | {bond.atom2 for bond in bonds}
    missing = sorted(referenced - unique_ids)
    if missing:
        raise ValueError(f"Bonds reference unknown atom IDs: {', '.join(missing)}")


def _run_build_script(params: BuildMoleculeInput) -> dict[str, Any]:
    _validate_molecule_graph(params.atoms, params.bonds)
    script = build_molecule_script(
        params.name,
        params.output_file,
        [atom.model_dump() for atom in params.atoms],
        [
            {"atom1": bond.atom1, "atom2": bond.atom2, "type": bond.type.value}
            for bond in params.bonds
        ],
        optimize=params.optimize,
        forcefield=params.forcefield,
        quality=params.quality.value,
        max_iterations=params.max_iterations,
    )
    if params.dry_run:
        return _dry_run(script)
    try:
        result = runner.run_script(
            script,
            working_dir=params.working_dir,
            timeout_seconds=params.timeout_seconds,
            job_prefix="build_molecule",
        )
        return _ok({"result": result.to_dict()})
    except Exception as exc:
        return _error(exc)


@mcp.tool(
    name="material_studio_get_status",
    annotations={
        "title": "Get Materials Studio runner status",
        "readOnlyHint": True,
        "destructiveHint": False,
        "idempotentHint": True,
        "openWorldHint": False,
    },
)
def material_studio_get_status() -> dict[str, Any]:
    """Get BIOVIA Materials Studio automation status.

    Returns:
        dict[str, Any]: JSON-serializable status with keys:
            - ok (bool): whether the MCP tool succeeded
            - connected (bool): whether a runner executable was found
            - runner (str | None): resolved RunMatserver/RunMatScript path
            - workspace_root (str): base folder used for generated job folders
            - searched_candidates (list[str]): runner paths checked
    """

    return _ok(runner.status())


