def _schema_capability_paths() -> dict[str, dict[str, str]]:
    """Return schema files used by structured live modeling clients."""

    schema_dir = Path(__file__).with_name("schemas")
    schema_files = {
        "model_spec": "model_spec.schema.json",
        "molecule_spec": "molecule_spec.schema.json",
        "crystal_spec": "crystal_spec.schema.json",
        "forcite_spec": "forcite_spec.schema.json",
        "castep_spec": "castep_spec.schema.json",
        "semantic_patch": "patch_spec.schema.json",
    }
    return {
        key: {
            "filename": filename,
            "package_relative_path": f"src/material_studio_mcp_server/schemas/{filename}",
            "path": str(schema_dir / filename),
        }
        for key, filename in schema_files.items()
    }


