        MoleculeAtom(id="N1", element="N", x=1.440, y=2.490, z=0.000),
        MoleculeAtom(id="O1", element="O", x=1.990, y=3.250, z=0.350),
        MoleculeAtom(id="O2", element="O", x=0.930, y=3.070, z=-0.350),
