@mcp.tool(
    name="material_studio_castep_energy_script",
    annotations={
        "title": "Generate a CASTEP task script",
        "readOnlyHint": True,
        "destructiveHint": False,
        "idempotentHint": True,
        "openWorldHint": False,
    },
)
def material_studio_castep_energy_script(
    input_file: Annotated[
        str,
        Field(description="Structure file imported by the CASTEP task script.", min_length=1, max_length=500),
    ],
    quality: Annotated[
        str,
        Field(description="CASTEP quality setting.", min_length=1, max_length=100),
    ] = "Medium",
    task: Annotated[
        CastepTaskValue,
        Field(description="CASTEP task with a verified Materials Studio 20.1 API mapping."),
    ] = CastepTask.ENERGY,
    functional: Annotated[
        str,
        Field(description="Exchange-correlation functional setting.", min_length=1, max_length=100),
    ] = "PBE",
    cutoff_energy_ev: Annotated[
        int | None,
        Field(description="Optional cutoff energy in eV.", ge=1, le=100_000),
    ] = None,
    kpoint_separation: Annotated[
        float | None,
        Field(description="Optional primary SCF k-point separation.", gt=0, le=10),
    ] = None,
    kpoints: Annotated[
        tuple[int, int, int] | None,
        Field(description="Optional primary SCF custom k-point grid."),
    ] = None,
) -> dict[str, Any]:
    """Generate a task-aware CASTEP MaterialsScript Perl template.

    This tool does not execute CASTEP. Use material_studio_run_script after
    reviewing the generated script and confirming the local CASTEP license and
    server queue settings are ready.

    Args:
        input_file (str): structure imported by the CASTEP task script.
        quality (str): CASTEP quality setting.
        task (str): CASTEP task name.
        functional (str): exchange-correlation functional.
        cutoff_energy_ev (int | None): optional cutoff energy in eV.
        kpoint_separation (float | None): optional primary SCF k-point separation.
        kpoints (tuple[int, int, int] | None): optional primary SCF custom grid.

    Returns:
        dict[str, Any]: generated MaterialsScript Perl source code.
    """

    params = CastepEnergyInput(
        input_file=input_file,
        quality=quality,
        task=task,
        functional=functional,
        cutoff_energy_ev=cutoff_energy_ev,
        kpoint_separation=kpoint_separation,
        kpoints=kpoints,
    )
    spec = CastepEnergySpec(
        task=params.task,
        quality=params.quality,
        functional=params.functional,
        cutoff_energy_ev=params.cutoff_energy_ev,
        kpoint_separation=params.kpoint_separation,
        kpoints=params.kpoints,
    )
    plan = build_castep_materialscript_plan(spec)
    script = castep_energy_script(
        params.input_file,
        quality=spec.quality,
        task=spec.task.value,
        functional=spec.functional,
        cutoff_energy_ev=spec.cutoff_energy_ev,
        kpoint_separation=spec.kpoint_separation,
        kpoints=spec.kpoints,
    )
    return _ok(
        {
            "script": script,
            "execution_mode": "preview",
            "executes_castep": False,
            "castep_dispatch": plan.summary(),
        }
    )


def _structured_store(working_dir: str | None = None) -> ProjectStore:
    """获取结构化项目存储实例。"""
    return ProjectStore(working_dir)


def _available_project_id(store: ProjectStore, desired_project_id: str) -> str:
    """Return a project id that does not already have current state."""

    base = desired_project_id[:120]
    if not (store.project_dir(base) / "current.json").exists():
        return base
    for index in range(2, 1000):
        suffix = f"_{index}"
        candidate = f"{base[: 120 - len(suffix)]}{suffix}"
        if not (store.project_dir(candidate) / "current.json").exists():
            return candidate
    raise ValueError(f"无法为项目生成可用 project_id: {desired_project_id}")


def _latest_live_project(store: ProjectStore) -> tuple[ModelSpec, dict[str, Any]] | None:
    """Return the latest current project for conversation-style live edits."""

    latest = store.latest_project()
    if latest is None:
        return None
    spec, current_resolution = store.resolve_current(str(latest["project_id"]))
    resolution = {
        "source": "latest_current",
        "project_id": spec.project_id,
        "revision": spec.revision,
        "current_path": latest.get("current_path"),
        "current_mtime_ns": latest.get("current_mtime_ns"),
        "current_pointer_status": current_resolution.get("status"),
        "current_pointer_valid": current_resolution.get("valid"),
        "current_pointer_recovery_used": current_resolution.get("recovery_used"),
        "current_read_source": current_resolution.get("read_source"),
        "current_pointer": current_resolution,
    }
    return spec, resolution


def _implicit_visible_workspace_guard(
    *,
    store: ProjectStore,
    current_spec: ModelSpec,
    project_resolution: dict[str, Any] | None,
    user_request: str,
    workflow: str,
) -> dict[str, Any] | None:
    """Block an implicit follow-up when the visible wrapper belongs to another workspace."""

    try:
        gui_status = _gui_controller(str(store.workspace_root)).status(
            project_id=current_spec.project_id,
            revision=current_spec.revision,
        )
    except Exception:
        return None
    window_management = (
        gui_status.get("window_management")
        if isinstance(gui_status.get("window_management"), dict)
        else {}
    )
    workspace_context = (
        window_management.get("workspace_context")
        if isinstance(window_management.get("workspace_context"), dict)
        else gui_status.get("workspace_context")
        if isinstance(gui_status.get("workspace_context"), dict)
        else {}
    )
    if not (
        window_management.get("workspace_context_mismatch") is True
        or gui_status.get("workspace_context_mismatch") is True
    ):
        return None

    recommended_working_dir = _first_not_none(
        window_management.get("recommended_working_dir"),
        gui_status.get("recommended_working_dir"),
        workspace_context.get("recommended_working_dir"),
    )
    visible_project_id = workspace_context.get("recommended_project_id")
    visible_revision = workspace_context.get("recommended_revision")
    payload_hint = _drop_none_values(
        {
            "user_request": user_request,
            "working_dir": recommended_working_dir,
            "project_id": visible_project_id,
            "base_revision": visible_revision,
            "include_gui_status": True,
        }
    )
    return _attach_live_failure_contract(
        {
            "ok": False,
            "workflow": workflow,
            "user_request": user_request,
            "project_id": current_spec.project_id,
            "revision": current_spec.revision,
            "project_resolution": project_resolution,
            "workspace_context_mismatch": True,
            "implicit_project_resolution_blocked": True,
            "revision_created": False,
            "write_attempted": False,
            "controller_workspace_root": str(store.workspace_root),
            "recommended_working_dir": recommended_working_dir,
            "visible_gui_context": workspace_context,
            "window_management_receipt": _select_keys(
                window_management,
                [
                    "status",
                    "process_count",
                    "window_count",
                    "single_window_policy_ok",
                    "workspace_context_mismatch",
                    "recommended_working_dir",
                    "selected_window_handle",
                    "selected_window_title",
                    "selected_window_project_id",
                    "selected_window_revision",
                    "selected_window_wrapper_workspace_root",
                    "target_window_handle",
                    "target_window_title",
                    "warnings",
                ],
            ),
            "error": (
                "The implicit current-project follow-up was not applied because the visible "
                "Materials Studio wrapper belongs to a different trusted workspace."
            ),
        },
        status="workspace_context_mismatch",
        recommended_action="rerun_request_with_visible_wrapper_workspace_and_explicit_project_id",
        payload_hint=payload_hint,
    )


def _explicit_project_resolution(
    spec: ModelSpec,
    current_resolution: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Return response metadata for an explicitly selected project."""

    resolution = {
        "source": "explicit",
        "project_id": spec.project_id,
        "revision": spec.revision,
    }
    if current_resolution is not None:
        resolution.update(
            {
                "current_pointer_status": current_resolution.get("status"),
                "current_pointer_valid": current_resolution.get("valid"),
                "current_pointer_recovery_used": current_resolution.get("recovery_used"),
                "current_read_source": current_resolution.get("read_source"),
                "current_pointer": current_resolution,
            }
        )
    return resolution


def _inline_spec_resolution(spec: ModelSpec) -> dict[str, Any]:
    """Return response metadata for an inline ModelSpec payload."""

    return {"source": "inline_spec", "project_id": spec.project_id, "revision": spec.revision}


def _resolve_model_spec_for_read(
    store: ProjectStore,
    spec_payload: dict[str, Any] | None,
    project_id: str | None,
) -> tuple[ModelSpec, dict[str, Any]]:
    """Resolve a ModelSpec for read/export tools with latest-project fallback."""

    if spec_payload is not None:
        model_spec = ModelSpec.model_validate(spec_payload)
        return model_spec, _inline_spec_resolution(model_spec)
    if project_id is not None:
        model_spec, current_resolution = store.resolve_current(project_id)
        return model_spec, _explicit_project_resolution(model_spec, current_resolution)
    latest = _latest_live_project(store)
    if latest is None:
        raise ValueError("No current structured project exists. Provide a ModelSpec or project_id before exporting diagnostics.")
    return latest


def _resolve_live_execution_mode(value: ExecutionMode | str | None, user_request: str) -> tuple[ExecutionMode, str]:
    """Resolve live-entry execution mode from an explicit parameter or text intent."""

    if value is not None:
        return _execution_mode(value), "explicit_parameter"
    if _explicit_live_hotload_requested(user_request):
        return ExecutionMode.EXECUTE, "explicit_live_intent"
    return ExecutionMode.PREVIEW, "default_preview"


