    issue_index_path = bundle_path / "modeling_issue_index.json"
    issue_index_path.write_text("{}", encoding="utf-8")
    issue_index_csv_path = bundle_path / "modeling_issue_index.csv"
    issue_index_csv_path.write_text("", encoding="utf-8")
    diagnostic_manifest_path = bundle_path / "diagnostic_export_manifest.json"
