def _modeling_report_summary_row(response: dict[str, Any], report: dict[str, Any]) -> dict[str, Any]:
    """Return a stable CSV row for the compact modeling report."""

    readiness = report.get("live_readiness") if isinstance(report.get("live_readiness"), dict) else {}
    acceptance = report.get("acceptance_review") if isinstance(report.get("acceptance_review"), dict) else {}
