def _promote_response_semiconductor_diagnostics(response: dict[str, Any]) -> None:
    """Expose semiconductor-domain diagnostics at the response top level."""

    report = response.get("modeling_report") if isinstance(response.get("modeling_report"), dict) else {}
    live_summary = response.get("live_summary")
    if not isinstance(live_summary, dict):
        live_summary = report.get("live_summary") if isinstance(report.get("live_summary"), dict) else {}
    semiconductor_review = (
        report.get("semiconductor_review")
        if isinstance(report.get("semiconductor_review"), dict)
        else {}
    )
    inspection = report.get("inspection") if isinstance(report.get("inspection"), dict) else {}
    semiconductor_health = (
        inspection.get("semiconductor_health")
        if isinstance(inspection.get("semiconductor_health"), dict)
        else {}
    )
    modeling_health = response.get("modeling_health")
    if not isinstance(modeling_health, dict):
        modeling_health = report.get("modeling_health") if isinstance(report.get("modeling_health"), dict) else {}
    checks = modeling_health.get("checks") if isinstance(modeling_health.get("checks"), dict) else {}

    promoted: dict[str, Any] = {}
    for key in _TOP_LEVEL_SEMICONDUCTOR_DIAGNOSTIC_FIELDS:
        if key in live_summary and live_summary.get(key) is not None:
            promoted[key] = live_summary.get(key)

    promoted.setdefault(
        "semiconductor_available",
        _first_not_none(semiconductor_review.get("available"), semiconductor_health.get("available")),
    )
    promoted.setdefault(
        "semiconductor_ok",
        _first_not_none(semiconductor_review.get("ok"), semiconductor_health.get("ok")),
    )
    promoted.setdefault(
        "semiconductor_rule",
        _first_not_none(
            live_summary.get("semiconductor_rule"),
            semiconductor_review.get("rule"),
            semiconductor_health.get("rule"),
            checks.get("semiconductor_rule"),
        ),
    )
    promoted.setdefault(
        "semiconductor_formula",
        _first_not_none(
            live_summary.get("semiconductor_formula"),
            live_summary.get("formula"),
            semiconductor_review.get("formula"),
            semiconductor_health.get("formula"),
            checks.get("semiconductor_formula"),
        ),
    )
    promoted.setdefault(
        "semiconductor_reduced_formula",
        _first_not_none(
            live_summary.get("semiconductor_reduced_formula"),
            live_summary.get("reduced_formula"),
            semiconductor_review.get("reduced_formula"),
            semiconductor_health.get("reduced_formula"),
        ),
    )
    promoted = _drop_none_values(promoted)
    for key in _TOP_LEVEL_SEMICONDUCTOR_DIAGNOSTIC_FIELDS:
        if key in promoted:
            response[key] = promoted[key]


