def _requested_diagnostic_focus_status(report: dict[str, Any]) -> dict[str, Any]:
    """Return artifact/summary availability for user-requested diagnostic focus areas."""

    focuses = report.get("requested_diagnostic_focuses")
    if not isinstance(focuses, list):
        focuses = []
    auto_completed_focuses = _dedupe_strings(
        [
            str(item)
            for item in report.get("auto_completed_diagnostic_focuses", [])
            if item
        ]
        if isinstance(report.get("auto_completed_diagnostic_focuses"), list)
        else []
    )
    auto_completed_focus_set = set(auto_completed_focuses)
    diagnostics = report.get("diagnostics") if isinstance(report.get("diagnostics"), dict) else {}
    row_counts = diagnostics.get("view_bundle_row_counts") if isinstance(diagnostics.get("view_bundle_row_counts"), dict) else {}
    items: list[dict[str, Any]] = []
    missing_csv_keys: list[str] = []
    missing_summary_keys: list[str] = []
    for focus in [str(item) for item in focuses]:
        auto_completed = focus in auto_completed_focus_set
        requirements = _REQUESTED_DIAGNOSTIC_FOCUS_REQUIREMENTS.get(focus, {"summary_keys": [], "csv_keys": []})
        summary_keys = list(requirements.get("summary_keys") or [])
        csv_keys = list(requirements.get("csv_keys") or [])
        summary_status = {
            key: _diagnostic_summary_available(report, key)
            for key in summary_keys
        }
        missing_summaries = [key for key, available in summary_status.items() if not available]
        artifacts: dict[str, Any] = {}
        existing_csv_keys: list[str] = []
        focus_missing_csv_keys: list[str] = []
        csv_row_counts: dict[str, Any] = {}
        for key in csv_keys:
            value = diagnostics.get(key)
            artifacts[key] = value
            row_key = key[:-4] if key.endswith("_csv") else key
            if row_key in row_counts:
                csv_row_counts[row_key] = row_counts.get(row_key)
            if _artifact_path_exists(value):
                existing_csv_keys.append(key)
            else:
                focus_missing_csv_keys.append(key)
        missing_csv_keys.extend(focus_missing_csv_keys)
        missing_summary_keys.extend(missing_summaries)
        items.append(
            {
                "focus": focus,
                "source": "auto_completed" if auto_completed else "user_request",
                "auto_completed": auto_completed,
                "available": bool(existing_csv_keys or any(summary_status.values())),
                "ok": not focus_missing_csv_keys and not missing_summaries,
                "summary_keys": summary_keys,
                "available_summary_keys": [key for key, available in summary_status.items() if available],
                "missing_summary_keys": missing_summaries,
                "csv_keys": csv_keys,
                "existing_csv_keys": existing_csv_keys,
                "missing_csv_keys": focus_missing_csv_keys,
                "artifacts": artifacts,
                "row_counts": csv_row_counts,
                "next_action": "requested_diagnostic_focus_ready"
                if not focus_missing_csv_keys and not missing_summaries
                else "export_view_bundle_or_review_missing_focus_diagnostics",
            }
        )
    return {
        "available": bool(items),
        "ok": all(item["ok"] for item in items) if items else None,
        "focus_count": len(items),
        "auto_completed_focuses": auto_completed_focuses,
        "auto_completed_focus_count": len(auto_completed_focuses),
        "focuses": items,
        "missing_csv_keys": _dedupe_strings(missing_csv_keys),
        "missing_summary_keys": _dedupe_strings(missing_summary_keys),
    }


def _diagnostic_focus_plan(report: dict[str, Any]) -> dict[str, Any]:
    """Summarize requested and recommended diagnostic exports into one safe next action."""

    requested = report.get("requested_diagnostic_focuses")
    if not isinstance(requested, list):
        requested = []
    requested_focuses = _dedupe_strings([str(item) for item in requested if item])
    auto_completed = report.get("auto_completed_diagnostic_focuses")
    auto_completed_focuses = _dedupe_strings(
        [str(item) for item in auto_completed if item]
        if isinstance(auto_completed, list)
        else []
    )
    auto_completed_focus_set = set(auto_completed_focuses)
    user_requested_focuses = [
        focus for focus in requested_focuses if focus not in auto_completed_focus_set
    ]

    template_defaults = report.get("semiconductor_template_default_diagnostic_focuses")
    if not isinstance(template_defaults, list):
        template_defaults = []
    template_default_focuses = _dedupe_strings([str(item) for item in template_defaults if item])

    recommended = report.get("recommended_diagnostic_focuses")
    if not isinstance(recommended, list):
        recommended = requested_focuses + template_default_focuses
    recommended_focuses = _dedupe_strings([str(item) for item in recommended if item])
    if not recommended_focuses:
        recommended_focuses = _dedupe_strings(requested_focuses + template_default_focuses)

    unrequested = report.get("unrequested_recommended_diagnostic_focuses")
    if isinstance(unrequested, list):
        unrequested_recommended_focuses = _dedupe_strings([str(item) for item in unrequested if item])
    else:
        requested_set = set(requested_focuses)
        unrequested_recommended_focuses = [focus for focus in recommended_focuses if focus not in requested_set]

    focus_status = (
        report.get("requested_diagnostic_focus_status")
        if isinstance(report.get("requested_diagnostic_focus_status"), dict)
        else _requested_diagnostic_focus_status(report)
    )
    if not auto_completed_focuses:
        status_auto_completed = focus_status.get("auto_completed_focuses")
        if isinstance(status_auto_completed, list):
            auto_completed_focuses = _dedupe_strings(
                [str(item) for item in status_auto_completed if item]
            )
            auto_completed_focus_set = set(auto_completed_focuses)
            user_requested_focuses = [
                focus for focus in requested_focuses if focus not in auto_completed_focus_set
            ]
    missing_focuses = [
        str(item.get("focus"))
        for item in focus_status.get("focuses", [])
        if isinstance(item, dict) and item.get("focus") and item.get("ok") is False
    ]
    missing_csv_keys = _dedupe_strings([str(item) for item in focus_status.get("missing_csv_keys") or [] if item])
    missing_summary_keys = _dedupe_strings(
        [str(item) for item in focus_status.get("missing_summary_keys") or [] if item]
    )
    recommended_focus_status = _requested_diagnostic_focus_status(
        {
            **report,
            "requested_diagnostic_focuses": recommended_focuses,
            "auto_completed_diagnostic_focuses": auto_completed_focuses,
        }
    )
    recommended_focus_missing_csv_keys = _dedupe_strings(
        [str(item) for item in recommended_focus_status.get("missing_csv_keys") or [] if item]
    )
    recommended_focus_missing_summary_keys = _dedupe_strings(
        [str(item) for item in recommended_focus_status.get("missing_summary_keys") or [] if item]
    )
    recommended_focuses_ready = bool(
        recommended_focuses
        and recommended_focus_status.get("ok") is True
        and not recommended_focus_missing_csv_keys
        and not recommended_focus_missing_summary_keys
    )
    diagnostic_export_requested = bool(report.get("diagnostic_export_requested"))
    normality_check_requested = bool(report.get("normality_check_requested"))
    diagnostic_requested = bool(
        diagnostic_export_requested
        or normality_check_requested
        or requested_focuses
        or template_default_focuses
    )

    if focus_status.get("ok") is False:
        status = "requested_focus_incomplete"
        recommended_action = "export_view_bundle_for_missing_requested_diagnostic_focuses"
        export_needed = True
    elif unrequested_recommended_focuses and recommended_focuses_ready:
        status = "recommended_focuses_ready"
        recommended_action = "review_recommended_diagnostic_focus_status"
        export_needed = False
    elif unrequested_recommended_focuses:
        status = "recommended_focuses_unrequested"
        recommended_action = "export_recommended_diagnostic_focuses_for_current_revision"
        export_needed = True
    elif requested_focuses:
        status = "requested_focuses_ready"
        recommended_action = "review_requested_diagnostic_focus_status"
        export_needed = False
    elif diagnostic_export_requested or normality_check_requested:
        if recommended_focuses_ready:
            status = "diagnostic_export_ready"
            recommended_action = "review_exported_diagnostic_bundle"
            export_needed = False
        else:
            status = "diagnostic_export_requested"
            recommended_action = "export_view_bundle_for_current_revision"
            export_needed = True
    elif template_default_focuses:
        if recommended_focuses_ready:
            status = "template_focuses_ready"
            recommended_action = "review_recommended_diagnostic_focus_status"
            export_needed = False
        else:
            status = "template_focuses_recommended"
            recommended_action = "export_recommended_diagnostic_focuses_for_current_revision"
            export_needed = True
    else:
        status = "no_focus_requested"
        recommended_action = "diagnostic_focus_plan_ready"
        export_needed = False
    ok = (
        False
        if focus_status.get("ok") is False or export_needed
        else True
        if diagnostic_requested
        else None
    )

    return _drop_none_values(
        {
            "available": diagnostic_requested,
            "ok": ok,
            "status": status,
            "export_needed": export_needed,
            "diagnostic_export_requested": diagnostic_export_requested,
            "normality_check_requested": normality_check_requested,
            "requested_focuses": requested_focuses,
            "user_requested_focuses": user_requested_focuses,
            "auto_completed_focuses": auto_completed_focuses,
            "auto_completed_focus_count": len(auto_completed_focuses),
            "template_default_focuses": template_default_focuses,
            "recommended_focuses": recommended_focuses,
            "unrequested_recommended_focuses": unrequested_recommended_focuses,
            "requested_focus_status_ok": focus_status.get("ok"),
            "requested_focus_count": focus_status.get("focus_count"),
            "recommended_focus_count": len(recommended_focuses),
            "recommended_focus_status_ok": recommended_focus_status.get("ok"),
            "recommended_focuses_ready": recommended_focuses_ready,
            "recommended_focus_missing_csv_keys": recommended_focus_missing_csv_keys,
            "recommended_focus_missing_summary_keys": recommended_focus_missing_summary_keys,
            "missing_requested_focuses": _dedupe_strings(missing_focuses),
            "missing_csv_keys": missing_csv_keys,
            "missing_summary_keys": missing_summary_keys,
            "action_id": recommended_action,
            "recommended_tool": "material_studio_model_export_view_bundle",
            "recommended_action": recommended_action,
            "needs_user_confirmation": False,
            "safe_to_call_without_confirmation": True,
            "payload_hint": _drop_none_values(
                {
                    "project_id": report.get("project_id"),
                    "revision": report.get("revision"),
                    "include_gui_snapshot": True,
                    "recommended_focuses": recommended_focuses,
                    "auto_completed_focuses": auto_completed_focuses,
                }
            ),
        }
    )


def _semiconductor_diagnostic_gate(report: dict[str, Any]) -> dict[str, Any]:
    """Summarize whether semiconductor diagnostics are delivered enough for @mcp clients."""

    semiconductor = report.get("semiconductor_review") if isinstance(report.get("semiconductor_review"), dict) else {}
    if not semiconductor or semiconductor.get("available") is False:
        return {"available": False, "reason": "no_semiconductor_review"}

    diagnostics = report.get("diagnostics") if isinstance(report.get("diagnostics"), dict) else {}
    row_counts = diagnostics.get("view_bundle_row_counts") if isinstance(diagnostics.get("view_bundle_row_counts"), dict) else {}
    if not row_counts and isinstance(report.get("view_bundle_row_counts"), dict):
        row_counts = report["view_bundle_row_counts"]
    if not isinstance(row_counts, dict):
        row_counts = {}
    diagnostic_export_manifest = (
        report.get("diagnostic_export_manifest")
        if isinstance(report.get("diagnostic_export_manifest"), dict)
        else {}
    )
    focus_status = (
        report.get("requested_diagnostic_focus_status")
        if isinstance(report.get("requested_diagnostic_focus_status"), dict)
        else {}
    )
    focus_plan = (
        report.get("diagnostic_focus_plan")
        if isinstance(report.get("diagnostic_focus_plan"), dict)
        else {}
    )
    normality = (
        report.get("semiconductor_normality_diagnosis")
        if isinstance(report.get("semiconductor_normality_diagnosis"), dict)
        else {}
    )

    required_row_counts = {
        "view_summary": 1,
        "view_projections": 1,
        "view_quality": 1,
        "semiconductor_composition": 1,
        "semiconductor_calculation_preflight": 1,
        "semiconductor_calculation_readiness": 1,
        "semiconductor_normality_diagnosis": 1,
    }

    def row_count_value(key: str) -> int:
        try:
            return int(row_counts.get(key) or 0)
        except (TypeError, ValueError):
            return 0

    missing_row_counts = [
        key for key, minimum in required_row_counts.items() if row_count_value(key) < minimum
    ]
    required_artifacts = [
        "view_summary_csv",
        "view_projections_csv",
        "view_quality_csv",
        "semiconductor_normality_diagnosis_json",
        "semiconductor_normality_diagnosis_csv",
        "diagnostic_export_manifest_json",
    ]
    optional_artifacts: list[str] = []
    requested_focus_declared = bool(
        focus_status.get("focus_count")
        or focus_status.get("auto_completed_focus_count")
        or focus_status.get("missing_csv_keys")
        or focus_status.get("missing_summary_keys")
        or report.get("requested_diagnostic_focuses")
        or report.get("required_diagnostic_focuses")
        or focus_plan.get("diagnostic_export_requested")
        or focus_plan.get("normality_check_requested")
        or focus_plan.get("requested_focuses")
        or focus_plan.get("auto_completed_focuses")
    )
    if requested_focus_declared:
        optional_artifacts.append("requested_diagnostic_focus_status_json")
    missing_artifacts = [
        key for key in required_artifacts if not _artifact_path_exists(diagnostics.get(key))
    ]
    missing_optional_artifacts = [
        key for key in optional_artifacts if not _artifact_path_exists(diagnostics.get(key))
    ]
    focus_missing_csv = _dedupe_strings([str(item) for item in focus_status.get("missing_csv_keys") or [] if item])
    focus_missing_summary = _dedupe_strings(
        [str(item) for item in focus_status.get("missing_summary_keys") or [] if item]
    )
    view_diagnostics_ok = not any(
        key in missing_row_counts for key in ("view_summary", "view_projections", "view_quality")
    )
    semiconductor_core_ok = not any(
        key in missing_row_counts
        for key in (
            "semiconductor_composition",
            "semiconductor_calculation_preflight",
            "semiconductor_calculation_readiness",
        )
    )
    normality_ok = normality.get("available") is True and "semiconductor_normality_diagnosis" not in missing_row_counts
    manifest_ok = bool(
        diagnostic_export_manifest.get("ok")
        or diagnostic_export_manifest.get("total_exported_file_count")
        or diagnostics.get("view_bundle_manifest_path")
    )
    requested_focus_ok = focus_status.get("ok")
    if requested_focus_ok is None:
        requested_focus_ok = True

    blocking_reasons: list[str] = []
    if not manifest_ok:
        blocking_reasons.append("diagnostic_manifest_missing")
    if not view_diagnostics_ok:
        blocking_reasons.append("view_diagnostics_missing")
    if not semiconductor_core_ok:
        blocking_reasons.append("semiconductor_core_diagnostics_missing")
    if not normality_ok:
        blocking_reasons.append("semiconductor_normality_diagnosis_missing")
    if requested_focus_ok is False:
        blocking_reasons.append("requested_diagnostic_focus_incomplete")
    if missing_artifacts:
        blocking_reasons.append("diagnostic_artifacts_missing")
    blocking_reasons = _dedupe_strings(blocking_reasons)

    if not blocking_reasons:
        status = "ready"
        ok = True
        recommended_action = "review_semiconductor_diagnostics_or_continue_modeling"
    elif requested_focus_ok is False:
        status = "requested_focus_incomplete"
        ok = False
        recommended_action = "export_view_bundle_for_missing_requested_diagnostic_focuses"
    elif not view_diagnostics_ok:
        status = "view_diagnostics_incomplete"
        ok = False
        recommended_action = "export_view_bundle_with_requested_views"
    elif not normality_ok:
        status = "semiconductor_normality_missing"
        ok = False
        recommended_action = "export_semiconductor_normality_diagnostics"
    else:
        status = "diagnostics_incomplete"
        ok = False
        recommended_action = "export_view_bundle_for_current_revision"

    return _drop_none_values(
        {
            "available": True,
            "ok": ok,
            "status": status,
            "blocking_reasons": blocking_reasons,
            "required_row_counts": required_row_counts,
            "row_counts": {key: row_counts.get(key) for key in required_row_counts if row_counts.get(key) is not None},
            "missing_row_counts": missing_row_counts,
            "required_artifacts": required_artifacts,
            "missing_artifacts": missing_artifacts,
            "optional_artifacts": optional_artifacts,
            "missing_optional_artifacts": missing_optional_artifacts,
            "view_diagnostics_ok": view_diagnostics_ok,
            "semiconductor_core_diagnostics_ok": semiconductor_core_ok,
            "semiconductor_normality_ok": normality_ok,
            "diagnostic_manifest_ok": manifest_ok,
            "requested_focus_ok": requested_focus_ok,
            "requested_focus_missing_csv_keys": focus_missing_csv,
            "requested_focus_missing_summary_keys": focus_missing_summary,
            "recommended_tool": "material_studio_model_export_view_bundle",
            "recommended_action": recommended_action,
            "needs_user_confirmation": False,
            "safe_to_call_without_confirmation": True,
            "payload_hint": _drop_none_values(
                {
                    "project_id": report.get("project_id"),
                    "revision": report.get("revision"),
                    "include_gui_snapshot": True,
                    "recommended_focuses": focus_plan.get("recommended_focuses") or report.get("recommended_diagnostic_focuses"),
                    "missing_row_counts": missing_row_counts,
                    "missing_artifacts": missing_artifacts,
                    "missing_optional_artifacts": missing_optional_artifacts,
                }
            ),
        }
    )


def _diagnostic_acceptance_summary(report: dict[str, Any]) -> dict[str, Any]:
    """Summarize whether exported diagnostics are sufficient for model-normality review."""

    diagnostics = report.get("diagnostics") if isinstance(report.get("diagnostics"), dict) else {}
    row_counts = diagnostics.get("view_bundle_row_counts") if isinstance(diagnostics.get("view_bundle_row_counts"), dict) else {}
    if not row_counts and isinstance(report.get("view_bundle_row_counts"), dict):
        row_counts = report["view_bundle_row_counts"]
    if not isinstance(row_counts, dict):
        row_counts = {}
    view_parameter_summary = (
        report.get("view_parameter_summary")
        if isinstance(report.get("view_parameter_summary"), dict)
        else _view_parameter_summary(report)
    )
    view_parameter_export_status = view_parameter_summary.get("export_status")
    view_parameter_export_needs_refresh = bool(view_parameter_summary.get("export_needs_refresh"))
    view_parameter_export_current = (
        True
        if view_parameter_export_status == "current"
        else False
        if view_parameter_export_needs_refresh
        else None
    )
    view_parameter_export_failure = (
        {
            "type": "view_parameter_export_not_current",
            "status": view_parameter_export_status,
            "expected_row_counts": view_parameter_summary.get("row_counts") or {},
            "exported_row_counts": view_parameter_summary.get("exported_row_counts") or {},
        }
        if view_parameter_export_needs_refresh
        else None
    )
    basic_requirements = {"view_summary": 1, "view_quality": 1, "view_projections": 1}
    observed_basic: dict[str, int] = {}
    basic_failures: list[dict[str, Any]] = []
    for key, minimum in basic_requirements.items():
        observed_raw = row_counts.get(key, 0)
        try:
            observed = int(observed_raw)
        except (TypeError, ValueError):
            observed = 0
        observed_basic[key] = observed
        if observed < minimum:
            basic_failures.append(
                {
                    "type": "row_count_below_minimum",
                    "key": key,
                    "expected_minimum": minimum,
                    "observed": observed_raw,
                }
            )

    semiconductor_gate = (
        report.get("semiconductor_diagnostic_gate")
        if isinstance(report.get("semiconductor_diagnostic_gate"), dict)
        else {}
    )
    semiconductor_failures: list[dict[str, Any]] = []
    if semiconductor_gate.get("available") is True and semiconductor_gate.get("ok") is False:
        for key in semiconductor_gate.get("missing_row_counts") or []:
            semiconductor_failures.append({"source": "semiconductor", "type": "missing_row_count", "key": key})
        for key in semiconductor_gate.get("missing_artifacts") or []:
            semiconductor_failures.append({"source": "semiconductor", "type": "missing_artifact", "key": key})

    diagnostic_export_manifest = (
        report.get("diagnostic_export_manifest")
        if isinstance(report.get("diagnostic_export_manifest"), dict)
        else {}
    )
    exported = bool(
        row_counts
        or diagnostic_export_manifest.get("ok")
        or diagnostic_export_manifest.get("total_exported_file_count")
        or diagnostics.get("view_bundle_manifest_path")
        or diagnostics.get("diagnostic_export_manifest_json")
    )
    view_parameter_failures = [view_parameter_export_failure] if view_parameter_export_failure else []
    failures = [*basic_failures, *semiconductor_failures, *view_parameter_failures]
    normality_gate = report.get("normality_gate") if isinstance(report.get("normality_gate"), dict) else {}
    visual_normality = (
        report.get("visual_normality_summary")
        if isinstance(report.get("visual_normality_summary"), dict)
        else {}
    )
    normality_signal_available = bool(
        report.get("normality")
        or normality_gate.get("status")
        or visual_normality.get("status")
        or report.get("semiconductor_normality_diagnosis")
    )
    if not exported:
        ok = False
        status = "diagnostics_not_exported"
    elif view_parameter_export_needs_refresh and not basic_failures and not semiconductor_failures:
        ok = False
        status = "diagnostics_stale_or_partial"
    elif failures:
        ok = False
        status = "diagnostics_failed"
    else:
        ok = True
        status = "diagnostics_ready"

    if view_parameter_export_needs_refresh:
        recommended_action = (
            view_parameter_summary.get("export_recommended_action")
            or "regenerate_view_bundle_for_current_view_parameter_summary"
        )
    elif not ok:
        recommended_action = "export_view_bundle_for_current_revision"
    else:
        recommended_action = "review_diagnostics_or_continue_modeling"

    return {
        "available": True,
        "ok": ok,
        "status": status,
        "can_check_model_normality": bool(ok is True and normality_signal_available),
        "normality_signal_available": normality_signal_available,
        "manifest_path": diagnostics.get("view_bundle_manifest_path"),
        "manifest_exists": _artifact_path_exists(diagnostics.get("view_bundle_manifest_path")),
        "diagnostic_export_manifest_ok": diagnostic_export_manifest.get("ok"),
        "file_count": diagnostic_export_manifest.get("total_file_count")
        or diagnostic_export_manifest.get("total_exported_file_count"),
        "row_count_total": _row_count_total(row_counts),
        "row_count_keys": sorted(str(key) for key in row_counts),
        "basic_view_requirements": basic_requirements,
        "basic_view_observed_row_counts": observed_basic,
        "basic_view_tables_ok": not basic_failures,
        "basic_view_table_failures": basic_failures,
        "view_parameter_export_status": view_parameter_export_status,
        "view_parameter_export_current": view_parameter_export_current,
        "view_parameter_export_needs_refresh": view_parameter_export_needs_refresh,
        "view_parameter_export_expected_row_counts": view_parameter_summary.get("row_counts") or {},
        "view_parameter_exported_row_counts": view_parameter_summary.get("exported_row_counts") or {},
        "view_parameter_export_failures": view_parameter_failures,
        "view_parameter_export_recommended_tool": view_parameter_summary.get("export_recommended_tool"),
        "view_parameter_export_recommended_action": view_parameter_summary.get("export_recommended_action"),
        "view_parameter_export_payload_hint": view_parameter_summary.get("export_payload_hint") or {},
        "semiconductor_diagnostic_gate_status": semiconductor_gate.get("status"),
        "semiconductor_diagnostic_gate_ok": semiconductor_gate.get("ok"),
        "failure_count": len(failures),
        "failures": failures,
        "recommended_tool": "material_studio_model_export_view_bundle",
        "recommended_action": recommended_action,
    }


def _row_count_total(row_counts: dict[str, Any]) -> int:
    total = 0
    for value in row_counts.values():
        try:
            total += int(value)
        except (TypeError, ValueError):
            continue
    return total


def _diagnostic_summary_available(report: dict[str, Any], dotted_key: str) -> bool:
    value: Any = report
    for part in dotted_key.split("."):
        if not isinstance(value, dict):
            return False
        value = value.get(part)
    if value is None:
        return False
    if isinstance(value, dict):
        if not value:
            return False
        if value.get("available") is False:
            return any(
                key in value
                for key in (
                    "model",
                    "status",
                    "warning",
                    "warnings",
                    "next_action",
                    "requires_materials_studio_review",
                )
            )
        return True
    if isinstance(value, list):
        return bool(value)
    return bool(value)


def _artifact_path_exists(value: Any) -> bool:
    if not value:
        return False
    try:
        return Path(str(value)).expanduser().exists()
    except (OSError, ValueError):
        return False


