def _numeric_row_count(value: Any) -> int:
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, int):
        return max(value, 0)
    if isinstance(value, float):
        return max(int(value), 0)
    if isinstance(value, str):
        try:
            return max(int(float(value)), 0)
        except ValueError:
            return 0
    return 0


def _diagnostic_export_manifest(report: dict[str, Any]) -> dict[str, Any]:
    """Group exported model/view diagnostics into stable client-facing categories."""

    diagnostics = report.get("diagnostics") if isinstance(report.get("diagnostics"), dict) else {}
    row_counts = diagnostics.get("view_bundle_row_counts") if isinstance(diagnostics.get("view_bundle_row_counts"), dict) else {}
    focus_status = (
        report.get("requested_diagnostic_focus_status")
        if isinstance(report.get("requested_diagnostic_focus_status"), dict)
        else {}
    )
    requested_focuses = (
        report.get("requested_diagnostic_focuses")
        if isinstance(report.get("requested_diagnostic_focuses"), list)
        else []
    )

    categories: dict[str, dict[str, Any]] = {}
    exported_file_keys: set[str] = set()
    exported_row_keys: set[str] = set()
    total_row_count = 0
    for category, entries in _DIAGNOSTIC_EXPORT_CATEGORIES.items():
        category_files: dict[str, str] = {}
        category_row_counts: dict[str, Any] = {}
        missing_file_keys: list[str] = []
        category_row_total = 0
        for file_key, row_key in entries:
            artifact = diagnostics.get(file_key)
            if _artifact_path_exists(artifact):
                category_files[file_key] = str(artifact)
                exported_file_keys.add(file_key)
            else:
                missing_file_keys.append(file_key)
            if row_key in row_counts:
                count = row_counts.get(row_key)
                category_row_counts[row_key] = count
                numeric_count = _numeric_row_count(count)
                category_row_total += numeric_count
                if row_key not in exported_row_keys:
                    exported_row_keys.add(row_key)
                    total_row_count += numeric_count
        categories[category] = {
            "available": bool(category_files or category_row_counts),
            "expected_file_count": len(entries),
            "available_file_count": len(category_files),
            "total_row_count": category_row_total,
            "files": category_files,
            "row_counts": category_row_counts,
            "available_file_keys": sorted(category_files),
            "missing_file_keys": missing_file_keys,
        }

    categories_with_files = [name for name, item in categories.items() if item["available_file_count"]]
    missing_requested_focuses = [
        str(item.get("focus"))
        for item in focus_status.get("focuses", [])
        if isinstance(item, dict) and item.get("ok") is False
    ]
    diagnostic_requested = bool(
        report.get("diagnostic_export_requested")
        or report.get("normality_check_requested")
        or requested_focuses
    )
    total_exported_file_count = len(exported_file_keys)
    has_any_export = bool(total_exported_file_count or total_row_count)
    if has_any_export:
        status = "exported_with_requested_focus_gaps" if focus_status.get("ok") is False else "exported"
    else:
        status = "missing" if diagnostic_requested else "not_requested"
    ok = status in {"exported", "not_requested"}
    return {
        "available": has_any_export,
        "ok": ok,
        "status": status,
        "diagnostic_export_requested": bool(report.get("diagnostic_export_requested")),
        "normality_check_requested": bool(report.get("normality_check_requested")),
        "requested_diagnostic_focus_count": len(requested_focuses),
        "requested_diagnostic_focus_ok": focus_status.get("ok"),
        "missing_requested_focuses": missing_requested_focuses,
        "requested_diagnostic_focus_missing_csv_keys": focus_status.get("missing_csv_keys") or [],
        "requested_diagnostic_focus_missing_summary_keys": focus_status.get("missing_summary_keys") or [],
        "view_bundle_manifest_path": diagnostics.get("view_bundle_manifest_path"),
        "view_bundle_manifest_exists": _artifact_path_exists(diagnostics.get("view_bundle_manifest_path")),
        "diagnostic_export_manifest_json_path": diagnostics.get("diagnostic_export_manifest_json"),
        "diagnostic_export_manifest_json_exists": _artifact_path_exists(
            diagnostics.get("diagnostic_export_manifest_json")
        ),
        "view_audit_report_path": diagnostics.get("view_audit_report_path"),
        "view_audit_report_exists": _artifact_path_exists(diagnostics.get("view_audit_report_path")),
        "report_json_path": diagnostics.get("report_json_path"),
        "report_json_exists": _artifact_path_exists(diagnostics.get("report_json_path")),
        "available_category_count": sum(1 for item in categories.values() if item["available"]),
        "total_exported_file_count": total_exported_file_count,
        "total_row_count": total_row_count,
        "categories_with_files": categories_with_files,
        "exported_file_keys": sorted(exported_file_keys),
        "categories": categories,
        "next_action": (
            "review_missing_requested_diagnostic_focus_exports"
            if status == "exported_with_requested_focus_gaps"
            else "export_view_bundle_for_current_revision"
            if status == "missing"
            else "diagnostic_exports_ready"
            if status == "exported"
            else "request_diagnostic_export_when_needed"
        ),
    }


def _modeling_issue_remediation(issue: dict[str, Any], report: dict[str, Any]) -> dict[str, Any]:
    """Return the safest next MCP action for a single indexed modeling issue."""

    category = str(issue.get("category") or "")
    code = str(issue.get("code") or "")
    evidence = issue.get("evidence") if isinstance(issue.get("evidence"), dict) else {}
    next_action = report.get("next_action_plan") if isinstance(report.get("next_action_plan"), dict) else {}
    readiness = report.get("live_readiness") if isinstance(report.get("live_readiness"), dict) else {}
    project_id = report.get("project_id")
    revision = report.get("revision")

    default_payload = (
        dict(next_action.get("payload_hint"))
        if isinstance(next_action.get("payload_hint"), dict)
        else {"project_id": project_id, "revision": revision}
    )
    recommended_tool = (
        next_action.get("recommended_tool")
        or readiness.get("recommended_tool")
        or "material_studio_live_project_status"
    )
    recommended_action = (
        next_action.get("recommended_action")
        or readiness.get("recommended_action")
        or "review_current_revision_before_next_modeling_step"
    )
    action_id = next_action.get("action_id") or "review_or_fix_current_revision"
    needs_user_confirmation = bool(next_action.get("needs_user_confirmation") or readiness.get("needs_user_confirmation"))
    payload_hint: dict[str, Any] = default_payload

    if category == "normality_gate" and code == "preview_not_hot_loaded":
        action_id = "execute_and_hotload_current_revision"
        recommended_tool = "material_studio_gui_apply_current_revision"
        recommended_action = "execute_current_revision_to_hotload_when_user_confirms"
        needs_user_confirmation = True
        payload_hint = {
            "project_id": project_id,
            "revision": revision,
            "execution_mode": ExecutionMode.EXECUTE.value,
            "open_in_gui": True,
            "take_snapshot": True,
            "export_view_audit": True,
        }
    elif category in {"gui", "live_readiness"} and "single_window" in code:
        action_id = "resolve_single_window_materials_studio_session"
        recommended_tool = "material_studio_gui_status"
        recommended_action = (
            "close_save_extra_matstudio_windows_or_activate_target_window_then_retry_live_session_preflight"
        )
        needs_user_confirmation = False
        payload_hint = {
            "project_id": project_id,
            "revision": revision,
            "require_single_window": True,
        }
    elif category == "gui" and code == "gui_loaded_revision_stale":
        action_id = "reload_current_revision_in_gui"
        recommended_tool = "material_studio_gui_open_structure"
        recommended_action = "reload_current_revision_in_existing_materials_studio_window"
        needs_user_confirmation = True
        payload_hint = {
            "project_id": project_id,
            "revision": revision,
            "take_snapshot": True,
            "export_view_audit": True,
            "reuse_existing_window_only": True,
        }
    elif category == "gui" and code.startswith("gui_visual_validation:"):
        action_id = "snapshot_current_revision"
        recommended_tool = "material_studio_gui_snapshot"
        recommended_action = "resnapshot_current_revision_and_review_visual_state"
        needs_user_confirmation = False
        payload_hint = {"project_id": project_id, "revision": revision}
    elif category in {"acceptance", "change_verification", "semiconductor_intent"}:
        action_id = "revise_model_or_acceptance"
        recommended_tool = "material_studio_live_modeling_request"
        recommended_action = (
            "revise_model_or_acceptance_then_reaudit"
            if category == "acceptance"
            else "regenerate_or_patch_model_to_match_intent"
        )
        needs_user_confirmation = False
        payload_hint = {"project_id": project_id, "issue_code": code}
    elif category in {"diagnostics", "view", "visual_review"}:
        action_id = "export_or_review_view_bundle"
        recommended_tool = "material_studio_model_export_view_bundle"
        recommended_action = (
            "export_requested_diagnostics_for_current_revision"
            if category == "diagnostics"
            else "review_view_bundle_or_adjust_model_geometry"
        )
        needs_user_confirmation = False
        payload_hint = {
            "project_id": project_id,
            "revision": revision,
            "missing_requested_focuses": evidence.get("missing_requested_focuses") or [],
        }
    elif category in {"semiconductor", "calculation_readiness"}:
        action_id = (
            "review_semiconductor_calculation_readiness"
            if category == "calculation_readiness"
            else "review_semiconductor_diagnostics"
        )
        recommended_tool = "material_studio_live_project_status"
        recommended_action = (
            "review_calculation_preflight_before_expensive_job"
            if category == "calculation_readiness"
            else "review_semiconductor_diagnostics_before_calculation"
        )
        needs_user_confirmation = False
        payload_hint = {"project_id": project_id, "revision": revision}
    elif category == "live_delivery":
        action_id = next_action.get("action_id") or "review_live_delivery_failure"
        recommended_tool = recommended_tool or "material_studio_live_project_status"
        recommended_action = recommended_action or "review_live_delivery_failure_before_next_step"
        payload_hint = default_payload

    payload_hint = _drop_none_values(payload_hint)
    return _drop_none_values(
        {
            "action_id": action_id,
            "recommended_tool": recommended_tool,
            "recommended_action": recommended_action,
            "needs_user_confirmation": needs_user_confirmation,
            "safe_to_call_without_confirmation": not needs_user_confirmation,
            "payload_hint": payload_hint,
        }
    )


def _modeling_issue_index(report: dict[str, Any]) -> dict[str, Any]:
    """Return a compact issue index for automated normality review."""

    issues: list[dict[str, Any]] = []

    def add_issue(
        *,
        category: str,
        severity: str,
        code: str,
        message: str | None = None,
        source: str | None = None,
        evidence: dict[str, Any] | None = None,
    ) -> None:
        issue = {
            "category": category,
            "severity": severity,
            "code": code,
            "message": message or code,
            "source": source,
            "evidence": evidence or {},
        }
        issue.update(_modeling_issue_remediation(issue, report))
        issues.append(_drop_none_values(issue))

    for error in report.get("health_errors") or []:
        add_issue(
            category="modeling_health",
            severity="error",
            code="modeling_health_error",
            message=str(error),
            source="modeling_health.errors",
        )
    for warning in report.get("health_verdict_warnings") or report.get("health_warnings") or []:
        add_issue(
            category="modeling_health",
            severity="warning",
            code="modeling_health_warning",
            message=str(warning),
            source="modeling_health.warnings",
        )

    normality_gate = report.get("normality_gate") if isinstance(report.get("normality_gate"), dict) else {}
    for reason in normality_gate.get("must_not_claim_normal_reasons") or []:
        add_issue(
            category="normality_gate",
            severity="blocker",
            code=str(reason),
            source="normality_gate.must_not_claim_normal_reasons",
            evidence={
                "status": normality_gate.get("status"),
                "can_claim_model_normal": normality_gate.get("can_claim_model_normal"),
            },
        )

    readiness = report.get("live_readiness") if isinstance(report.get("live_readiness"), dict) else {}
    for reason in readiness.get("blocking_reasons") or []:
        add_issue(
            category="live_readiness",
            severity="blocker",
            code=str(reason),
            source="live_readiness.blocking_reasons",
        )
    for reason in readiness.get("calculation_blocking_reasons") or []:
        add_issue(
            category="calculation_readiness",
            severity="warning",
            code=str(reason),
            source="live_readiness.calculation_blocking_reasons",
        )
    for reason in readiness.get("review_reasons") or []:
        add_issue(
            category="review",
            severity="warning",
            code=str(reason),
            source="live_readiness.review_reasons",
        )
    for reason in readiness.get("visual_review_reasons") or []:
        add_issue(
            category="visual_review",
            severity="warning",
            code=str(reason),
            source="live_readiness.visual_review_reasons",
        )

    acceptance = report.get("acceptance_review") if isinstance(report.get("acceptance_review"), dict) else {}
    for check in acceptance.get("failed_checks") or []:
        add_issue(
            category="acceptance",
            severity="blocker",
            code=str(check),
            source="acceptance_review.failed_checks",
            evidence={"next_action": acceptance.get("next_action")},
        )

    view_review = report.get("view_review") if isinstance(report.get("view_review"), dict) else {}
    if view_review.get("available") and view_review.get("ok") is False:
        add_issue(
            category="view",
            severity="warning",
            code=f"view_status:{view_review.get('status')}",
            source="view_review.status",
            evidence={"next_action": view_review.get("next_action")},
        )
    for flag in view_review.get("calculation_risk_flags") or []:
        add_issue(
            category="view",
            severity="warning",
            code=str(flag),
            source="view_review.calculation_risk_flags",
        )
    for flag in view_review.get("nonblocking_visual_flags") or []:
        add_issue(
            category="view",
            severity="info",
            code=str(flag),
            source="view_review.nonblocking_visual_flags",
        )

    gui = report.get("gui") if isinstance(report.get("gui"), dict) else {}
    if gui.get("single_window_policy_ok") is False:
        for reason in gui.get("single_window_violation_reasons") or ["single_window_policy_violation"]:
            add_issue(
                category="gui",
                severity="blocker",
                code=str(reason),
                source="gui.single_window_violation_reasons",
            )
    if gui.get("loaded_current_revision") is False:
        add_issue(
            category="gui",
            severity="blocker",
            code="gui_loaded_revision_stale",
            source="gui.loaded_current_revision",
        )
    if gui.get("visual_validation") not in {None, "passed"}:
        add_issue(
            category="gui",
            severity="warning",
            code=f"gui_visual_validation:{gui.get('visual_validation')}",
            source="gui.visual_validation",
        )

    semiconductor = report.get("semiconductor_review") if isinstance(report.get("semiconductor_review"), dict) else {}
    if semiconductor.get("available") and semiconductor.get("ok") is False:
        add_issue(
            category="semiconductor",
            severity="warning",
            code=f"semiconductor_status:{semiconductor.get('status')}",
            source="semiconductor_review.status",
        )
    for flag in semiconductor.get("risk_flags") or []:
        add_issue(
            category="semiconductor",
            severity="warning",
            code=str(flag),
            source="semiconductor_review.risk_flags",
        )

    change_verification = (
        report.get("change_verification")
        if isinstance(report.get("change_verification"), dict)
        else {}
    )
    if change_verification.get("available") and change_verification.get("ok") is False:
        add_issue(
            category="change_verification",
            severity="blocker",
            code=str(change_verification.get("status") or "change_verification_failed"),
            source="change_verification.status",
        )

    semiconductor_intent = (
        report.get("semiconductor_intent")
        if isinstance(report.get("semiconductor_intent"), dict)
        else {}
    )
    if semiconductor_intent.get("available") and semiconductor_intent.get("ok") is False:
        for reason in semiconductor_intent.get("failure_reasons") or ["semiconductor_intent_failed"]:
            add_issue(
                category="semiconductor_intent",
                severity="blocker",
                code=str(reason),
                source="semiconductor_intent.failure_reasons",
            )

    diagnostic_manifest = (
        report.get("diagnostic_export_manifest")
        if isinstance(report.get("diagnostic_export_manifest"), dict)
        else {}
    )
    if diagnostic_manifest.get("ok") is False:
        add_issue(
            category="diagnostics",
            severity="warning",
            code=str(diagnostic_manifest.get("status") or "diagnostic_export_manifest_incomplete"),
            source="diagnostic_export_manifest.status",
            evidence={
                "missing_requested_focuses": diagnostic_manifest.get("missing_requested_focuses") or [],
                "missing_csv_keys": diagnostic_manifest.get("requested_diagnostic_focus_missing_csv_keys") or [],
            },
        )

    live_delivery = report.get("live_delivery") if isinstance(report.get("live_delivery"), dict) else {}
    for failure in live_delivery.get("required_failures") or []:
        add_issue(
            category="live_delivery",
            severity="blocker",
            code=str(failure),
            source="live_delivery.required_failures",
        )

    deduped: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    severity_rank = {"blocker": 0, "error": 1, "warning": 2, "info": 3}
    for issue in issues:
        key = (str(issue.get("category")), str(issue.get("severity")), str(issue.get("code")))
        if key in seen:
            continue
        seen.add(key)
        deduped.append(issue)
    deduped.sort(key=lambda item: (severity_rank.get(str(item.get("severity")), 99), str(item.get("category")), str(item.get("code"))))

    counts_by_severity: dict[str, int] = {}
    counts_by_category: dict[str, int] = {}
    for issue in deduped:
        severity = str(issue.get("severity"))
        category = str(issue.get("category"))
        counts_by_severity[severity] = counts_by_severity.get(severity, 0) + 1
        counts_by_category[category] = counts_by_category.get(category, 0) + 1
    blocker_count = counts_by_severity.get("blocker", 0) + counts_by_severity.get("error", 0)
    warning_count = counts_by_severity.get("warning", 0)
    if blocker_count:
        status = "blocked"
        next_action = "fix_blocking_modeling_issues_before_claiming_normal"
    elif warning_count:
        status = "review_required"
        next_action = "review_modeling_issue_index_before_calculation_or_public_use"
    else:
        status = "passed"
        next_action = "available_checks_have_no_indexed_issues"

    diagnostics = report.get("diagnostics") if isinstance(report.get("diagnostics"), dict) else {}
    return {
        "available": True,
        "ok": blocker_count == 0,
        "status": status,
        "issue_count": len(deduped),
        "blocker_count": blocker_count,
        "warning_count": warning_count,
        "info_count": counts_by_severity.get("info", 0),
        "counts_by_severity": counts_by_severity,
        "counts_by_category": counts_by_category,
        "top_issue_codes": [str(issue.get("code")) for issue in deduped[:10]],
        "issues": deduped,
        "modeling_issue_index_csv_path": diagnostics.get("modeling_issue_index_csv"),
        "modeling_issue_index_csv_exists": _artifact_path_exists(diagnostics.get("modeling_issue_index_csv")),
        "modeling_issue_index_json_path": diagnostics.get("modeling_issue_index_json"),
        "modeling_issue_index_json_exists": _artifact_path_exists(diagnostics.get("modeling_issue_index_json")),
        "next_action": next_action,
    }


def _modeling_issue_index_csv_rows(index: dict[str, Any]) -> list[dict[str, Any]]:
    """Return one CSV row per indexed modeling issue."""

    issues = index.get("issues") if isinstance(index.get("issues"), list) else []
    rows: list[dict[str, Any]] = []
    for position, issue in enumerate(issues, start=1):
        if not isinstance(issue, dict):
            continue
        rows.append(
            {
                "position": position,
                "severity": issue.get("severity"),
                "category": issue.get("category"),
                "code": issue.get("code"),
                "message": issue.get("message"),
                "source": issue.get("source"),
                "action_id": issue.get("action_id"),
                "recommended_tool": issue.get("recommended_tool"),
                "recommended_action": issue.get("recommended_action"),
                "needs_user_confirmation": issue.get("needs_user_confirmation"),
                "safe_to_call_without_confirmation": issue.get("safe_to_call_without_confirmation"),
                "payload_hint": _csv_json_value(issue.get("payload_hint") or {}),
                "evidence": _csv_json_value(issue.get("evidence") or {}),
            }
        )
    return rows


def _write_modeling_issue_index_csv(path: Path, index: dict[str, Any]) -> int:
    """Write the issue index as an external-inspection CSV table."""

    fieldnames = [
        "position",
        "severity",
        "category",
        "code",
        "message",
        "source",
        "action_id",
        "recommended_tool",
        "recommended_action",
        "needs_user_confirmation",
        "safe_to_call_without_confirmation",
        "payload_hint",
        "evidence",
    ]
    rows = _modeling_issue_index_csv_rows(index)
    with path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)
    return len(rows)


