def _normalized_modeling_health_for_report(response: dict[str, Any]) -> dict[str, Any]:
    """Add current health fields to legacy persisted health payloads."""

    health = response.get("modeling_health") if isinstance(response.get("modeling_health"), dict) else {}
    if not health or isinstance(health.get("verdict_warnings"), list):
        return health

    normalized = dict(health)
    checks = dict(normalized.get("checks") or {})
    warnings = [str(item) for item in normalized.get("warnings") or []]
    try:
        legacy_verdict_warning_count = int(checks.get("verdict_warning_count", len(warnings)) or 0)
    except (TypeError, ValueError):
        legacy_verdict_warning_count = len(warnings)

    candidates = [warning for warning in warnings if not _legacy_health_warning_is_view_projection(warning)]
    if _current_gui_revision_verified_for_response(response):
        candidates = [warning for warning in candidates if not _legacy_health_warning_is_open_activation(warning)]
    if legacy_verdict_warning_count >= 0 and len(candidates) > legacy_verdict_warning_count:
        candidates = candidates[-legacy_verdict_warning_count:] if legacy_verdict_warning_count else []

    normalized["verdict_warnings"] = candidates
    checks["verdict_warning_count"] = len(candidates)
    normalized["checks"] = checks
    if not normalized.get("errors"):
        execution_mode = normalized.get("execution_mode") or response.get("execution_mode")
        if execution_mode == ExecutionMode.EXECUTE.value:
            normalized["verdict"] = "passed_with_warnings" if candidates else "passed"
        elif execution_mode == ExecutionMode.PREVIEW.value:
            normalized["verdict"] = "ready_with_warnings" if candidates else "ready_for_review"
    return normalized


def _legacy_health_warning_is_view_projection(warning: str) -> bool:
    return "nearly overlapping in this 2d projection" in warning.lower()


def _legacy_health_warning_is_open_activation(warning: str) -> bool:
    return "opened Materials Studio window was not confirmed active" in warning


def _current_gui_revision_verified_for_response(response: dict[str, Any]) -> bool:
    persisted = response.get("persisted_modeling_report") if isinstance(response.get("persisted_modeling_report"), dict) else {}
    persisted_current = persisted.get("gui_current_revision") if isinstance(persisted.get("gui_current_revision"), dict) else {}
    if persisted_current.get("status") == "current_and_visually_verified":
        return True
    if persisted_current.get("window_identity_verification") == "verified":
        return True
    if persisted_current.get("matching_window_identity_verification") == "verified":
        return True

    gui_open = response.get("gui_open") if isinstance(response.get("gui_open"), dict) else None
    consistency = _gui_current_revision_consistency(response, gui_open)
    return any(
        consistency.get(key) == "verified"
        for key in (
            "foreground_window_identity_verification",
            "selected_window_identity_verification",
            "matching_window_identity_verification",
        )
    )


def _build_modeling_report(response: dict[str, Any]) -> dict[str, Any]:
    """Return a compact display-ready summary for live modeling clients."""

    health = _normalized_modeling_health_for_report(response)
    response["modeling_health"] = health
    execution_mode = response.get("execution_mode", health.get("execution_mode"))
    result = response.get("result") if isinstance(response.get("result"), dict) else {}
    if not result and isinstance(response.get("result_metadata"), dict):
        result = response["result_metadata"]
    planned_outputs = response.get("planned_outputs") or {}
    structure = planned_outputs.get("structure")
    structure_exists = bool(structure and Path(str(structure)).expanduser().exists())
    structure_artifact_validation = (
        response.get("structure_artifact_validation")
        if isinstance(response.get("structure_artifact_validation"), dict)
        else None
    )
    calculation_preview = _compact_calculation_preview(
        response.get("calculation_preview")
    )
    gui_status = response.get("gui_status") or {}
    gui_open = response.get("gui_open") if isinstance(response.get("gui_open"), dict) else None
    bundle_files = response.get("view_bundle_files") or response.get("files") or {}
    audit = response.get("view_audit") if isinstance(response.get("view_audit"), dict) else None
    view_selection = (
        audit.get("view_selection")
        if isinstance(audit, dict) and isinstance(audit.get("view_selection"), dict)
        else response.get("view_selection")
        if isinstance(response.get("view_selection"), dict)
        else None
    )
    if view_selection is not None:
        response["view_selection"] = view_selection
    gui_summary = _gui_report_summary(response, gui_status=gui_status, gui_open=gui_open)
    report_ok = bool(response.get("ok", health.get("ok", True)))
    change_validation = _change_validation_summary(response.get("revision_delta"), audit)
    inspection = _inspection_summary_from_audit(audit, response.get("view_bundle_row_counts") or response.get("row_counts"))
    acceptance_review = _acceptance_review(response.get("acceptance"), response)
    semiconductor_review = _semiconductor_review_from_audit(audit)
    view_review = _view_review_from_audit(audit, gui_summary)
    trusted_clean_view_replay = _trusted_clean_view_replay_summary(
        response,
        view_review,
    )
    response["trusted_clean_view_replay"] = trusted_clean_view_replay
    requested_diagnostic_focuses = response.get("requested_diagnostic_focuses")
    if not isinstance(requested_diagnostic_focuses, list):
        requested_diagnostic_focuses = _requested_diagnostic_focuses_from_text(response.get("user_request"))
    response["requested_diagnostic_focuses"] = requested_diagnostic_focuses
    semiconductor_template_profile = _semiconductor_template_profile_for_response(response)
    semiconductor_template_default_focuses = (
        list(semiconductor_template_profile.get("default_diagnostic_focuses") or [])
        if semiconductor_template_profile
        else []
    )
