def _report_artifact_path_with_source(report: dict[str, Any], key: str) -> tuple[Any, str]:
    """Resolve a declared report artifact, preferring a path that currently exists."""

    candidates: list[tuple[str, Any]] = [("top_level", report.get(key))]
    for source in ("diagnostics", "artifacts"):
        section = report.get(source) if isinstance(report.get(source), dict) else {}
        candidates.append((source, section.get(key)))

    first_declared: tuple[Any, str] | None = None
    for source, value in candidates:
        if not value:
            continue
        if first_declared is None:
            first_declared = (value, source)
        if _artifact_path_exists(value):
            return value, source
    if first_declared is not None:
        return first_declared
    return None, "missing"


def _gui_current_revision_status_from_report(report: dict[str, Any]) -> dict[str, Any]:
    """Return a compact trust check for whether Materials Studio shows this revision."""

    gui = report.get("gui") if isinstance(report.get("gui"), dict) else {}
    structure = report.get("structure") if isinstance(report.get("structure"), dict) else {}
    view_audit_report_path, view_audit_report_path_source = _report_artifact_path_with_source(
        report,
        "view_audit_report_path",
    )
    report_json_path, report_json_path_source = _report_artifact_path_with_source(
        report,
        "report_json_path",
    )
    view_bundle_manifest_path, view_bundle_manifest_path_source = _report_artifact_path_with_source(
        report,
        "view_bundle_manifest_path",
    )
    artifact_evidence = {
        "view_audit_report_path": view_audit_report_path,
        "view_audit_report_exists": _artifact_path_exists(view_audit_report_path),
        "view_audit_report_path_source": view_audit_report_path_source,
        "report_json_path": report_json_path,
        "report_json_exists": _artifact_path_exists(report_json_path),
        "report_json_path_source": report_json_path_source,
        "view_bundle_manifest_path": view_bundle_manifest_path,
        "view_bundle_manifest_exists": _artifact_path_exists(view_bundle_manifest_path),
        "view_bundle_manifest_path_source": view_bundle_manifest_path_source,
    }
    if not gui:
        return {
            "available": False,
            "reason": "no_gui_report",
            "status": "unknown",
            "loaded_current_revision": None,
            "needs_reload": None,
            "needs_snapshot": None,
            **artifact_evidence,
        }

    hot_loaded = bool(gui.get("hot_loaded"))
    loaded_current = gui.get("loaded_current_revision")
    visual_validation = gui.get("visual_validation")
    selected_matches = gui.get("selected_window_matches_current")
    foreground_matches = gui.get("foreground_window_matches_current")
    window_identity = _window_identity_verification(gui)
    window_management = gui.get("window_management") if isinstance(gui.get("window_management"), dict) else {}
    single_window = _single_window_policy_summary(gui, window_management)
    single_window_policy_ok = single_window.get("single_window_policy_ok")
    single_window_violation_reasons = single_window.get("single_window_violation_reasons") or []
    needs_single_window_resolution = single_window_policy_ok is False
    target_window_loaded = bool(
        gui.get("matching_window_count")
        or gui.get("target_window_matched_project_window") is True
        or window_management.get("matched_project_window") is True
    )
    target_window_is_selected = window_management.get("target_window_is_selected")
    target_window_is_visible = window_management.get("target_window_is_visible")
    target_window_is_minimized = window_management.get("target_window_is_minimized")
    target_window_foreground_observed = window_management.get("target_window_foreground_observed")
    target_window_is_foreground = window_management.get("target_window_is_foreground")
    activation_required_before_capture_or_input = window_management.get(
        "activation_required_before_capture_or_input"
    )
    target_window_identity_verified = bool(
        target_window_loaded
        and (
            gui.get("matching_window_identity_verification") == "verified"
            or window_management.get("matching_window_identity_verification") == "verified"
        )
    )
    stale_reasons = list(gui.get("stale_reasons") or [])
    if selected_matches is False:
        stale_reasons.extend(str(item) for item in gui.get("selected_window_stale_reasons") or [])
    if foreground_matches is False:
        stale_reasons.extend(str(item) for item in gui.get("foreground_window_stale_reasons") or [])
    stale_reasons = _dedupe_strings([str(item) for item in stale_reasons if item])

    needs_activation = bool(
        target_window_loaded
        and loaded_current is not False
        and (
            selected_matches is False
            or foreground_matches is False
            or target_window_is_selected is False
            or window_management.get("needs_activation") is True
            or activation_required_before_capture_or_input is True
        )
    )
    needs_reload = bool(
        not hot_loaded
        or loaded_current is False
        or (
            not target_window_loaded
            and (
                selected_matches is False
                or foreground_matches is False
            )
        )
    )
    needs_snapshot = bool(hot_loaded and visual_validation in {"snapshot_missing", "not_available"})
    needs_visual_review = bool(hot_loaded and visual_validation in {"warning", "failed"})
    if needs_single_window_resolution:
        status = "single_window_policy_review"
    elif not hot_loaded:
        status = "not_hot_loaded"
    elif needs_activation:
        status = "current_but_not_active"
    elif needs_reload:
        status = "stale_or_not_current"
    elif visual_validation == "passed":
        status = "current_and_visually_verified"
    elif needs_snapshot:
        status = "current_but_snapshot_missing"
    elif visual_validation in {"warning", "failed"}:
        status = f"current_with_visual_{visual_validation}"
    else:
        status = "current_revision_loaded"

    if needs_single_window_resolution:
        recommended_tool = "material_studio_gui_status"
        recommended_action = "close_save_extra_matstudio_windows_then_reaudit_current_revision"
    elif needs_activation:
        recommended_tool = "material_studio_gui_activate"
        recommended_action = (
            "restore_and_activate_current_revision_window"
            if target_window_is_minimized is True
            else "activate_current_revision_window"
        )
    elif needs_reload:
        recommended_tool = "material_studio_gui_open_structure" if structure.get("exists") else "material_studio_gui_apply_current_revision"
        recommended_action = "reload_current_revision_in_gui_and_snapshot"
    elif needs_snapshot:
        recommended_tool = "material_studio_gui_snapshot"
        recommended_action = "capture_gui_snapshot_for_current_revision"
    elif needs_visual_review:
        recommended_tool = "material_studio_gui_snapshot"
        recommended_action = "recapture_or_review_gui_snapshot_for_current_revision"
    else:
        recommended_tool = "material_studio_live_modeling_request"
        recommended_action = "continue_next_model_edit"

    if target_window_identity_verified and window_identity in {"unverified", "unknown", None}:
        window_identity = "verified"
    if target_window_identity_verified and not stale_reasons and selected_matches is False and foreground_matches is False:
        # The current revision is already verified in a matching wrapper window.
        # Keep activation guidance, but avoid treating the revision identity itself as unverified noise.
        stale_reasons = list(stale_reasons)

    payload_hint: dict[str, Any] = {}
    if recommended_tool == "material_studio_gui_open_structure":
        payload_hint = {
            "structure_path": structure.get("path"),
            "project_id": report.get("project_id"),
            "revision": report.get("revision"),
            "take_snapshot": True,
            "export_view_audit": True,
            "reuse_existing_window_only": True,
        }
    elif recommended_tool == "material_studio_gui_activate":
        payload_hint = {
            "project_id": report.get("project_id"),
            "revision": report.get("revision"),
            "take_snapshot": True,
        }
    elif recommended_tool == "material_studio_gui_apply_current_revision":
        payload_hint = {
            "project_id": report.get("project_id"),
            "execution_mode": ExecutionMode.EXECUTE.value,
            "open_in_gui": True,
            "take_snapshot": True,
            "export_view_audit": True,
        }
    elif recommended_tool == "material_studio_gui_snapshot":
        payload_hint = {
            "project_id": report.get("project_id"),
            "revision": report.get("revision"),
            "label": "current_revision_visual_review" if needs_visual_review else "current_revision",
        }

    return {
        "available": True,
        "status": status,
        "hot_loaded": hot_loaded,
        "loaded_current_revision": loaded_current,
        "needs_reload": needs_reload,
        "needs_activation": needs_activation,
        "needs_snapshot": needs_snapshot,
        "needs_single_window_resolution": needs_single_window_resolution,
        **single_window,
        "visual_validation": visual_validation,
        "snapshot_path": gui.get("snapshot_path"),
        "opened_structure_path": gui.get("opened_structure_path"),
        "expected_structure_path": structure.get("path") or gui.get("expected_structure_path"),
        **artifact_evidence,
        "open_identity_verification": gui.get("open_identity_verification"),
        "window_identity_verification": window_identity,
        "matching_window_count": gui.get("matching_window_count"),
        "matching_window_identity_verification": gui.get("matching_window_identity_verification"),
        "matching_windows": gui.get("matching_windows") or [],
        "target_window_matched_project_window": gui.get("target_window_matched_project_window"),
        "target_window_matching_window_count": gui.get("target_window_matching_window_count"),
        "target_window_handle": gui.get("target_window_handle"),
        "target_window_title": gui.get("target_window_title"),
        "target_window_fallback_used": gui.get("target_window_fallback_used"),
        "target_window_loaded": target_window_loaded,
        "target_window_is_selected": target_window_is_selected,
        "target_window_is_visible": target_window_is_visible,
        "target_window_is_minimized": target_window_is_minimized,
        "target_window_foreground_observed": target_window_foreground_observed,
        "target_window_is_foreground": target_window_is_foreground,
        "activation_required_before_capture_or_input": activation_required_before_capture_or_input,
        "activation_reasons": window_management.get("activation_reasons") or [],
        "target_window_identity_verified": target_window_identity_verified,
        "window_management": window_management or None,
        "window_management_status": window_management.get("status"),
        "window_management_recommended_tool": window_management.get("recommended_tool"),
        "window_management_recommended_action": window_management.get("recommended_action"),
        "window_management_ready_for_next_live_edit": window_management.get("ready_for_next_live_edit"),
        "window_management_can_hotload_without_new_window": window_management.get("can_hotload_without_new_window"),
        "window_management_can_apply_current_revision_without_new_window": window_management.get(
            "can_apply_current_revision_without_new_window"
        ),
        "window_management_needs_reload": window_management.get("needs_reload"),
        "window_management_needs_activation": window_management.get("needs_activation"),
        "window_management_needs_snapshot": window_management.get("needs_snapshot"),
        "window_management_payload_hint": window_management.get("payload_hint") or {},
        "window_management_warning_count": len(window_management.get("warnings") or []),
        "window_management_warnings": window_management.get("warnings") or [],
        "selected_window_matches_current": selected_matches,
        "selected_window_identity_verification": gui.get("selected_window_identity_verification"),
        "foreground_window_matches_current": foreground_matches,
        "foreground_window_identity_verification": gui.get("foreground_window_identity_verification"),
        "stale_reason_count": len(stale_reasons),
        "stale_reasons": stale_reasons,
        "recommended_tool": recommended_tool,
        "recommended_action": recommended_action,
        "payload_hint": _drop_none_values(payload_hint),
    }


