def _live_gui_window_binding_summary(report: dict[str, Any]) -> dict[str, Any]:
    """Return the current Materials Studio window binding for live clients."""

    gui = report.get("gui") if isinstance(report.get("gui"), dict) else {}
    gui_current = (
        report.get("gui_current_revision")
        if isinstance(report.get("gui_current_revision"), dict)
        else {}
    )
    mcp_readiness = (
        report.get("mcp_client_readiness")
        if isinstance(report.get("mcp_client_readiness"), dict)
        else {}
    )
    live_gui_acceptance = (
        report.get("live_gui_acceptance")
        if isinstance(report.get("live_gui_acceptance"), dict)
        else {}
    )
    live_hotload_preflight = (
        report.get("live_hotload_preflight")
        if isinstance(report.get("live_hotload_preflight"), dict)
        else {}
    )
    gui_window_management = (
        gui.get("window_management") if isinstance(gui.get("window_management"), dict) else {}
    )
    if not any((gui, gui_current, mcp_readiness, live_gui_acceptance, live_hotload_preflight)):
        return {}

    single_window_policy_ok = mcp_readiness.get("single_window_policy_ok")
    if single_window_policy_ok is None:
        single_window_policy_ok = gui_current.get("single_window_policy_ok")
    if single_window_policy_ok is None:
        single_window_policy_ok = gui.get("single_window_policy_ok")
    if single_window_policy_ok is None:
        single_window_policy_ok = live_gui_acceptance.get("single_window_policy_ok")

    single_window_violation_reasons = _dedupe_strings(
        [
            str(reason)
            for source in (gui_current, gui, live_gui_acceptance)
            for reason in (source.get("single_window_violation_reasons") or [])
            if reason
        ]
    )
    target_window_handle = mcp_readiness.get("gui_target_window_handle")
    if target_window_handle is None:
        target_window_handle = gui_current.get("target_window_handle")
    if target_window_handle is None:
        target_window_handle = gui.get("target_window_handle")
    target_window_title = mcp_readiness.get("gui_target_window_title")
    if target_window_title is None:
        target_window_title = gui_current.get("target_window_title")
    if target_window_title is None:
        target_window_title = gui.get("target_window_title")
    target_window_is_selected = mcp_readiness.get("gui_target_window_is_selected")
    if target_window_is_selected is None:
        target_window_is_selected = gui_current.get("target_window_is_selected")
    target_window_is_visible = _first_not_none(
        mcp_readiness.get("gui_target_window_is_visible"),
        gui_current.get("target_window_is_visible"),
        gui.get("window_management_target_window_is_visible"),
    )
    target_window_is_minimized = _first_not_none(
        mcp_readiness.get("gui_target_window_is_minimized"),
        gui_current.get("target_window_is_minimized"),
        gui.get("window_management_target_window_is_minimized"),
    )
    target_window_foreground_observed = _first_not_none(
        mcp_readiness.get("gui_target_window_foreground_observed"),
        gui_current.get("target_window_foreground_observed"),
        gui.get("window_management_target_window_foreground_observed"),
    )
    target_window_is_foreground = _first_not_none(
        mcp_readiness.get("gui_target_window_is_foreground"),
        gui_current.get("target_window_is_foreground"),
        gui.get("window_management_target_window_is_foreground"),
    )
    activation_required_before_capture_or_input = _first_not_none(
        mcp_readiness.get("gui_activation_required_before_capture_or_input"),
        gui_current.get("activation_required_before_capture_or_input"),
        gui.get("window_management_activation_required_before_capture_or_input"),
    )
    activation_reasons = _dedupe_strings(
        [
            str(reason)
            for source in (gui_current, gui_window_management)
            for reason in (source.get("activation_reasons") or [])
            if reason
        ]
    )
    target_window_found = mcp_readiness.get("gui_target_window_found")
    if target_window_found is None:
        target_window_found = bool(
            target_window_handle is not None
            or gui_current.get("target_window_matched_project_window") is True
            or gui.get("target_window_matched_project_window") is True
        )

    current_revision_loaded = mcp_readiness.get("current_revision_loaded_in_gui")
    if current_revision_loaded is None:
        current_revision_loaded = live_hotload_preflight.get("current_revision_loaded")
    if current_revision_loaded is None:
        current_revision_loaded = gui_current.get("loaded_current_revision")
    if current_revision_loaded is None:
        current_revision_loaded = gui.get("loaded_current_revision")

    status = gui_current.get("status")
    if not status and live_gui_acceptance.get("available"):
        status = (
            "current_revision_bound_to_target_window"
            if live_gui_acceptance.get("ok") is True
            else "live_gui_acceptance_review"
        )
    if not status:
        status = "unknown"
    gui_preflight_required = bool(mcp_readiness.get("gui_preflight_required"))
    if gui_preflight_required:
        status = "gui_preflight_required"
    visible_followup_ready = mcp_readiness.get("visible_followup_ready")
    visible_followup_status = mcp_readiness.get("visible_followup_status")
    visible_followup_blocking_reasons = mcp_readiness.get("visible_followup_blocking_reasons")
    visible_followup_recommended_tool = mcp_readiness.get("visible_followup_recommended_tool")
    visible_followup_recommended_action = mcp_readiness.get("visible_followup_recommended_action")
    visible_followup_payload_hint = mcp_readiness.get("visible_followup_payload_hint")
    ready_for_next_live_edit = _first_not_none(
        live_gui_acceptance.get("can_continue_same_window_modeling"),
        visible_followup_ready,
        mcp_readiness.get("ready_for_live_edit"),
    )
    if activation_required_before_capture_or_input is True:
        ready_for_next_live_edit = False

    return _drop_none_values(
        {
            "available": True,
            "status": status,
            "same_window_required": mcp_readiness.get("must_reuse_existing_gui_window"),
            "auto_launch_allowed": mcp_readiness.get("auto_launch_during_hotload_allowed"),
            "single_window_policy_ok": single_window_policy_ok,
            "single_window_violation_reasons": single_window_violation_reasons,
            "process_count": mcp_readiness.get("gui_process_count"),
            "window_count": mcp_readiness.get("gui_window_count"),
            "target_window_found": target_window_found,
            "target_window_handle": target_window_handle,
            "target_window_title": target_window_title,
            "target_window_is_selected": target_window_is_selected,
            "target_window_is_visible": target_window_is_visible,
            "target_window_is_minimized": target_window_is_minimized,
            "target_window_foreground_observed": target_window_foreground_observed,
            "target_window_is_foreground": target_window_is_foreground,
            "activation_required_before_capture_or_input": activation_required_before_capture_or_input,
            "activation_reasons": activation_reasons,
            "target_window_loaded": gui_current.get("target_window_loaded"),
            "target_window_matched_project_window": gui_current.get("target_window_matched_project_window"),
            "target_window_fallback_used": gui_current.get("target_window_fallback_used"),
            "current_revision_loaded": current_revision_loaded,
            "needs_reload": gui_current.get("needs_reload"),
            "needs_activation": _first_not_none(
                gui_current.get("needs_activation"),
                mcp_readiness.get("gui_target_window_needs_activation"),
                activation_required_before_capture_or_input,
            ),
            "needs_snapshot": gui_current.get("needs_snapshot"),
            "needs_single_window_resolution": gui_current.get("needs_single_window_resolution"),
            "visual_validation": gui_current.get("visual_validation") or gui.get("visual_validation"),
            "can_trust_current_revision": live_gui_acceptance.get("can_trust_live_gui_current_revision"),
            "ready_for_next_live_edit": ready_for_next_live_edit,
            "ready_for_live_hotload": mcp_readiness.get("ready_for_live_hotload"),
            "model_ready_for_hotload": mcp_readiness.get("model_ready_for_hotload"),
            "gui_preflight_verified": mcp_readiness.get("gui_preflight_verified"),
            "gui_preflight_required": gui_preflight_required,
            "gui_preflight_reasons": mcp_readiness.get("gui_preflight_reasons") or [],
            "visible_followup_ready": visible_followup_ready,
            "visible_followup_status": visible_followup_status,
            "visible_followup_blocking_reasons": visible_followup_blocking_reasons or [],
            "visible_followup_recommended_tool": visible_followup_recommended_tool,
            "visible_followup_recommended_action": visible_followup_recommended_action,
            "visible_followup_payload_hint": visible_followup_payload_hint or {},
            "can_hotload_without_new_window": mcp_readiness.get(
                "can_accept_hotload_request_without_new_window"
            ),
            "can_apply_current_revision_without_new_window": mcp_readiness.get(
                "can_apply_current_revision_without_new_window"
            ),
            "recommended_tool": (
                visible_followup_recommended_tool
                if gui_preflight_required
                else gui_current.get("recommended_tool") or mcp_readiness.get("recommended_tool")
            ),
            "recommended_action": (
                visible_followup_recommended_action
                if gui_preflight_required
                else gui_current.get("recommended_action") or mcp_readiness.get("recommended_action")
            ),
            "payload_hint": (
                visible_followup_payload_hint
                if gui_preflight_required
                else gui_current.get("payload_hint") or mcp_readiness.get("payload_hint") or {}
            ),
        }
    )


