def _change_receipt_row_counts(diagnostics: dict[str, Any]) -> dict[str, int]:
    """Return compact diagnostic table sizes for a client receipt."""

    raw_counts = diagnostics.get("view_bundle_row_counts")
    if not isinstance(raw_counts, dict):
        return {}
    keys = (
        "atoms",
        "bonds",
        "crystal_nearest_neighbors",
        "crystal_coordination",
        "modeling_health_summary",
        "modeling_report_summary",
        "view_summary",
        "view_projections",
        "view_overlaps",
        "view_quality",
        "semiconductor_lattice",
        "semiconductor_composition",
        "semiconductor_charge_balance",
        "semiconductor_calculation_readiness",
        "semiconductor_normality_diagnosis",
        "semiconductor_calculation_preflight",
        "semiconductor_reciprocal_lattice",
        "semiconductor_band_path",
        "semiconductor_band_alignment",
        "semiconductor_polarization_2deg",
        "semiconductor_p_gan_gate_cap",
        "semiconductor_neighbor_pairs",
        "semiconductor_local_environment",
        "semiconductor_sublattice_balance",
        "semiconductor_dopants",
        "semiconductor_dopant_concentration",
        "semiconductor_dopant_sites",
        "semiconductor_carrier_intents",
        "semiconductor_junctions",
        "semiconductor_dopant_fraction",
        "semiconductor_alloy",
        "semiconductor_defects",
        "semiconductor_finite_size",
        "semiconductor_layer_profile",
        "semiconductor_interface_profile",
        "semiconductor_interface_scaffold",
        "semiconductor_interface_quality",
        "semiconductor_gate_stack",
        "semiconductor_contact",
        "semiconductor_quantum_well",
        "semiconductor_heterostructure",
        "semiconductor_strain",
        "semiconductor_surface_termination",
        "semiconductor_surface_polarity",
    )
    counts: dict[str, int] = {}
    for key in keys:
        value = raw_counts.get(key)
        if isinstance(value, int):
            counts[key] = value
    return counts


def _change_receipt_view_check(
    view_review: dict[str, Any],
    inspection: dict[str, Any],
    gui: dict[str, Any],
) -> dict[str, Any]:
    """Return the visual-check subset most useful to live clients."""

    if not view_review or view_review.get("available") is False:
        return {"available": False, "reason": view_review.get("reason") if isinstance(view_review, dict) else "no_view_review"}
    row_counts = inspection.get("row_counts") if isinstance(inspection.get("row_counts"), dict) else {}
    return {
        "available": True,
        "ok": view_review.get("ok"),
        "status": view_review.get("status"),
        "view_count": view_review.get("view_count"),
        "view_names": view_review.get("view_names") or _view_names_from_rows(inspection.get("views")),
        "supported_view_count": view_review.get("supported_view_count"),
        "supported_view_names": view_review.get("supported_view_names") or [],
        "expected_atom_projection_count": view_review.get("expected_atom_projection_count"),
        "view_projection_row_count": row_counts.get("view_projections"),
        "total_overlap_candidate_count": view_review.get("total_overlap_candidate_count"),
        "views_with_overlaps": view_review.get("views_with_overlaps") or [],
        "views_with_warnings": view_review.get("views_with_warnings") or [],
        "overlap_free_view_count": view_review.get("overlap_free_view_count"),
        "clean_view_count": view_review.get("clean_view_count"),
        "risk_flags": view_review.get("risk_flags") or [],
        "nonblocking_visual_flags": view_review.get("nonblocking_visual_flags") or [],
        "calculation_risk_flags": view_review.get("calculation_risk_flags") or [],
        "critical_flags": view_review.get("critical_flags") or [],
        "best_view_candidates": view_review.get("best_view_candidates") or [],
        "recommended_view_name": view_review.get("recommended_view_name"),
        "recommended_view_reason": view_review.get("recommended_view_reason"),
        "manual_review_view_names": view_review.get("manual_review_view_names") or [],
        "recommended_view_overlap_candidate_count": view_review.get("recommended_view_overlap_candidate_count"),
        "recommended_view_warning_count": view_review.get("recommended_view_warning_count"),
        "recommended_view_projection_span_angstrom": view_review.get("recommended_view_projection_span_angstrom"),
        "recommended_view_camera_direction": view_review.get("recommended_view_camera_direction"),
        "recommended_view_camera_up": view_review.get("recommended_view_camera_up"),
        "gui_visual_validation": gui.get("visual_validation"),
        "gui_loaded_current_revision": gui.get("loaded_current_revision"),
        "next_action": view_review.get("next_action"),
    }


