def _change_receipt_delta(delta: dict[str, Any]) -> dict[str, Any]:
    """Return compact delta fields suitable for a client-facing receipt."""

    if not delta:
        return {"available": False}
    molecule = delta.get("molecule") if isinstance(delta.get("molecule"), dict) else {}
    crystal = delta.get("crystal") if isinstance(delta.get("crystal"), dict) else {}
    return {
        "available": bool(delta.get("available", True)),
        "atom_count_delta": delta.get("atom_count_delta"),
        "element_count_delta": delta.get("element_count_delta"),
        "diff": delta.get("diff"),
        "molecule": _select_keys(
            molecule,
            [
                "added_atoms",
                "deleted_atoms",
                "substituted_atoms",
                "moved_atoms",
                "added_bonds",
                "deleted_bonds",
                "changed_bond_types",
            ],
        ),
        "crystal": _select_keys(
            crystal,
            [
                "lattice_delta",
                "added_atoms",
                "deleted_atoms",
                "substituted_atoms",
                "moved_atoms",
                "fractional_coordinate_update_count",
                "cartesian_moved_atoms",
                "cartesian_moved_atom_count",
                "cartesian_preserved_atom_count",
                "max_cartesian_displacement_angstrom",
                "fractional_rescale_preserved_cartesian",
                "supercell",
                "metadata_changes",
            ],
        ),
    }


def _inspection_summary_from_audit(audit: dict[str, Any] | None, row_counts: dict[str, Any] | None = None) -> dict[str, Any]:
    """Return compact geometry and view counts from a view audit."""

    row_counts = row_counts or {}
    if audit is None:
        return {"available": False, "row_counts": row_counts}
    health = audit.get("health") or {}
    model = audit.get("model") or {}
    metadata = audit.get("metadata") or {}
    views = audit.get("views") or []
    view_overlap_count = sum(len(view.get("overlap_candidates") or []) for view in views)
    view_warning_count = sum(len((view.get("health") or {}).get("warnings") or []) for view in views)
    return {
        "available": True,
        "project_id": audit.get("project_id"),
        "revision": audit.get("revision"),
        "model_type": audit.get("model_type"),
        "spec_fingerprint": audit.get("spec_fingerprint"),
        "atom_count": model.get("atom_count"),
        "bond_count": model.get("bond_count"),
        "elements": model.get("elements"),
        "metadata": metadata,
        "surface": _surface_summary_from_metadata(metadata),
        "geometry": audit.get("geometry"),
        "structure_artifact_validation": audit.get("structure_artifact_validation"),
        "health_ok": health.get("ok"),
        "health_error_count": len(health.get("errors") or []),
        "health_warning_count": len(health.get("warnings") or []),
        "bond_count_rows": len(health.get("bond_lengths_angstrom") or []),
        "bond_angle_count": len(health.get("bond_angles_deg") or []),
        "dihedral_count": len(health.get("dihedral_angles_deg") or []),
        "connectivity_count": len(health.get("atom_connectivity") or []),
        "close_contact_count": len(health.get("nonbonded_close_contacts") or []),
        "crystal_nearest_neighbor_count": len(health.get("crystal_nearest_neighbors") or []),
        "crystal_coordination_count": len(health.get("crystal_coordination") or []),
        "view_count": len(views),
        "views": _inspection_view_summaries(views),
        "view_overlap_candidate_count": view_overlap_count,
        "view_warning_count": view_warning_count,
        "bond_length_stats_angstrom": health.get("bond_length_stats_angstrom"),
        "bond_angle_stats_deg": health.get("bond_angle_stats_deg"),
        "dihedral_angle_stats_abs_deg": health.get("dihedral_angle_stats_abs_deg"),
        "crystal_pair_distance_stats_angstrom": health.get("crystal_pair_distance_stats_angstrom"),
        "crystal_nearest_neighbor_stats_angstrom": health.get("crystal_nearest_neighbor_stats_angstrom"),
        "crystal_coordination_stats": health.get("crystal_coordination_stats"),
        "slab_vacuum": health.get("slab_vacuum"),
        "semiconductor_health": health.get("semiconductor_health"),
        "row_counts": row_counts,
    }


def _view_review_from_audit(audit: dict[str, Any] | None, gui_summary: dict[str, Any] | None = None) -> dict[str, Any]:
    """Return a compact multi-view visual review for client display."""

    gui_summary = gui_summary or {}
    if not isinstance(audit, dict):
        return {
            "available": False,
            "reason": "no_view_audit",
            "gui_visual_validation": gui_summary.get("visual_validation"),
        }

    views = [view for view in audit.get("views") or [] if isinstance(view, dict)]
    model = audit.get("model") or {}
    expected_atoms = model.get("atom_count")
    rows = [_view_review_row(view, expected_atoms) for view in views]
    supported_rows = [row for row in rows if row.get("supported")]
    unsupported = [row["name"] for row in rows if row.get("supported") is False]
    warning_views = [row["name"] for row in rows if row.get("warning_count", 0) > 0]
    overlap_views = [row["name"] for row in rows if row.get("overlap_candidate_count", 0) > 0]
    degenerate_views = [row["name"] for row in rows if row.get("nearly_degenerate")]
    truncated_views = [row["name"] for row in rows if row.get("atom_projections_truncated")]
    projection_count_mismatch = [
        row["name"]
        for row in rows
        if expected_atoms is not None
        and row.get("atom_projection_count") is not None
        and int(row.get("atom_projection_count") or 0) != int(expected_atoms)
    ]
    warning_free_views = [row["name"] for row in supported_rows if int(row.get("warning_count") or 0) == 0]
    overlap_free_views = [row["name"] for row in supported_rows if int(row.get("overlap_candidate_count") or 0) == 0]
    clean_views = [
        row["name"]
        for row in supported_rows
        if int(row.get("warning_count") or 0) == 0
        and int(row.get("overlap_candidate_count") or 0) == 0
        and not row.get("nearly_degenerate")
        and not row.get("atom_projections_truncated")
        and row.get("projection_count_matches_model") is not False
    ]

    risk_flags: list[str] = []
    critical_flags: list[str] = []
    if not views:
        risk_flags.append("no_views")
        critical_flags.append("no_views")
    if unsupported:
        risk_flags.append("unsupported_views")
        critical_flags.append("unsupported_views")
    if not supported_rows and views:
        risk_flags.append("no_supported_views")
        critical_flags.append("no_supported_views")
    if warning_views:
        risk_flags.append("view_warnings")
    if overlap_views:
        risk_flags.append("projection_overlaps")
    if degenerate_views:
        risk_flags.append("degenerate_projection_views")
    if truncated_views:
        risk_flags.append("truncated_atom_projection_rows")
    if projection_count_mismatch:
        risk_flags.append("projection_atom_count_mismatch")
        critical_flags.append("projection_atom_count_mismatch")

    visual_validation = gui_summary.get("visual_validation")
    if visual_validation in {"failed", "warning", "snapshot_missing"}:
        risk_flags.append(f"gui_visual_validation_{visual_validation}")
    if visual_validation == "failed":
        critical_flags.append("gui_visual_validation_failed")
    if gui_summary.get("snapshot_likely_nonblank") is False:
        risk_flags.append("gui_snapshot_blank")
        critical_flags.append("gui_snapshot_blank")
    if gui_summary.get("loaded_current_revision") is False and gui_summary.get("hot_loaded"):
        risk_flags.append("gui_loaded_revision_stale")
        critical_flags.append("gui_loaded_revision_stale")
    if (
        gui_summary.get("activated_opened_window") is False
        and gui_summary.get("hot_loaded")
        and not _gui_foreground_current_revision_verified(gui_summary)
    ):
        risk_flags.append("gui_opened_window_activation_failed")
    if gui_summary.get("selected_window_matches_current") is False:
        risk_flags.append("gui_selected_window_stale")
    if gui_summary.get("foreground_window_matches_current") is False:
        risk_flags.append("gui_foreground_window_stale")
    identity_verification = gui_summary.get("window_identity_verification")
    if identity_verification == "unverified":
        risk_flags.append("gui_window_identity_unverified")
    elif identity_verification == "mismatched":
        risk_flags.append("gui_window_identity_mismatched")
        critical_flags.append("gui_window_identity_mismatched")

    nonblocking_visual_flags: list[str] = []
    if _projection_risks_are_nonblocking_visual_notes(
        audit,
        rows,
        clean_views=clean_views,
        unsupported=unsupported,
        degenerate_views=degenerate_views,
        truncated_views=truncated_views,
        projection_count_mismatch=projection_count_mismatch,
    ):
        if "projection_overlaps" in risk_flags:
            nonblocking_visual_flags.append("projection_overlaps")
        if "view_warnings" in risk_flags:
            nonblocking_visual_flags.append("view_warnings")

    total_overlap_count = sum(int(row.get("overlap_candidate_count") or 0) for row in rows)
    total_warning_count = sum(int(row.get("warning_count") or 0) for row in rows)
    best_views = _best_view_candidates(rows)
    recommended_view = best_views[0] if best_views else {}
    recommended_view_name = recommended_view.get("name")
    manual_review_view_names = [
        str(candidate.get("name"))
        for candidate in best_views
        if candidate.get("name") is not None
    ]
    calculation_risk_flags = sorted(set(risk_flags) - set(nonblocking_visual_flags))
    status = "failed" if critical_flags else ("review_warnings" if risk_flags else "passed")
    return {
        "available": True,
        "ok": not critical_flags,
        "status": status,
        "view_selection": audit.get("view_selection"),
        "view_count": len(rows),
        "view_names": _view_names_from_rows(rows),
        "supported_view_count": len(supported_rows),
        "supported_view_names": _view_names_from_rows(supported_rows),
        "expected_atom_projection_count": expected_atoms,
        "total_overlap_candidate_count": total_overlap_count,
        "view_warning_count": total_warning_count,
        "views_with_overlaps": overlap_views,
        "views_with_warnings": warning_views,
        "overlap_free_view_count": len(overlap_free_views),
        "overlap_free_views": overlap_free_views,
        "warning_free_view_count": len(warning_free_views),
        "warning_free_views": warning_free_views,
        "clean_view_count": len(clean_views),
        "clean_views": clean_views,
        "unsupported_views": unsupported,
        "degenerate_views": degenerate_views,
        "truncated_projection_views": truncated_views,
        "projection_count_mismatch_views": projection_count_mismatch,
        "best_view_candidates": best_views,
        "recommended_view_name": recommended_view_name,
        "recommended_view_reason": (
            "ranked_by_warning_count_overlap_count_projection_area"
            if recommended_view_name
            else None
        ),
        "manual_review_view_names": manual_review_view_names,
        "recommended_view_overlap_candidate_count": recommended_view.get("overlap_candidate_count"),
        "recommended_view_warning_count": recommended_view.get("warning_count"),
        "recommended_view_projection_span_angstrom": recommended_view.get("projection_span_angstrom"),
        "recommended_view_camera_direction": recommended_view.get("camera_direction"),
        "recommended_view_camera_up": recommended_view.get("camera_up"),
        "recommended_view_camera_position": recommended_view.get("camera_position"),
        "recommended_view_camera_distance_angstrom": recommended_view.get("camera_distance_angstrom"),
        "recommended_view_orthographic_width_angstrom": recommended_view.get("orthographic_width_angstrom"),
        "recommended_view_orthographic_height_angstrom": recommended_view.get("orthographic_height_angstrom"),
        "gui_visual_validation": visual_validation,
        "gui_window_identity_verification": identity_verification,
        "gui_snapshot_likely_nonblank": gui_summary.get("snapshot_likely_nonblank"),
        "risk_flags": sorted(set(risk_flags)),
        "nonblocking_visual_flags": sorted(set(nonblocking_visual_flags)),
        "calculation_risk_flags": calculation_risk_flags,
        "critical_flags": sorted(set(critical_flags)),
        "risk_flag_count": len(set(risk_flags)),
        "nonblocking_visual_flag_count": len(set(nonblocking_visual_flags)),
        "calculation_risk_flag_count": len(set(calculation_risk_flags)),
        "critical_flag_count": len(set(critical_flags)),
        "views": rows,
        "next_action": _view_review_next_action(risk_flags, critical_flags, clean_views=clean_views),
    }


def _projection_risks_are_nonblocking_visual_notes(
    audit: dict[str, Any],
    rows: list[dict[str, Any]],
    *,
    clean_views: list[Any],
    unsupported: list[Any],
    degenerate_views: list[Any],
    truncated_views: list[Any],
    projection_count_mismatch: list[Any],
) -> bool:
    """Return True when projection overlaps are visual notes, not structural risk."""

    if not clean_views:
        return False
    if unsupported or degenerate_views or truncated_views or projection_count_mismatch:
        return False
    if not _semiconductor_audit_structurally_clean(audit):
        return False
    warning_rows = [row for row in rows if int(row.get("warning_count") or 0) > 0]
    if not warning_rows:
        return False
    return all(_view_row_has_only_projection_overlap_warnings(row) for row in warning_rows)


def _view_row_has_only_projection_overlap_warnings(row: dict[str, Any]) -> bool:
    warnings = [str(item) for item in row.get("warnings") or []]
    if not warnings:
        return False
    if int(row.get("overlap_candidate_count") or 0) <= 0:
        return False
    return all("nearly overlapping in this 2d projection" in warning.lower() for warning in warnings)


def _semiconductor_audit_structurally_clean(audit: dict[str, Any]) -> bool:
    health = audit.get("health") if isinstance(audit.get("health"), dict) else {}
    semiconductor = health.get("semiconductor_health") if isinstance(health.get("semiconductor_health"), dict) else {}
    if not semiconductor:
        return False
    if health.get("ok") is False or semiconductor.get("ok") is False:
        return False
    if int(semiconductor.get("unexpected_neighbor_pair_count") or 0) > 0:
        return False
    if int(semiconductor.get("coordination_outlier_count") or 0) > 0:
        return False
    local_environment = semiconductor.get("local_environment_summary") or {}
    if int(local_environment.get("coordination_outlier_count") or 0) > 0:
        return False
    if int(semiconductor.get("same_sublattice_cutoff_artifact_pair_count") or 0) > 0:
        return False
    return True


def _view_review_row(view: dict[str, Any], expected_atoms: Any) -> dict[str, Any]:
    health = view.get("health") or {}
    warnings = [str(item) for item in health.get("warnings") or []]
    span = view.get("projection_span_angstrom") or {}
    framing = view.get("framing") or {}
    atom_projection_count = view.get("atom_projection_count")
    overlap_count = len(view.get("overlap_candidates") or [])
    nearly_degenerate = any("degenerate" in warning.lower() for warning in warnings)
    projection_count_matches = None
    if expected_atoms is not None and atom_projection_count is not None:
        projection_count_matches = int(atom_projection_count) == int(expected_atoms)
    return {
        "name": view.get("name"),
        "supported": view.get("supported"),
        "atom_projection_count": atom_projection_count,
        "projection_count_matches_model": projection_count_matches,
        "overlap_candidate_count": overlap_count,
        "warning_count": len(warnings),
        "warnings": warnings[:5],
        "nearly_degenerate": nearly_degenerate,
        "atom_projections_truncated": bool(view.get("atom_projections_truncated")),
        "projection_span_angstrom": span,
        "projection_bbox_angstrom": view.get("projection_bbox_angstrom"),
        "camera_direction": view.get("camera_direction"),
        "camera_up": view.get("camera_up"),
        "camera_position": view.get("camera_position"),
        "camera_distance_angstrom": view.get("camera_distance_angstrom"),
        "orthographic_width_angstrom": framing.get("orthographic_width_angstrom"),
        "orthographic_height_angstrom": framing.get("orthographic_height_angstrom"),
        "near_clip_angstrom": framing.get("near_clip_angstrom"),
        "far_clip_angstrom": framing.get("far_clip_angstrom"),
    }


def _best_view_candidates(rows: list[dict[str, Any]], *, limit: int = 3) -> list[dict[str, Any]]:
    supported = [row for row in rows if row.get("supported")]
    ranked = sorted(
        supported,
        key=lambda row: (
            int(row.get("warning_count") or 0),
            int(row.get("overlap_candidate_count") or 0),
            -float((row.get("projection_span_angstrom") or {}).get("x") or 0.0)
            * float((row.get("projection_span_angstrom") or {}).get("y") or 0.0),
            str(row.get("name") or ""),
        ),
    )
    return [
        {
            "name": row.get("name"),
            "overlap_candidate_count": row.get("overlap_candidate_count"),
            "warning_count": row.get("warning_count"),
            "projection_span_angstrom": row.get("projection_span_angstrom"),
            "camera_direction": row.get("camera_direction"),
            "camera_up": row.get("camera_up"),
            "camera_position": row.get("camera_position"),
            "camera_distance_angstrom": row.get("camera_distance_angstrom"),
            "orthographic_width_angstrom": row.get("orthographic_width_angstrom"),
            "orthographic_height_angstrom": row.get("orthographic_height_angstrom"),
        }
        for row in ranked[:limit]
    ]


def _view_review_next_action(
    risk_flags: list[str],
    critical_flags: list[str],
    *,
    clean_views: list[str] | None = None,
) -> str:
    if critical_flags:
        return "re_export_view_audit_or_re_hotload_before_trusting_visual_state"
    if risk_flags:
        if clean_views:
            return "inspect_clean_view_candidates_before_trusting_visual_state"
        return "inspect_best_view_candidates_and_overlap_or_warning_views"
    return "view_parameters_ready_for_visual_review"


def _semiconductor_review_from_audit(audit: dict[str, Any] | None) -> dict[str, Any]:
    """Return a compact semiconductor-focused review for client display."""

    if not isinstance(audit, dict):
        return {"available": False, "reason": "no_view_audit"}
    health = audit.get("health") or {}
    semiconductor = health.get("semiconductor_health")
    if not isinstance(semiconductor, dict) or not semiconductor:
        return {"available": False, "reason": "no_semiconductor_health"}

    metadata = audit.get("metadata") or {}
    model = audit.get("model") or {}
    composition = semiconductor.get("composition_summary") or {}
    lattice = semiconductor.get("lattice_summary") or {}
    calculation = semiconductor.get("calculation_preflight_summary") or {}
    reciprocal = semiconductor.get("reciprocal_lattice_summary") or {}
    band_path = semiconductor.get("band_path_summary") or {}
    band_alignment = semiconductor.get("band_alignment_summary") or {}
    polarization_2deg = semiconductor.get("polarization_2deg_summary") or {}
    p_gan_gate_cap = semiconductor.get("p_gan_gate_cap_summary") or {}
    heterostructure = semiconductor.get("heterostructure_summary") or {}
    substrate_epitaxy_preflight = semiconductor.get("substrate_epitaxy_preflight_summary") or {}
    interface_scaffold = semiconductor.get("interface_scaffold_summary") or {}
    strain = semiconductor.get("strain_summary") or {}
    charge_balance = semiconductor.get("charge_balance_summary") or {}
    dopant = semiconductor.get("dopant_summary") or {}
    dopant_site = semiconductor.get("dopant_site_summary") or {}
    dopant_concentration = semiconductor.get("dopant_concentration_summary") or {}
    dopant_fraction = semiconductor.get("dopant_fraction_summary") or {}
    junction = semiconductor.get("junction_summary") or {}
    alloy = semiconductor.get("alloy_summary") or {}
    defect = semiconductor.get("defect_summary") or {}
    finite_size = semiconductor.get("finite_size_summary") or {}
    interface_quality = semiconductor.get("interface_quality_summary") or {}
    gate_stack = semiconductor.get("gate_stack_summary") or {}
    contact = semiconductor.get("metal_semiconductor_contact_summary") or {}
    quantum_well = semiconductor.get("quantum_well_summary") or {}
    surface_model = semiconductor.get("surface_model_summary") or {}
    surface = semiconductor.get("surface_termination_summary") or {}
    polarity = semiconductor.get("surface_polarity_summary") or {}
    local_environment = semiconductor.get("local_environment_summary") or {}

    risk_flags = _semiconductor_review_risk_flags(
        semiconductor,
        calculation=calculation,
        reciprocal=reciprocal,
        band_path=band_path,
        band_alignment=band_alignment,
        polarization_2deg=polarization_2deg,
        p_gan_gate_cap=p_gan_gate_cap,
        heterostructure=heterostructure,
        substrate_epitaxy_preflight=substrate_epitaxy_preflight,
        interface_scaffold=interface_scaffold,
        strain=strain,
        charge_balance=charge_balance,
        dopant=dopant,
        dopant_site=dopant_site,
        dopant_concentration=dopant_concentration,
        dopant_fraction=dopant_fraction,
        junction=junction,
        alloy=alloy,
        defect=defect,
        finite_size=finite_size,
        interface_quality=interface_quality,
        gate_stack=gate_stack,
        contact=contact,
        quantum_well=quantum_well,
        surface_model=surface_model,
        surface=surface,
        polarity=polarity,
    )

    return {
        "available": True,
        "ok": semiconductor.get("ok"),
        "rule": semiconductor.get("rule"),
        "expected_coordination": semiconductor.get("expected_coordination"),
        "expected_coordination_by_element": semiconductor.get("expected_coordination_by_element"),
        "neighbor_pair_counts": semiconductor.get("neighbor_pair_counts"),
        "unexpected_neighbor_pair_count": semiconductor.get("unexpected_neighbor_pair_count"),
        "alloy_same_sublattice_neighbor_pair_count": semiconductor.get(
            "alloy_same_sublattice_neighbor_pair_count"
        ),
        "same_sublattice_cutoff_artifact_pair_count": semiconductor.get(
            "same_sublattice_cutoff_artifact_pair_count"
        ),
        "coordination_excluded_neighbor_pair_count": semiconductor.get(
            "coordination_excluded_neighbor_pair_count"
        ),
        "coordination_excluded_pair_types": semiconductor.get("coordination_excluded_pair_types") or [],
        "coordination_outlier_count": semiconductor.get("coordination_outlier_count")
        if semiconductor.get("coordination_outlier_count") is not None
        else local_environment.get("coordination_outlier_count"),
        "structure_family": metadata.get("structure_family") or band_path.get("structure_family"),
        "formula": composition.get("formula"),
        "reduced_formula": composition.get("reduced_formula"),
        "atom_count": model.get("atom_count"),
        "element_counts": composition.get("element_counts") or model.get("elements"),
        "model": {
            "name": model.get("name"),
            "atom_count": model.get("atom_count"),
            "formula": composition.get("formula"),
            "reduced_formula": composition.get("reduced_formula"),
            "element_counts": composition.get("element_counts") or model.get("elements"),
            "host_elements": composition.get("host_elements"),
            "dopant_elements": composition.get("dopant_elements"),
        },
        "lattice": _select_keys(
            lattice,
            [
                "a_angstrom",
                "b_angstrom",
                "c_angstrom",
                "alpha_deg",
                "beta_deg",
                "gamma_deg",
                "cell_volume_angstrom3",
                "volume_per_non_passivant_atom_angstrom3",
                "non_passivant_atom_density_per_angstrom3",
                "is_slab",
                "surface_axis",
                "declared_vacuum_angstrom",
                "declared_vacuum_fraction",
                "atom_extent_vacuum_angstrom",
                "vacuum_ok",
                "slab_vacuum_status",
                "slab_vacuum_next_action",
                "centered_in_cell",
                "vacuum_asymmetry_abs_angstrom",
                "slab_center_offset_angstrom",
                "metadata_cell_mismatch",
            ],
        ),
        "calculation": _select_keys(
            calculation,
            [
                "configured",
                "module",
                "task",
                "task_family",
                "task_intent",
                "status",
                "execution_risk",
                "functional",
                "quality",
                "cutoff_energy_ev",
                "cutoff_status",
                "kpoint_mode",
                "kpoint_separation",
                "kpoints",
                "ready_for_requested_task_preflight",
                "requires_prior_relaxed_structure",
                "settings_review_required",
                "changes_structure",
                "next_action",
            ],
        ),
        "kpoints": {
            **_select_keys(
                reciprocal,
                [
                    "status",
                    "estimated_kpoints_from_separation",
                    "actual_separations_1_per_angstrom",
                    "explicit_kpoints",
                    "recommended_kpoint_mode",
                    "recommended_kpoints",
                    "recommended_separations_1_per_angstrom",
                    "recommendation_reason_codes",
                    "slab_axis",
                ],
            ),
            "band_path": _select_keys(
                band_path,
                [
                    "available",
                    "task_relevant",
                    "bravais_lattice",
                    "path_label",
                    "point_count",
                    "segment_count",
                    "requires_materials_studio_review",
                ],
            ),
        },
        "composition": _select_keys(
            composition,
            ["total_atom_count", "non_passivant_atom_count", "passivant_atom_count", "element_count", "host_elements", "dopant_elements"],
        ),
        "coordination": _semiconductor_coordination_review(semiconductor),
        "charge_balance": _select_keys(
            charge_balance,
            [
                "total_valence_electron_count",
                "electron_count_parity",
                "odd_electron_warning",
                "spin_charge_review_required",
                "spin_polarization_review_required",
                "minimum_unpaired_electron_count_hint",
                "recommended_spin_treatment",
                "calculation_readiness_impact",
                "next_action",
                "carrier_type_hint",
                "carrier_type_hint_source",
                "nominal_dopant_delta_electrons",
                "site_adjusted_dopant_delta_electrons",
                "average_host_nominal_dopant_delta_electrons",
            ],
        ),
        "dopants": _semiconductor_dopant_review(
            dopant,
            dopant_site,
            dopant_fraction,
            dopant_concentration,
        ),
        "junction": _semiconductor_junction_review(junction),
        "band_alignment": _semiconductor_band_alignment_review(band_alignment),
        "polarization_2deg": _semiconductor_polarization_2deg_review(polarization_2deg),
        "p_gan_gate_cap": _semiconductor_p_gan_gate_cap_review(p_gan_gate_cap),
        "heterostructure": _semiconductor_heterostructure_review(heterostructure),
        "substrate_epitaxy_preflight": _semiconductor_substrate_epitaxy_preflight_review(
            substrate_epitaxy_preflight
        ),
        "interface_scaffold": _semiconductor_interface_scaffold_review(interface_scaffold),
        "strain": _semiconductor_strain_review(strain),
        "alloy": _semiconductor_alloy_review(alloy),
        "defects": _semiconductor_defect_review(defect, finite_size),
        "interface": _semiconductor_interface_review(interface_quality, quantum_well),
        "gate_stack": _semiconductor_gate_stack_review(gate_stack),
        "contact": _semiconductor_contact_review(contact),
        "surface_model": _semiconductor_surface_model_review(surface_model),
        "surface": _semiconductor_surface_review(surface, polarity),
        "risk_flags": risk_flags,
        "risk_flag_count": len(risk_flags),
        "next_action": _semiconductor_review_next_action(risk_flags, calculation),
    }


def _select_keys(source: dict[str, Any], keys: list[str]) -> dict[str, Any]:
    return {key: source.get(key) for key in keys if key in source}


def _semiconductor_coordination_review(semiconductor: dict[str, Any]) -> dict[str, Any]:
    """Return compact coordination diagnostics for client-facing semiconductor review."""

    local_environment = (
        semiconductor.get("local_environment_summary")
        if isinstance(semiconductor.get("local_environment_summary"), dict)
        else {}
    )
    outlier_count = semiconductor.get("coordination_outlier_count")
    if outlier_count is None:
        outlier_count = local_environment.get("coordination_outlier_count")
    result = {
        "expected_coordination": semiconductor.get("expected_coordination"),
        "expected_coordination_by_element": semiconductor.get("expected_coordination_by_element"),
        "coordination_by_element": semiconductor.get("coordination_by_element"),
        "coordination_outlier_count": outlier_count,
        "neighbor_pair_counts": semiconductor.get("neighbor_pair_counts"),
        "unexpected_neighbor_pair_count": semiconductor.get("unexpected_neighbor_pair_count"),
        "unchecked_neighbor_pair_count": semiconductor.get("unchecked_neighbor_pair_count"),
        "passivant_neighbor_pair_count": semiconductor.get("passivant_neighbor_pair_count"),
        "alloy_same_sublattice_neighbor_pair_count": semiconductor.get(
            "alloy_same_sublattice_neighbor_pair_count"
        ),
        "same_sublattice_cutoff_artifact_pair_count": semiconductor.get(
            "same_sublattice_cutoff_artifact_pair_count"
        ),
        "excluded_neighbor_pair_count": semiconductor.get("coordination_excluded_neighbor_pair_count"),
        "excluded_pair_types": semiconductor.get("coordination_excluded_pair_types") or [],
    }
    if local_environment:
        result["local_environment"] = _select_keys(
            local_environment,
            [
                "available",
                "atom_count",
                "expected_coordination",
                "expected_coordination_by_element",
                "coordination_outlier_count",
                "angle_stats_deg",
                "tetrahedral_angle_reference_deg",
                "tetrahedral_angle_deviation_stats_deg",
            ],
        )
    return _drop_none_values(result)


def _semiconductor_dopant_review(
    dopant: dict[str, Any],
    dopant_site: dict[str, Any],
    dopant_fraction: dict[str, Any],
    dopant_concentration: dict[str, Any],
) -> dict[str, Any] | None:
    if not dopant and not dopant_site and not dopant_fraction and not dopant_concentration:
        return None
    dopants = dopant.get("dopants") or []
    role_hints = sorted({str(item.get("role_hint")) for item in dopants if item.get("role_hint")})
    return {
        "total_dopant_count": dopant.get("total_dopant_count"),
        "total_dopant_fraction": dopant.get("total_dopant_fraction"),
        "total_dopant_density_cm3": dopant_concentration.get("total_dopant_density_cm3"),
        "net_nominal_carrier_density_cm3_abs": dopant_concentration.get("net_nominal_carrier_density_cm3_abs"),
        "concentration_warning_level": dopant_concentration.get("concentration_warning_level"),
        "high_concentration_warning": dopant_concentration.get("high_concentration_warning"),
        "degenerate_doping_review_required": dopant_concentration.get("degenerate_doping_review_required"),
        "concentration_next_action": dopant_concentration.get("next_action"),
        "host_elements": dopant.get("host_elements"),
        "dopant_elements": dopant.get("dopant_elements"),
        "role_hints": role_hints,
        "requested_fraction": dopant_fraction.get("requested_fraction"),
        "actual_fraction": dopant_fraction.get("actual_fraction"),
        "rounding_warning": dopant_fraction.get("rounding_warning"),
        "site_metadata": _select_keys(
            dopant_site,
            [
                "raw_site_count",
                "site_count",
                "valid_site_count",
                "stale_site_count",
                "metadata_consistent",
                "carrier_type_hint",
                "error_count",
                "errors",
                "warning_count",
                "warnings",
                "latest",
                "stale_entries",
            ],
        ),
    }


