def _semiconductor_review_risk_flags(
    semiconductor: dict[str, Any],
    *,
    calculation: dict[str, Any],
    reciprocal: dict[str, Any],
    band_path: dict[str, Any],
    band_alignment: dict[str, Any],
    polarization_2deg: dict[str, Any],
    p_gan_gate_cap: dict[str, Any],
    heterostructure: dict[str, Any],
    substrate_epitaxy_preflight: dict[str, Any],
    interface_scaffold: dict[str, Any],
    strain: dict[str, Any],
    charge_balance: dict[str, Any],
    dopant: dict[str, Any],
    dopant_site: dict[str, Any],
    dopant_concentration: dict[str, Any],
    dopant_fraction: dict[str, Any],
    junction: dict[str, Any],
    alloy: dict[str, Any],
    defect: dict[str, Any],
    finite_size: dict[str, Any],
    interface_quality: dict[str, Any],
    gate_stack: dict[str, Any],
    contact: dict[str, Any],
    quantum_well: dict[str, Any],
    surface_model: dict[str, Any],
    surface: dict[str, Any],
    polarity: dict[str, Any],
) -> list[str]:
    flags: list[str] = []
    lattice = semiconductor.get("lattice_summary") if isinstance(semiconductor.get("lattice_summary"), dict) else {}
    if semiconductor.get("ok") is False:
        flags.append("semiconductor_health_failed")
    if int(semiconductor.get("unexpected_neighbor_pair_count") or 0) > 0:
        flags.append("unexpected_semiconductor_neighbor_pairs")
    local_environment = semiconductor.get("local_environment_summary") or {}
    if int(local_environment.get("coordination_outlier_count") or 0) > 0:
        flags.append("coordination_outliers")
    if lattice.get("is_slab") and lattice.get("slab_vacuum_status") not in {None, "ready"}:
        flags.append("slab_vacuum_review")
    if lattice.get("vacuum_ok") is False:
        flags.append("slab_vacuum_insufficient")
    if lattice.get("centered_in_cell") is False:
        flags.append("slab_not_centered")
    if lattice.get("metadata_cell_mismatch"):
        flags.append("slab_vacuum_metadata_mismatch")
    if calculation.get("status") not in {None, "ok"}:
        flags.append("calculation_preflight_warnings")
    if calculation.get("settings_review_required"):
        flags.append("calculation_settings_review_required")
    if calculation.get("requires_prior_relaxed_structure"):
        flags.append("prior_relaxed_structure_required")
    if reciprocal.get("status") not in {None, "ok"}:
        flags.append("kpoint_reciprocal_lattice_warnings")
    if band_path.get("task_relevant") and band_path.get("requires_materials_studio_review"):
        flags.append("band_path_requires_materials_studio_review")
    if band_alignment.get("quality") not in {None, "complete"}:
        flags.append("band_alignment_review")
    if polarization_2deg.get("quality") not in {None, "complete"}:
        flags.append("polarization_2deg_review")
    if p_gan_gate_cap.get("quality") not in {None, "complete"}:
        flags.append("p_gan_gate_cap_review")
    if p_gan_gate_cap and p_gan_gate_cap.get("dopant_site_found") is False:
        flags.append("p_gan_gate_cap_dopant_missing")
    if heterostructure.get("strain_warning"):
        flags.append("epitaxial_strain_warning")
    if int(substrate_epitaxy_preflight.get("warning_count") or 0) > 0:
        flags.append("substrate_epitaxy_preflight_review")
    for target in substrate_epitaxy_preflight.get("targets", []) or []:
        if not isinstance(target, dict):
            continue
        if target.get("direct_mismatch_warning"):
            flags.append("substrate_epitaxy_direct_mismatch_warning")
        if target.get("domain_mismatch_warning"):
            flags.append("substrate_epitaxy_domain_mismatch_warning")
    if interface_scaffold.get("requires_geometry_relaxation"):
        flags.append("interface_scaffold_requires_relaxation")
    if interface_scaffold.get("visual_hotload_ready") is False:
        flags.append("interface_scaffold_visual_hotload_not_ready")
    if strain.get("strain_warning"):
        flags.append("applied_lattice_strain_warning")
    if charge_balance.get("odd_electron_warning"):
        flags.append("odd_valence_electron_count")
    if dopant.get("total_dopant_count"):
        flags.append("dopant_model")
    if int(dopant_site.get("stale_site_count") or 0) > 0 or dopant_site.get("metadata_consistent") is False:
        flags.append("dopant_site_metadata_inconsistent")
    if dopant_concentration.get("high_concentration_warning"):
        flags.append("dopant_concentration_high")
    if dopant_concentration.get("degenerate_doping_review_required"):
        flags.append("degenerate_doping_review_required")
    if dopant_fraction.get("rounding_warning"):
        flags.append("dopant_fraction_rounding")
    if junction.get("junction_count"):
        flags.append("junction_model")
    if int(junction.get("warning_count") or 0) > 0:
        flags.append("junction_metadata_review")
    latest_alloy = alloy.get("latest") if isinstance(alloy.get("latest"), dict) else {}
    if latest_alloy.get("rounding_warning"):
        flags.append("alloy_fraction_rounding")
    if int(alloy.get("same_sublattice_neighbor_pair_count") or 0) > 0:
        flags.append("alloy_same_sublattice_neighbors")
    if defect.get("defect_count"):
        flags.append("defect_model")
    if finite_size.get("finite_size_warning"):
        flags.append("finite_size_or_dilution_warning")
    if interface_quality.get("quality") not in {None, "complete"}:
        flags.append("interface_sequence_review")
    if interface_quality.get("period_sequence_complete") is False or interface_quality.get("transition_sequence_complete") is False:
        flags.append("interface_period_sequence_incomplete")
    if int(interface_quality.get("mixed_layer_count") or 0) > 0 and not interface_quality.get("mixed_layers_expected"):
        flags.append("mixed_interface_layers")
    if gate_stack.get("quality") not in {None, "complete"}:
        flags.append("gate_stack_review")
    if gate_stack.get("sequence_matches_expected") is False:
        flags.append("gate_stack_sequence_mismatch")
    if contact.get("quality") not in {None, "complete"}:
        flags.append("metal_semiconductor_contact_review")
    if _abs_float_gt(contact.get("contact_gap_delta_angstrom"), 0.05):
        flags.append("metal_semiconductor_contact_gap_mismatch")
    if _abs_float_gt(contact.get("metal_thickness_delta_angstrom"), 0.05):
        flags.append("metal_semiconductor_contact_thickness_mismatch")
    if contact.get("sequence_matches_expected") is False:
        flags.append("metal_semiconductor_contact_sequence_mismatch")
    if quantum_well.get("warning_count"):
        flags.append("quantum_well_review")
    if surface_model and surface_model.get("status") not in {None, "ready"}:
        flags.append("surface_model_not_ready")
    surface_orientation = surface_model.get("surface_orientation_summary") or {}
    if surface_orientation.get("blocking"):
        flags.append("surface_orientation_mismatch")
    surface_status = surface.get("surface_preparation_status")
    if surface.get("dangling_bond_estimate"):
        flags.append("surface_dangling_bonds")
    if surface.get("fully_passivated") is False and surface_status not in {None, "no_dangling_bonds_detected"}:
        flags.append("surface_not_fully_passivated")
    if polarity.get("surface_asymmetry_warning"):
        flags.append("surface_polarity_or_asymmetry")
    return sorted(set(flags))


def _abs_float_gt(value: Any, threshold: float) -> bool:
    try:
        return abs(float(value)) > threshold
    except (TypeError, ValueError):
        return False


def _semiconductor_review_next_action(risk_flags: list[str], calculation: dict[str, Any]) -> str:
    if "dopant_site_metadata_inconsistent" in risk_flags:
        return "reconcile_dopant_metadata_with_current_structure_then_reaudit"
    if risk_flags:
        return "review_semiconductor_risk_flags_before_calculation_or_claiming_normality"
    if calculation.get("ready_for_requested_task_preflight"):
        return "ready_for_requested_semiconductor_calculation_preflight"
    if calculation:
        return "review_or_complete_semiconductor_calculation_settings"
    return "continue_model_edits_or_add_simulation_settings"


def _surface_summary_from_metadata(metadata: dict[str, Any]) -> dict[str, Any] | None:
    """Return compact slab/surface metadata when present."""

    keys = {
        "surface_orientation",
        "surface_orientation_basis",
        "surface_normal_cell_axis",
        "surface_axis",
        "slab_thickness_angstrom",
        "vacuum_angstrom",
        "termination",
    }
    summary = {key: metadata.get(key) for key in sorted(keys) if key in metadata}
    return summary or None


def _inspection_view_summaries(views: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Return compact per-view projection parameters for display clients."""

    summaries: list[dict[str, Any]] = []
    for view in views:
        health = view.get("health") or {}
        warnings = health.get("warnings") or []
        summaries.append(
            {
                "name": view.get("name"),
                "supported": view.get("supported"),
                "camera_direction": view.get("camera_direction"),
                "camera_up": view.get("camera_up"),
                "camera_right": view.get("camera_right"),
                "look_at_direction": view.get("look_at_direction"),
                "camera_position": view.get("camera_position"),
                "camera_distance_angstrom": view.get("camera_distance_angstrom"),
                "target": view.get("target"),
                "framing": view.get("framing"),
                "projection_bbox_angstrom": view.get("projection_bbox_angstrom"),
                "projection_span_angstrom": view.get("projection_span_angstrom"),
                "atom_projection_count": view.get("atom_projection_count"),
                "overlap_candidate_count": len(view.get("overlap_candidates") or []),
                "health_ok": health.get("ok"),
                "warning_count": len(warnings),
                "warnings": warnings[:5],
            }
        )
    return summaries


def _change_validation_summary(delta: dict[str, Any] | None, audit: dict[str, Any] | None) -> dict[str, Any]:
    """Confirm that the current audit reflects the structured revision delta."""

    if not isinstance(delta, dict) or not delta.get("available"):
        return {"available": False, "reason": "no_revision_delta"}
    if not isinstance(audit, dict):
        return {"available": False, "reason": "no_view_audit"}

    model = audit.get("model") or {}
    atom_map = _audit_atom_map(audit)
    bond_rows = (audit.get("health") or {}).get("bond_lengths_angstrom") or []
    bond_set = {_audit_bond_key(row) for row in bond_rows if _audit_bond_key(row) is not None}
    checks: list[dict[str, Any]] = []
    warnings: list[str] = []

    _append_change_check(
        checks,
        "atom_count_after_matches_audit",
        delta.get("atom_count_after") == model.get("atom_count"),
        expected=delta.get("atom_count_after"),
        actual=model.get("atom_count"),
    )
    expected_elements = _normalized_count_map(delta.get("element_counts_after") or {})
    actual_elements = _normalized_count_map(model.get("elements") or {})
    _append_change_check(
        checks,
        "element_counts_after_match_audit",
        expected_elements == actual_elements,
        expected=expected_elements,
        actual=actual_elements,
    )

    molecule_delta = delta.get("molecule") if isinstance(delta.get("molecule"), dict) else None
    crystal_delta = delta.get("crystal") if isinstance(delta.get("crystal"), dict) else None
    structure_delta = molecule_delta or crystal_delta or {}
    coordinate_key = "xyz_angstrom" if molecule_delta else "fractional"
    moved_to_key = "to_xyz_angstrom" if molecule_delta else "to_fractional"

    added_mismatches = _added_atom_mismatches(structure_delta.get("added_atoms") or [], atom_map, coordinate_key)
    if structure_delta.get("added_atoms"):
        _append_change_check(
            checks,
            "added_atoms_present",
            not added_mismatches,
            expected=[item.get("atom_id") for item in structure_delta.get("added_atoms") or []],
            actual=sorted(atom_map),
            mismatches=added_mismatches,
        )

    deleted_present = [
        str(item.get("atom_id"))
        for item in structure_delta.get("deleted_atoms") or []
        if item.get("atom_id") is not None and str(item.get("atom_id")) in atom_map
    ]
    if structure_delta.get("deleted_atoms"):
        _append_change_check(
            checks,
            "deleted_atoms_absent",
            not deleted_present,
            expected=[item.get("atom_id") for item in structure_delta.get("deleted_atoms") or []],
            actual=deleted_present,
            mismatches=[{"atom_id": atom_id, "reason": "still_present"} for atom_id in deleted_present],
        )

    substituted_mismatches = _substituted_atom_mismatches(structure_delta.get("substituted_atoms") or [], atom_map)
    if structure_delta.get("substituted_atoms"):
        _append_change_check(
            checks,
            "substituted_atoms_match",
            not substituted_mismatches,
            expected=[{"atom_id": item.get("atom_id"), "element": item.get("to")} for item in structure_delta.get("substituted_atoms") or []],
            actual={atom_id: atom.get("element") for atom_id, atom in atom_map.items()},
            mismatches=substituted_mismatches,
        )

    moved_mismatches = _moved_atom_mismatches(structure_delta.get("moved_atoms") or [], atom_map, coordinate_key, moved_to_key)
    if structure_delta.get("moved_atoms"):
        _append_change_check(
            checks,
            "moved_atoms_match_coordinates",
            not moved_mismatches,
            expected=[{"atom_id": item.get("atom_id"), coordinate_key: item.get(moved_to_key)} for item in structure_delta.get("moved_atoms") or []],
            actual={atom_id: atom.get(coordinate_key) for atom_id, atom in atom_map.items()},
            mismatches=moved_mismatches,
        )

    if molecule_delta:
        _append_change_check(
            checks,
            "molecule_bond_count_after_matches_audit",
            molecule_delta.get("bond_count_after") == model.get("bond_count"),
            expected=molecule_delta.get("bond_count_after"),
            actual=model.get("bond_count"),
        )
        _append_bond_change_checks(checks, molecule_delta, bond_set)
    elif crystal_delta:
        lattice_after = crystal_delta.get("lattice_after")
        audit_lattice = model.get("lattice")
        if lattice_after is not None and audit_lattice is not None:
            _append_change_check(
                checks,
                "crystal_lattice_after_matches_audit",
                _numeric_mappings_close(lattice_after, audit_lattice),
                expected=lattice_after,
                actual=audit_lattice,
            )
        elif crystal_delta.get("lattice_changed"):
            warnings.append("crystal_lattice_not_available_in_audit")

    failed = [check for check in checks if check.get("passed") is False]
    return {
        "available": True,
        "ok": not failed,
        "checked_count": len(checks),
        "failed_count": len(failed),
        "warning_count": len(warnings),
        "warnings": warnings,
        "checks": checks,
    }


def _change_verification_summary(report: dict[str, Any]) -> dict[str, Any]:
    """Return a compact, client-facing receipt that the requested model change is represented."""

    delta = report.get("revision_delta") if isinstance(report.get("revision_delta"), dict) else {}
    change_validation = (
        report.get("change_validation")
        if isinstance(report.get("change_validation"), dict)
        else {}
    )
    semiconductor = (
        report.get("semiconductor_review")
        if isinstance(report.get("semiconductor_review"), dict)
        else {}
    )
    inspection = report.get("inspection") if isinstance(report.get("inspection"), dict) else {}
    structure = report.get("structure") if isinstance(report.get("structure"), dict) else {}
    workflow = report.get("workflow")
    diff = [str(item) for item in (delta.get("diff") or []) if item is not None]
    has_delta = bool(delta.get("available"))
    has_create = workflow == "create"
    audit_available = bool(inspection.get("available", True) is not False and inspection.get("atom_count") is not None)

    if has_delta:
        validation_available = bool(change_validation.get("available"))
        validation_ok = change_validation.get("ok") if validation_available else None
        ok = validation_ok is not False
        status = "verified" if validation_ok is True else "failed" if validation_ok is False else "delta_recorded_unverified"
        change_kind = "revision_patch"
    elif has_create:
        ok = bool(structure.get("exists") or audit_available)
        status = "created_and_audited" if audit_available else "created_without_audit" if ok else "created_without_structure"
        change_kind = "create"
    else:
        return {
            "available": False,
            "reason": "no_model_change",
            "workflow": workflow,
            "project_id": report.get("project_id"),
            "revision": report.get("revision"),
        }

    atom_count_after = delta.get("atom_count_after")
    if atom_count_after is None:
        atom_count_after = inspection.get("atom_count") or semiconductor.get("atom_count")
    element_counts_after = delta.get("element_counts_after")
    if element_counts_after is None:
        element_counts_after = semiconductor.get("element_counts") or (semiconductor.get("model") or {}).get("element_counts")
    domain_tags = _change_verification_domain_tags(delta, semiconductor, workflow=workflow)
    failed_checks = [
        check.get("name")
        for check in (change_validation.get("checks") or [])
        if isinstance(check, dict) and check.get("passed") is False
    ]

    return _drop_none_values(
        {
            "available": True,
            "ok": ok,
            "status": status,
            "change_kind": change_kind,
            "workflow": workflow,
            "project_id": report.get("project_id"),
            "base_revision": delta.get("base_revision", report.get("base_revision")),
            "revision": delta.get("new_revision", report.get("revision")),
            "model_type_before": delta.get("model_type_before"),
            "model_type_after": delta.get("model_type_after"),
            "diff": diff,
            "diff_count": len(diff),
            "atom_count_delta": delta.get("atom_count_delta"),
            "atom_count_after": atom_count_after,
            "element_count_delta": delta.get("element_count_delta") or {},
            "element_counts_after": element_counts_after,
            "change_validation_available": change_validation.get("available"),
            "change_validation_ok": change_validation.get("ok"),
            "change_validation_failed_checks": failed_checks,
            "domain_tags": domain_tags,
            "semiconductor": _select_keys(
                semiconductor,
                [
                    "available",
                    "ok",
                    "rule",
                    "formula",
                    "reduced_formula",
                    "structure_family",
                    "risk_flags",
                    "dopants",
                    "defects",
                    "junction",
                    "heterostructure",
                    "alloy",
                    "surface",
                    "surface_model",
                    "gate_stack",
                    "contact",
                    "strain",
                ],
            )
            if semiconductor
            else None,
            "next_action": "continue_next_model_edit" if ok else "inspect_change_validation_failures_before_trusting_change",
        }
    )


def _change_verification_domain_tags(
    delta: dict[str, Any],
    semiconductor: dict[str, Any],
    *,
    workflow: Any,
) -> list[str]:
    """Infer compact semiconductor-domain tags for the latest create/patch request."""

    tags: list[str] = []
    if workflow == "create":
        tags.append("create")
    diff_text = " ".join(str(item).lower() for item in (delta.get("diff") or []))
    crystal = delta.get("crystal") if isinstance(delta.get("crystal"), dict) else {}
    molecule = delta.get("molecule") if isinstance(delta.get("molecule"), dict) else {}
    if diff_text:
        tags.append("revision_delta")
    if "make_supercell" in diff_text or crystal.get("lattice_changed"):
        tags.append("lattice_or_supercell")
    if "add_vacuum" in diff_text or "set_vacuum" in diff_text or "center_slab" in diff_text:
        tags.append("surface_slab")
    if "substitute_atom" in diff_text or molecule.get("substituted_atoms") or crystal.get("substituted_atoms"):
        tags.append("substitution")
    if "delete_atom" in diff_text or molecule.get("deleted_atoms") or crystal.get("deleted_atoms"):
        tags.append("atom_removal")
    if "add_atom" in diff_text or molecule.get("added_atoms") or crystal.get("added_atoms"):
        tags.append("atom_addition")
    if (delta.get("simulation") or {}).get("changed"):
        tags.append("simulation_settings")

    if semiconductor.get("available") is True:
        tags.append("semiconductor")
    dopants = semiconductor.get("dopants") if isinstance(semiconductor.get("dopants"), dict) else {}
    defects = semiconductor.get("defects") if isinstance(semiconductor.get("defects"), dict) else {}
    junction = semiconductor.get("junction") if isinstance(semiconductor.get("junction"), dict) else {}
    heterostructure = (
        semiconductor.get("heterostructure")
        if isinstance(semiconductor.get("heterostructure"), dict)
        else {}
    )
    alloy = semiconductor.get("alloy") if isinstance(semiconductor.get("alloy"), dict) else {}
    surface = semiconductor.get("surface") if isinstance(semiconductor.get("surface"), dict) else {}
    surface_model = (
        semiconductor.get("surface_model")
        if isinstance(semiconductor.get("surface_model"), dict)
        else {}
    )
    gate_stack = semiconductor.get("gate_stack") if isinstance(semiconductor.get("gate_stack"), dict) else {}
    contact = semiconductor.get("contact") if isinstance(semiconductor.get("contact"), dict) else {}
    strain = semiconductor.get("strain") if isinstance(semiconductor.get("strain"), dict) else {}
    if dopants.get("total_dopant_count"):
        tags.append("dopant")
    if defects.get("defect_count") or defects.get("vacancy_count"):
        tags.append("defect")
    if junction.get("junction_count"):
        tags.append("junction")
    if heterostructure.get("interface") or heterostructure.get("materials"):
        tags.append("heterostructure")
    if alloy.get("alloy_count") or alloy.get("latest"):
        tags.append("alloy")
    if surface or surface_model:
        tags.append("surface")
    if gate_stack:
        tags.append("gate_stack")
    if contact:
        tags.append("metal_semiconductor_contact")
    if strain.get("entry_count"):
        tags.append("strain")
    return _dedupe_strings(tags)


def _semiconductor_intent_summary(response: dict[str, Any], report: dict[str, Any]) -> dict[str, Any]:
    """Return a compact receipt that the semiconductor modeling intent is represented."""

    semiconductor = (
        report.get("semiconductor_review")
        if isinstance(report.get("semiconductor_review"), dict)
        else {}
    )
    if not semiconductor or semiconductor.get("available") is False:
        return {
            "available": False,
            "reason": semiconductor.get("reason") or "no_semiconductor_review",
            "workflow": report.get("workflow"),
            "project_id": report.get("project_id"),
            "revision": report.get("revision"),
        }

    inspection = report.get("inspection") if isinstance(report.get("inspection"), dict) else {}
    semiconductor_health = (
        inspection.get("semiconductor_health")
        if isinstance(inspection.get("semiconductor_health"), dict)
        else {}
    )
    nl_plan = response.get("nl_plan") if isinstance(response.get("nl_plan"), dict) else {}
    if not nl_plan and isinstance(report.get("nl_plan"), dict):
        nl_plan = report["nl_plan"]
    template_profile = (
        report.get("semiconductor_template_profile")
        if isinstance(report.get("semiconductor_template_profile"), dict)
        else {}
    )
    change_verification = (
        report.get("change_verification")
        if isinstance(report.get("change_verification"), dict)
        else {}
    )

    carrier_intent = (
        semiconductor_health.get("carrier_intent_summary")
        if isinstance(semiconductor_health.get("carrier_intent_summary"), dict)
        else {}
    )
    dopants = semiconductor.get("dopants") if isinstance(semiconductor.get("dopants"), dict) else {}
    defects = semiconductor.get("defects") if isinstance(semiconductor.get("defects"), dict) else {}
    junction = semiconductor.get("junction") if isinstance(semiconductor.get("junction"), dict) else {}
    alloy = semiconductor.get("alloy") if isinstance(semiconductor.get("alloy"), dict) else {}
    heterostructure = (
        semiconductor.get("heterostructure")
        if isinstance(semiconductor.get("heterostructure"), dict)
        else {}
    )
    surface_model = (
        semiconductor.get("surface_model")
        if isinstance(semiconductor.get("surface_model"), dict)
        else {}
    )
    surface = semiconductor.get("surface") if isinstance(semiconductor.get("surface"), dict) else {}
    calculation = semiconductor.get("calculation") if isinstance(semiconductor.get("calculation"), dict) else {}
    gate_stack = semiconductor.get("gate_stack") if isinstance(semiconductor.get("gate_stack"), dict) else {}
    contact = semiconductor.get("contact") if isinstance(semiconductor.get("contact"), dict) else {}

    domain_tags = _dedupe_strings(
        [
            *[str(item) for item in (change_verification.get("domain_tags") or [])],
            *_semiconductor_intent_domain_tags(
                semiconductor,
                carrier_intent=carrier_intent,
                dopants=dopants,
                defects=defects,
                junction=junction,
                alloy=alloy,
                heterostructure=heterostructure,
                surface_model=surface_model,
                surface=surface,
                calculation=calculation,
                gate_stack=gate_stack,
                contact=contact,
            ),
        ]
    )

    failure_reasons: list[str] = []
    review_reasons: list[str] = []
    if semiconductor.get("ok") is False:
        failure_reasons.append("semiconductor_review_failed")
    if change_verification.get("available") and change_verification.get("ok") is False:
        failure_reasons.append("change_verification_failed")
    if carrier_intent and carrier_intent.get("latest_matches") is False:
        failure_reasons.append("carrier_intent_mismatch")
    for flag in semiconductor.get("risk_flags") or []:
        review_reasons.append(f"semiconductor:{flag}")
    if change_verification.get("status") in {"delta_recorded_unverified", "created_without_audit"}:
        review_reasons.append(f"change_verification:{change_verification.get('status')}")

    if failure_reasons:
        status = "failed"
    elif review_reasons:
        status = "verified_with_review"
    elif report.get("workflow") == "inspect_current":
        status = "current_model_reviewed"
    else:
        status = "verified"

    ok = not failure_reasons
    evidence = _drop_none_values(
        {
            "formula": semiconductor.get("formula"),
            "reduced_formula": semiconductor.get("reduced_formula"),
            "structure_family": semiconductor.get("structure_family"),
            "rule": semiconductor.get("rule"),
            "atom_count": semiconductor.get("atom_count"),
            "element_counts": semiconductor.get("element_counts"),
            "dopant_count": dopants.get("total_dopant_count"),
            "dopant_elements": dopants.get("dopant_elements"),
            "dopant_role_hints": dopants.get("role_hints"),
            "carrier_intent_latest_matches": carrier_intent.get("latest_matches"),
            "requested_carrier_type": carrier_intent.get("requested_carrier_type"),
            "actual_carrier_type": carrier_intent.get("actual_carrier_type"),
            "actual_dopant_elements": carrier_intent.get("actual_dopant_elements"),
            "defect_count": defects.get("defect_count"),
            "vacancy_count": defects.get("vacancy_count"),
            "interstitial_count": defects.get("interstitial_count"),
            "antisite_count": defects.get("antisite_count"),
            "pn_junction_count": junction.get("pn_junction_count"),
            "junction_count": junction.get("junction_count"),
            "alloy_count": alloy.get("alloy_count") or alloy.get("entry_count"),
            "heterostructure_materials": heterostructure.get("materials"),
            "heterostructure_interface": heterostructure.get("interface"),
            "surface_model_status": surface_model.get("status"),
            "surface_preparation_status": surface.get("surface_preparation_status"),
            "gate_stack_quality": gate_stack.get("quality"),
            "contact_quality": contact.get("quality"),
            "calculation_status": calculation.get("status"),
            "calculation_task": calculation.get("task"),
            "calculation_task_intent": calculation.get("task_intent"),
        }
    )

    return _drop_none_values(
        {
            "available": True,
            "ok": ok,
            "status": status,
            "workflow": report.get("workflow"),
            "project_id": report.get("project_id"),
            "revision": report.get("revision"),
            "nl_template_id": nl_plan.get("template_id"),
            "nl_plan_kind": nl_plan.get("kind"),
            "template_id": template_profile.get("template_id"),
            "template_label": template_profile.get("label") or template_profile.get("name"),
            "domain_tags": domain_tags,
            "failure_reasons": _dedupe_strings(failure_reasons),
            "review_reasons": _dedupe_strings(review_reasons),
            "change_verification_status": change_verification.get("status"),
            "change_verification_ok": change_verification.get("ok"),
            "semiconductor_ok": semiconductor.get("ok"),
            "risk_flags": semiconductor.get("risk_flags") or [],
            "evidence": evidence,
            "next_action": "continue_next_model_edit" if ok else "fix_semiconductor_intent_failures_then_reaudit",
        }
    )


def _semiconductor_intent_domain_tags(
    semiconductor: dict[str, Any],
    *,
    carrier_intent: dict[str, Any],
    dopants: dict[str, Any],
    defects: dict[str, Any],
    junction: dict[str, Any],
    alloy: dict[str, Any],
    heterostructure: dict[str, Any],
    surface_model: dict[str, Any],
    surface: dict[str, Any],
    calculation: dict[str, Any],
    gate_stack: dict[str, Any],
    contact: dict[str, Any],
) -> list[str]:
    """Infer high-level semiconductor intent tags from audited domain summaries."""

    tags: list[str] = []
    if semiconductor.get("available") is True:
        tags.append("semiconductor")
    if dopants.get("total_dopant_count"):
        tags.append("dopant")
    if carrier_intent:
        tags.append("carrier_intent")
    if defects.get("defect_count"):
        tags.append("defect")
    if defects.get("vacancy_count"):
        tags.append("vacancy")
    if defects.get("interstitial_count"):
        tags.append("interstitial")
    if defects.get("antisite_count"):
        tags.append("antisite")
    if junction.get("junction_count"):
        tags.append("junction")
    if junction.get("pn_junction_count"):
        tags.append("pn_junction")
    if alloy.get("alloy_count") or alloy.get("latest"):
        tags.append("alloy")
    if heterostructure.get("interface") or heterostructure.get("materials"):
        tags.append("heterostructure")
    if surface_model or surface:
        tags.append("surface_model")
    if gate_stack:
        tags.append("gate_stack")
    if contact:
        tags.append("metal_semiconductor_contact")
    if calculation.get("configured") or calculation.get("task") or calculation.get("task_intent"):
        tags.append("calculation_preflight")
    return _dedupe_strings(tags)


def _append_change_check(
    checks: list[dict[str, Any]],
    name: str,
    passed: bool,
    *,
    expected: Any = None,
    actual: Any = None,
    mismatches: list[dict[str, Any]] | None = None,
) -> None:
    check = {"name": name, "passed": bool(passed), "expected": expected, "actual": actual}
    if mismatches:
        check["mismatches"] = mismatches
    checks.append(check)


def _audit_atom_map(audit: dict[str, Any]) -> dict[str, dict[str, Any]]:
    atoms: dict[str, dict[str, Any]] = {}
    for atom in audit.get("atoms") or []:
        if not isinstance(atom, dict):
            continue
        atom_id = atom.get("id") or atom.get("atom_id")
        if atom_id is not None:
            atoms[str(atom_id)] = atom
    return atoms


def _added_atom_mismatches(
    added_atoms: list[dict[str, Any]],
    atom_map: dict[str, dict[str, Any]],
    coordinate_key: str,
) -> list[dict[str, Any]]:
    mismatches: list[dict[str, Any]] = []
    for item in added_atoms:
        atom_id = str(item.get("atom_id"))
        actual = atom_map.get(atom_id)
        if actual is None:
            mismatches.append({"atom_id": atom_id, "reason": "missing"})
            continue
        if item.get("element") is not None and actual.get("element") != item.get("element"):
            mismatches.append(
                {
                    "atom_id": atom_id,
                    "reason": "element_mismatch",
                    "expected": item.get("element"),
                    "actual": actual.get("element"),
                }
            )
        if item.get(coordinate_key) is not None and not _vectors_close(item.get(coordinate_key), actual.get(coordinate_key)):
            mismatches.append(
                {
                    "atom_id": atom_id,
                    "reason": "coordinate_mismatch",
                    "expected": item.get(coordinate_key),
                    "actual": actual.get(coordinate_key),
                }
            )
    return mismatches


def _substituted_atom_mismatches(
    substituted_atoms: list[dict[str, Any]],
    atom_map: dict[str, dict[str, Any]],
) -> list[dict[str, Any]]:
    mismatches: list[dict[str, Any]] = []
    for item in substituted_atoms:
        atom_id = str(item.get("atom_id"))
        actual = atom_map.get(atom_id)
        if actual is None:
            mismatches.append({"atom_id": atom_id, "reason": "missing"})
            continue
        if item.get("to") is not None and actual.get("element") != item.get("to"):
            mismatches.append(
                {
                    "atom_id": atom_id,
                    "reason": "element_mismatch",
                    "expected": item.get("to"),
                    "actual": actual.get("element"),
                }
            )
    return mismatches


def _moved_atom_mismatches(
    moved_atoms: list[dict[str, Any]],
    atom_map: dict[str, dict[str, Any]],
    coordinate_key: str,
    moved_to_key: str,
) -> list[dict[str, Any]]:
    mismatches: list[dict[str, Any]] = []
    for item in moved_atoms:
        atom_id = str(item.get("atom_id"))
        actual = atom_map.get(atom_id)
        if actual is None:
            mismatches.append({"atom_id": atom_id, "reason": "missing"})
            continue
        expected_coordinate = item.get(moved_to_key)
        if expected_coordinate is not None and not _vectors_close(expected_coordinate, actual.get(coordinate_key)):
            mismatches.append(
                {
                    "atom_id": atom_id,
                    "reason": "coordinate_mismatch",
                    "expected": expected_coordinate,
                    "actual": actual.get(coordinate_key),
                }
            )
    return mismatches


def _append_bond_change_checks(
    checks: list[dict[str, Any]],
    molecule_delta: dict[str, Any],
    bond_set: set[tuple[str, str, str]],
) -> None:
    added_bonds = [_delta_bond_key(item) for item in molecule_delta.get("added_bonds") or []]
    added_bonds = [item for item in added_bonds if item is not None]
    if added_bonds:
        missing = [item for item in added_bonds if item not in bond_set]
        _append_change_check(
            checks,
            "added_bonds_present",
            not missing,
            expected=[list(item) for item in added_bonds],
            actual=[list(item) for item in sorted(bond_set)],
            mismatches=[{"bond": list(item), "reason": "missing"} for item in missing],
        )

    deleted_bonds = [_delta_bond_key(item) for item in molecule_delta.get("deleted_bonds") or []]
    deleted_bonds = [item for item in deleted_bonds if item is not None]
    if deleted_bonds:
        still_present = [item for item in deleted_bonds if item in bond_set]
        _append_change_check(
            checks,
            "deleted_bonds_absent",
            not still_present,
            expected=[list(item) for item in deleted_bonds],
            actual=[list(item) for item in still_present],
            mismatches=[{"bond": list(item), "reason": "still_present"} for item in still_present],
        )

    changed = molecule_delta.get("changed_bond_types") or []
    if changed:
        mismatches = []
        for item in changed:
            expected = _delta_bond_key({"atom1": item.get("atom1"), "atom2": item.get("atom2"), "type": item.get("to")})
            if expected is not None and expected not in bond_set:
                mismatches.append({"bond": list(expected), "reason": "type_mismatch"})
        _append_change_check(
            checks,
            "changed_bond_types_match",
            not mismatches,
            expected=[{"atom1": item.get("atom1"), "atom2": item.get("atom2"), "type": item.get("to")} for item in changed],
            actual=[list(item) for item in sorted(bond_set)],
            mismatches=mismatches,
        )


def _audit_bond_key(row: dict[str, Any]) -> tuple[str, str, str] | None:
    atom1 = row.get("atom1")
    atom2 = row.get("atom2")
    bond_type = row.get("type")
    if atom1 is None or atom2 is None or bond_type is None:
        return None
    left, right = sorted([str(atom1), str(atom2)])
    return left, right, str(bond_type)


def _delta_bond_key(row: dict[str, Any]) -> tuple[str, str, str] | None:
    atom1 = row.get("atom1")
    atom2 = row.get("atom2")
    bond_type = row.get("type")
    if atom1 is None or atom2 is None or bond_type is None:
        return None
    left, right = sorted([str(atom1), str(atom2)])
    return left, right, str(bond_type)


def _normalized_count_map(value: dict[str, Any]) -> dict[str, int]:
    return {str(key): int(count) for key, count in sorted(value.items())}


def _vectors_close(expected: Any, actual: Any, *, tolerance: float = 1e-5) -> bool:
    expected_vector = _vector_components(expected)
    actual_vector = _vector_components(actual)
    if expected_vector is None or actual_vector is None:
        return False
    return all(abs(left - right) <= tolerance for left, right in zip(expected_vector, actual_vector))


def _vector_components(value: Any) -> tuple[float, float, float] | None:
    if isinstance(value, dict):
        keys = ("x", "y", "z")
        if all(key in value for key in keys):
            try:
                return tuple(float(value[key]) for key in keys)  # type: ignore[return-value]
            except (TypeError, ValueError):
                return None
    if isinstance(value, (list, tuple)) and len(value) == 3:
        try:
            return tuple(float(item) for item in value)  # type: ignore[return-value]
        except (TypeError, ValueError):
            return None
    return None


def _numeric_mappings_close(expected: dict[str, Any], actual: dict[str, Any], *, tolerance: float = 1e-6) -> bool:
    for key, expected_value in expected.items():
        actual_value = actual.get(key)
        if isinstance(expected_value, (int, float)) and isinstance(actual_value, (int, float)):
            if abs(float(expected_value) - float(actual_value)) > tolerance:
                return False
        elif expected_value != actual_value:
            return False
    return True


def _modeling_report_normality(report: dict[str, Any]) -> str:
    """Classify the current response for simple client display."""

    verdict = report.get("health_verdict")
    if not report["ok"] or report["health_ok"] is False:
        return "failed"
    if (report.get("acceptance_review") or {}).get("ok") is False:
        return "review_warnings"
    if (report.get("change_validation") or {}).get("ok") is False:
        return "review_warnings"
    if (report.get("view_review") or {}).get("status") == "failed":
        return "review_warnings"
    if verdict in {"ready_with_warnings", "passed_with_warnings"} and _health_verdict_warnings_require_review(report):
        return "review_warnings"
    if verdict is None and report["warning_count"]:
        return "review_warnings"
    if report["execution_mode"] == ExecutionMode.EXECUTE.value and report["gui"]["hot_loaded"]:
        if report["gui"].get("loaded_current_revision") is False:
            return "review_warnings"
        if report["gui"].get("selected_window_matches_current") is False:
            return "review_warnings"
        if report["gui"].get("foreground_window_matches_current") is False:
            return "review_warnings"
        if report["gui"].get("window_identity_verification") == "unverified":
            return "review_warnings"
        if report["gui"].get("window_identity_verification") == "mismatched":
            return "review_warnings"
        if report["gui"].get("visual_validation") not in {None, "passed"}:
            return "review_warnings"
        return "hot_loaded_and_passed"
    if report["execution_mode"] == ExecutionMode.PREVIEW.value:
        return "preview_ready"
    return "passed"


def _health_verdict_warnings_require_review(report: dict[str, Any]) -> bool:
    warnings = report.get("health_verdict_warnings")
    if not isinstance(warnings, list):
        return bool(report.get("warning_count"))
    return any(not _nonblocking_modeling_warning(str(warning), report) for warning in warnings)


def _nonblocking_modeling_warning(warning: str, report: dict[str, Any]) -> bool:
    structure = report.get("structure") if isinstance(report.get("structure"), dict) else {}
    gui = report.get("gui") if isinstance(report.get("gui"), dict) else {}
    if gui.get("external_visual_confirmation_ok") is True and (
        "GUI snapshot viewport" in warning
        or "GDI/OpenGL viewport capture" in warning
        or "OpenGL 3D viewport" in warning
    ):
        return True
    return (
        "Crystal MaterialsScript lattice construction is preview-only" in warning
        and report.get("execution_backend") == "crystal_cif_materialize"
        and report.get("execution_mode") == ExecutionMode.EXECUTE.value
        and structure.get("exists") is True
    )


