def _deduplicate_compact_action_payloads(compact: dict[str, Any]) -> None:
    """Keep a callable payload once in the authoritative next-action plan."""

    next_action = compact.get("next_action_plan")
    if not isinstance(next_action, dict):
        return
    authoritative_payload = next_action.get("payload_hint")
    if not isinstance(authoritative_payload, dict):
        return
    for key in ("mcp_client_readiness", "semiconductor_normality_diagnosis"):
        candidate = compact.get(key)
        if not isinstance(candidate, dict):
            continue
        if candidate.get("payload_hint") != authoritative_payload:
            continue
        candidate = dict(candidate)
        candidate.pop("payload_hint", None)
        candidate["payload_hint_ref"] = "next_action_plan.payload_hint"
        compact[key] = candidate


def _compact_capabilities_natural_language(value: Any) -> dict[str, Any]:
    """Return supported NL operation discovery without full prompt examples."""

    if not isinstance(value, dict):
        return {}
    patch_commands = [
        _mapping_subset(
            item,
            ("template_id", "operations", "requires_existing_project"),
        )
        for item in value.get("patch_commands") or []
        if isinstance(item, dict)
    ]
    session_commands = [
        _mapping_subset(
            item,
            ("template_id", "operation", "requires_existing_project"),
        )
        for item in value.get("session_commands") or []
        if isinstance(item, dict)
    ]
    view_selection = value.get("view_selection")
    compact_views: dict[str, Any] = {}
    if isinstance(view_selection, dict):
        compact_views = _mapping_subset(view_selection, ("default_views",))
        semiconductor_defaults = view_selection.get("semiconductor_domain_defaults")
        if isinstance(semiconductor_defaults, dict):
            compact_views["semiconductor_domain_defaults"] = _mapping_subset(
                semiconductor_defaults,
                (
                    "policy_version",
                    "applies_when",
                    "explicit_views_override",
                    "selection_precedence",
                    "receipt_field",
                    "cartesian_context_views",
                    "profiles",
                ),
            )
        for source_key, target_key in (
            ("crystallographic_direction_views", "crystallographic_direction_view_names"),
            ("crystallographic_plane_views", "crystallographic_plane_view_names"),
            ("semiconductor_oriented_frame_views", "semiconductor_oriented_frame_view_names"),
        ):
            entries = view_selection.get(source_key)
            if isinstance(entries, dict):
                compact_views[target_key] = list(entries)
    inline_modifiers = value.get("new_structure_inline_modifiers")
    compact_inline = _mapping_subset(
        inline_modifiers,
        (
            "enabled_for",
            "operations",
            "post_supercell_atom_ids_required",
            "post_supercell_auto_site_supported",
            "ambiguous_original_atom_id_policy",
        ),
    )
    return _drop_none_values(
        {
            "mode": value.get("mode"),
            "cjk_semiconductor_hotload_examples": value.get(
                "cjk_semiconductor_hotload_examples"
            ),
            "view_selection": compact_views,
            "patch_commands": patch_commands,
            "patch_command_count": len(patch_commands),
            "session_commands": session_commands,
            "session_command_count": len(session_commands),
            "new_structure_inline_modifiers": compact_inline,
            "unsupported_next_step": value.get("unsupported_next_step"),
            "full_catalog_hint": {
                "tool": "material_studio_live_capabilities",
                "arguments": {"response_mode": McpResponseMode.FULL.value},
            },
        }
    )


