            "next_pending_view_name",
            "next_actionable_pending_view_name",
            "next_automation_ready_view_name",
            "recommended_action",
            "recommended_mcp_tool",
            "recommended_tool",
            "recommended_executor",
            "automatic_replay_ready",
            "gui_input_required",
            "post_action_observation_required",
            "record_call_ready",
            "record_tool",
