def _enforce_capabilities_compact_budget(compact: dict[str, Any]) -> dict[str, Any]:
    """Guarantee a bounded discovery receipt as capability catalogs grow."""

    bounded = dict(compact)
    receipt = _compact_response_receipt(detail_paths={})
    receipt["full_detail_tool"] = "material_studio_live_capabilities"
    bounded["response_compaction"] = receipt
    if _compact_json_size_bytes(bounded) < COMPACT_RESPONSE_MAX_BYTES:
        return bounded

    receipt["hard_budget_applied"] = True
    natural_language = bounded.get("natural_language")
    if isinstance(natural_language, dict):
        natural_language = dict(natural_language)
        if natural_language.pop("cjk_semiconductor_hotload_examples", None) is not None:
            receipt["omitted_fields"].append(
                "natural_language.cjk_semiconductor_hotload_examples"
            )
        bounded["natural_language"] = natural_language
    for key in ("schemas", "view_replay_confirmation_entry", "visual_confirmation_entry"):
        if key in bounded:
            bounded.pop(key, None)
            receipt["omitted_fields"].append(key)
        if _compact_json_size_bytes(bounded) < COMPACT_RESPONSE_MAX_BYTES:
            return bounded

    domain = bounded.get("domain_focus")
    if isinstance(domain, dict):
        domain = dict(domain)
        for key in ("semiconductor_template_ids", "semiconductor_virtual_template_ids"):
            identifiers = domain.get(key)
            if isinstance(identifiers, list):
                domain[f"{key}_sample"] = identifiers[:20]
                domain.pop(key, None)
                receipt["omitted_fields"].append(f"domain_focus.{key}")
        bounded["domain_focus"] = domain
    if _compact_json_size_bytes(bounded) < COMPACT_RESPONSE_MAX_BYTES:
        return bounded
    minimal = _mapping_subset(
        bounded,
        (
            "ok",
            "live_preflight_tool",
            "live_entry_tool",
            "live_status_tool",
            "live_update_tool",
            "dopant_metadata_reconcile_tool",
            "recommended_kpoint_remediation_action_id",
            "recommended_calculation_settings_confirmation_field",
            "recommended_calculation_settings_requires_explicit_confirmation",
            "recommended_calculation_settings_receipt_recovery_field",
            "recommended_calculation_settings_receipt_recovery_policy",
            "default_execution_mode",
            "response_modes",
            "response_mode",
            "response_schema",
            "supported_response_modes",
            "max_response_bytes",
            "target_response_bytes",
            "full_detail_hint",
            "runner_status",
            "gui_status",
            "view_replay_runtime_availability",
            "domain_focus",
            "diagnostics",
            "gui_tools",
            "safety",
        ),
    )
    receipt["omitted_fields"].append("oversized_capability_catalogs")
    minimal["response_compaction"] = receipt
    for key in ("domain_focus", "diagnostics", "response_modes"):
        if _compact_json_size_bytes(minimal) < COMPACT_RESPONSE_MAX_BYTES:
            break
        if key in minimal:
            minimal.pop(key, None)
            receipt["omitted_fields"].append(key)
    return minimal


def _compact_revision_delta(value: Any) -> dict[str, Any] | None:
    """Return bounded revision-delta evidence for an interactive MCP reply."""

    if not isinstance(value, dict):
        return None
    compact = _mapping_subset(
        value,
        (
            "available",
            "project_id",
            "base_revision",
            "new_revision",
            "model_type_before",
            "model_type_after",
            "model_type_changed",
            "diff",
            "atom_count_before",
            "atom_count_after",
            "atom_count_delta",
            "bond_count_before",
            "bond_count_after",
            "bond_count_delta",
            "element_counts_before",
            "element_counts_after",
            "element_count_delta",
            "metadata_changed_keys",
            "output_changed_keys",
        ),
    )
    for section_name in ("simulation", "molecule", "crystal"):
        section = value.get(section_name)
        if not isinstance(section, dict):
            continue
        section_compact = _mapping_subset(
            section,
            (
                "changed",
                "changed_fields",
                "name_before",
                "name_after",
                "lattice_changed",
                "lattice_before",
                "lattice_after",
                "lattice_delta",
                "fractional_coordinate_update_count",
                "cartesian_moved_atom_count",
                "cartesian_preserved_atom_count",
                "max_cartesian_displacement_angstrom",
                "fractional_rescale_preserved_cartesian",
                "operation_count_before",
                "operation_count_after",
            ),
        )
        for list_key in (
            "added_atoms",
            "deleted_atoms",
            "substituted_atoms",
            "moved_atoms",
            "added_bonds",
            "deleted_bonds",
            "changed_bonds",
        ):
            items = section.get(list_key)
            if isinstance(items, list):
                section_compact[f"{list_key}_count"] = len(items)
                section_compact[f"{list_key}_sample"] = items[:20]
                if len(items) > 20:
                    section_compact[f"{list_key}_sample_truncated"] = True
        if section_compact:
            compact[section_name] = section_compact
    return compact


def _compact_calculation_preview(value: Any) -> dict[str, Any]:
    """Return a bounded CASTEP preview receipt without source text."""

    if not isinstance(value, dict):
        return {}
    compact = _mapping_subset(
        value,
        (
            "available",
            "kind",
            "module",
            "task",
            "script_path",
            "script_exists",
            "script_matches_generated",
            "artifact_status",
            "persisted_artifact_trusted",
            "preview_ready",
            "execution_policy",
            "execution_supported_by_structured_workflow",
            "structure_materialization_executes_calculation",
            "requires_explicit_separate_execution",
            "calculation_executed",
            "calculation_result_available",
        ),
    )
    dispatch = value.get("dispatch")
    if isinstance(dispatch, dict):
        compact["dispatch"] = _mapping_subset(
            dispatch,
            (
                "api_object",
                "run_method",
                "property_setting",
                "materials_studio_api_contract",
            ),
        )
    validation = value.get("validation")
    if isinstance(validation, dict):
        compact["validation"] = _mapping_subset(validation, ("valid",))
    return compact


def _compact_artifacts(response: dict[str, Any], report: dict[str, Any]) -> dict[str, Any]:
    """Return stable artifact entry points without the complete file map."""

    receipt = report.get("change_receipt") if isinstance(report.get("change_receipt"), dict) else {}
    receipt_artifacts = receipt.get("artifacts") if isinstance(receipt.get("artifacts"), dict) else {}
    diagnostics = report.get("diagnostics") if isinstance(report.get("diagnostics"), dict) else {}
    promoted = response.get("artifacts") if isinstance(response.get("artifacts"), dict) else {}
    merged = {**diagnostics, **receipt_artifacts, **promoted}
    return _mapping_subset(
        merged,
        (
            "structure_path",
            "structure_exists",
            "calculation_preview_script_path",
            "gui_snapshot_path",
            "snapshot_path",
            "report_json_path",
            "view_summary_csv",
            "view_projections_csv",
        ),
    )


