    if _response_mode(response_mode) == McpResponseMode.FULL:
        return response
    report = response.get("modeling_report") if isinstance(response.get("modeling_report"), dict) else {}
    live = response.get("live_summary") if isinstance(response.get("live_summary"), dict) else {}
