@mcp.tool(
    name="material_studio_gui_prepare_view_replay",
    annotations={
        "title": "Prepare a safe Materials Studio GUI view replay manifest",
        "readOnlyHint": False,
        "destructiveHint": False,
        "idempotentHint": False,
        "openWorldHint": False,
    },
)
def material_studio_gui_prepare_view_replay(
    project_id: Annotated[str | None, Field(description="Optional structured project ID; omitted uses the latest current project.", min_length=1, max_length=120)] = None,
    revision: Annotated[int | None, Field(description="Optional revision; omitted uses the resolved current revision.", ge=0)] = None,
    views: Annotated[list[str] | None, Field(description="View names to prepare, including Cartesian, crystal direction/plane, or surface/interface frame views.", min_length=1, max_length=32)] = None,
    runtime_ui_evidence: Annotated[GuiMillerPlaneRuntimeUiEvidenceInput | None, Field(description="Optional current-window Miller-plane UI observation. It is persisted only after exact project/revision/window binding succeeds.")] = None,
    runtime_accessibility_evidence: Annotated[GuiViewRuntimeAccessibilityEvidenceInput | None, Field(description="Optional current-window named-control or ordered anonymous-toolbar observation. Anonymous commands are derived only from the installed registry plus an exact live child sequence; static registration alone never enables replay.")] = None,
    working_dir: Annotated[str | None, Field(description="Optional structured/GUI workspace root.")] = None,
    response_mode: Annotated[McpResponseMode, Field(description="full replay manifest or compact MCP preparation receipt.")] = McpResponseMode.FULL,
) -> dict[str, Any]:
    """Persist camera and verification parameters without changing the GUI."""

    try:
        context = _resolve_gui_action_context(project_id=project_id, revision=revision, working_dir=working_dir)
        if context.get("project_id") is None or context.get("revision") is None:
            return _compact_live_response(
                _error(ValueError(f"Cannot resolve project/revision for view replay: {context}")),
                response_mode,
            )
        normalized_views: list[str] | None = None
        if views is not None:
            normalized_views = []
            for raw_view in views:
                view_name = str(raw_view).strip()
                if not view_name:
                    raise ValueError("view names must not be empty")
                if len(view_name) > 80:
                    raise ValueError("view names must be at most 80 characters")
                if any(ord(char) < 32 for char in view_name):
                    raise ValueError("view names must not contain control characters")
                if view_name not in normalized_views:
                    normalized_views.append(view_name)
        normalized_runtime_ui_evidence: dict[str, Any] | None = None
        if runtime_ui_evidence is not None:
            evidence_model = (
                runtime_ui_evidence
                if isinstance(runtime_ui_evidence, GuiMillerPlaneRuntimeUiEvidenceInput)
                else GuiMillerPlaneRuntimeUiEvidenceInput.model_validate(runtime_ui_evidence)
            )
            normalized_runtime_ui_evidence = evidence_model.model_dump(mode="json")
        normalized_runtime_accessibility_evidence: dict[str, Any] | None = None
        if runtime_accessibility_evidence is not None:
            accessibility_evidence_model = (
                runtime_accessibility_evidence
                if isinstance(
                    runtime_accessibility_evidence,
                    GuiViewRuntimeAccessibilityEvidenceInput,
                )
                else GuiViewRuntimeAccessibilityEvidenceInput.model_validate(
                    runtime_accessibility_evidence
                )
            )
            normalized_runtime_accessibility_evidence = (
                accessibility_evidence_model.model_dump(mode="json")
            )
        store = _structured_store(working_dir)
        spec = store.get_revision(str(context["project_id"]), int(context["revision"]))
        audit = model_view_audit(spec, normalized_views)
        result = _gui_controller(working_dir).prepare_view_replay(
            audit,
            project_id=spec.project_id,
            revision=spec.revision,
            runtime_ui_evidence=normalized_runtime_ui_evidence,
            runtime_accessibility_evidence=(
                normalized_runtime_accessibility_evidence
            ),
        )
        result["project_resolution"] = context.get("project_resolution") or _explicit_project_resolution(spec)
        result["resolved_latest_current_for_view_replay"] = (
            project_id is None and revision is None and context.get("reason") == "latest_current_project"
        )
        result["spec_fingerprint"] = audit.get("spec_fingerprint")
        result["model_type"] = audit.get("model_type")
        result["viewport_control_backend"] = "manifest_only"
        result["gui_modified"] = False
        result["structure_modified"] = False
        return _compact_live_response(_ok(result), response_mode)
    except Exception as exc:
        return _compact_live_response(_error(exc), response_mode)


@mcp.tool(
    name="material_studio_gui_execute_view_replay",
    annotations={
        "title": "Preview or execute one safe Materials Studio GUI view replay",
        "readOnlyHint": False,
        "destructiveHint": False,
        "idempotentHint": True,
        "openWorldHint": False,
    },
)
def material_studio_gui_execute_view_replay(
    project_id: Annotated[str | None, Field(description="Optional structured project ID; omitted uses the latest current project.", min_length=1, max_length=120)] = None,
    revision: Annotated[int | None, Field(description="Optional revision; omitted uses the resolved current revision.", ge=0)] = None,
    view_name: Annotated[str | None, Field(description="Optional prepared standard, isometric, or crystallographic Miller view. Omitted selects the next pending locally executable view.", min_length=1, max_length=80)] = None,
    execution_mode: Annotated[ExecutionMode, Field(description="preview performs only a read-only UIA preflight; execute runs either a Reset/arrow camera recipe or a transactional Miller-plane View Onto recipe that captures then exactly restores the prior view.")] = ExecutionMode.PREVIEW,
    working_dir: Annotated[str | None, Field(description="Optional structured/GUI workspace root.")] = None,
) -> dict[str, Any]:
    """Run one locally allowlisted GUI view recipe without recording acceptance."""

    try:
        context = _resolve_gui_action_context(
            project_id=project_id,
            revision=revision,
            working_dir=working_dir,
        )
        if context.get("project_id") is None or context.get("revision") is None:
            return _error(
                ValueError(
                    f"Cannot resolve project/revision for view replay execution: {context}"
                )
            )
        resolved_project_id = str(context["project_id"])
        resolved_revision = int(context["revision"])
        store = _structured_store(working_dir)
        spec = store.get_revision(resolved_project_id, resolved_revision)
        output_dir = store.outputs_dir(spec.project_id, spec.revision)
        persisted_manifest, _manifest_error = _read_json_file(
            output_dir / "gui_view_replay_manifest.json"
        )
        existing_view_names = (
            [
                str(item)
                for item in persisted_manifest.get("view_names") or []
                if str(item).strip()
            ]
            if isinstance(persisted_manifest, dict)
            and persisted_manifest.get("project_id") == spec.project_id
            and persisted_manifest.get("revision") == spec.revision
            else []
        )
        audit: dict[str, Any]
        selection_source: str
        if existing_view_names:
            candidate_audit = model_view_audit(spec, existing_view_names)
            if (
                isinstance(persisted_manifest, dict)
                and persisted_manifest.get("spec_fingerprint")
                == candidate_audit.get("spec_fingerprint")
            ):
                audit = candidate_audit
                selection_source = "current_view_replay_manifest"
            else:
                existing_view_names = []
        if not existing_view_names:
            persisted_audit, _audit_error = _read_json_file(
                output_dir / "view_audit.json"
            )
            audit, selection = _resolve_gui_reaudit_view_selection(
                spec,
                views=None,
                persisted_audit=persisted_audit,
            )
            selection_source = str(selection.get("source") or "default_views")

        result = _gui_controller(working_dir).run_view_replay(
            audit,
            project_id=spec.project_id,
            revision=spec.revision,
            view_name=view_name,
            execution_mode=execution_mode.value,
        )
        result["project_resolution"] = context.get(
            "project_resolution"
        ) or _explicit_project_resolution(spec)
        result["resolved_latest_current_for_view_replay_execution"] = bool(
            project_id is None
            and revision is None
            and context.get("reason") == "latest_current_project"
        )
        result["view_selection_source"] = selection_source
        result["spec_fingerprint"] = audit.get("spec_fingerprint")
        result["model_type"] = audit.get("model_type")
        return _ok(result)
    except Exception as exc:
        return _error(exc)


@mcp.tool(
    name="material_studio_gui_record_view_replay",
    annotations={
        "title": "Record externally verified Materials Studio GUI view replay evidence",
        "readOnlyHint": False,
        "destructiveHint": False,
        "idempotentHint": False,
        "openWorldHint": False,
    },
)
def material_studio_gui_record_view_replay(
    view_name: Annotated[str, Field(description="A view name present in the prepared replay manifest.", min_length=1, max_length=80)],
    project_id: Annotated[str | None, Field(description="Optional structured project ID; omitted uses the latest current project.", min_length=1, max_length=120)] = None,
    revision: Annotated[int | None, Field(description="Optional revision; omitted uses the resolved current revision.", ge=0)] = None,
    source: Annotated[str, Field(description="External replay source, such as computer_use or reviewed_copy_script.", min_length=1, max_length=80)] = "computer_use",
    model_visible: Annotated[bool, Field(description="Whether the expected model is visibly present after replay.")] = True,
    camera_matches_manifest: Annotated[bool, Field(description="Whether the externally reviewed camera/view matches the prepared manifest.")] = True,
    note: Annotated[str | None, Field(description="Short replay verification note.", max_length=1000)] = None,
    screenshot_path: Annotated[str | None, Field(description="Optional screenshot evidence inside the configured MCP workspace.", max_length=500)] = None,
    reviewed_copy_script_evidence: Annotated[GuiReviewedCopyScriptEvidenceInput | None, Field(description="Required inert script text and review attestations when source is reviewed_copy_script.")] = None,
    expected_window_handle: Annotated[int | None, Field(description="Optional observed Materials Studio window handle used to bind the replay evidence.", gt=0)] = None,
    expected_window_title: Annotated[str | None, Field(description="Optional observed wrapper window title used to bind the replay evidence.", min_length=1, max_length=500)] = None,
    native_command_id: Annotated[str | None, Field(description="Optional reviewed Materials Studio 2020 3D-view command used for replay.", pattern=r"^cmdViewer3D[A-Za-z0-9_]+$", max_length=120)] = None,
    accessibility_command_uses: Annotated[list[GuiViewReplayAccessibilityCommandUseInput] | None, Field(description="Exact invocation receipts for server-mapped anonymous toolbar controls.", min_length=1, max_length=2)] = None,
    key_sequence: Annotated[list[Annotated[str, Field(pattern=r"^(Up|Down|Left|Right)$")]] | None, Field(description="Optional exact unmodified arrow-key sequence from the prepared recipe.", min_length=1, max_length=16)] = None,
    reset_before_key_sequence: Annotated[bool | None, Field(description="Whether Reset View was invoked before the key sequence.")] = None,
    rotation_increment_degrees: Annotated[float | None, Field(description="Arrow-key rotation increment in degrees.", gt=0, le=360)] = None,
    modifier_keys: Annotated[list[Annotated[str, Field(pattern=r"^(Shift|Ctrl|Alt|Win)$")]] | None, Field(description="Modifier keys held during replay; documented camera recipes require an empty list.", max_length=4)] = None,
    keyboard_stages: Annotated[list[GuiViewReplayKeyboardStageInput] | None, Field(description="Optional exact multi-angle keyboard stages from the prepared recipe.", min_length=1, max_length=8)] = None,
    rotation_increment_restored_degrees: Annotated[float | None, Field(description="Rotation increment observed after staged replay settings were restored.", gt=0, le=360)] = None,
    movement_options_command_id: Annotated[str | None, Field(description="Reviewed Movement-options command used to configure staged angles.", pattern=r"^cmdViewer3D[A-Za-z0-9_]+$", max_length=120)] = None,
    movement_angle_control_id: Annotated[str | None, Field(description="Accessibility ID of the Movement angle control.", min_length=1, max_length=120)] = None,
    movement_screen_factor_control_id: Annotated[str | None, Field(description="Accessibility ID of the Movement screen-factor control.", min_length=1, max_length=120)] = None,
    movement_screen_factor: Annotated[float | None, Field(description="Observed Movement screen factor after replay.", gt=0, le=100)] = None,
    movement_dialog_closed: Annotated[bool | None, Field(description="Whether the Movement dialog was closed after restoring settings.")] = None,
    crystal_camera_evidence: Annotated[GuiCrystalCameraEvidenceInput | None, Field(description="Observed standard crystal view direction and Materials Studio native in-plane roll; exact analytic camera-up/right equality is optional.")] = None,
    miller_plane_evidence: Annotated[GuiMillerPlaneReplayEvidenceInput | None, Field(description="Exact transient Miller-plane selection, native View Onto, hash, and cleanup evidence.")] = None,
    evidence_request: Annotated[str | None, Field(description="Optional natural-language request whose explicit diagnostic intent should be merged into the persisted evidence audit.", min_length=1, max_length=5000)] = None,
    working_dir: Annotated[str | None, Field(description="Optional structured/GUI workspace root.")] = None,
    response_mode: Annotated[McpResponseMode, Field(description="full diagnostics or compact MCP view-replay receipt.")] = McpResponseMode.FULL,
) -> dict[str, Any]:
    """Record Computer Use, reviewed Copy Script, or human view-replay evidence."""

    try:
        if (expected_window_handle is None) != (expected_window_title is None):
            raise ValueError("expected_window_handle and expected_window_title must be supplied together")
        context = _resolve_gui_action_context(project_id=project_id, revision=revision, working_dir=working_dir)
        if context.get("project_id") is None or context.get("revision") is None:
            return _compact_live_response(
                _error(ValueError(f"Cannot resolve project/revision for replay evidence: {context}")),
                response_mode,
            )
        gui = _gui_controller(working_dir)
        replay_binding: dict[str, Any] | None = None
        if expected_window_handle is not None and expected_window_title is not None:
            try:
                gui_status = gui.status(
                    project_id=str(context["project_id"]),
                    revision=int(context["revision"]),
                )
            except Exception as exc:
                gui_status = {"ok": False, "error": str(exc)}
            replay_binding = _gui_visual_confirmation_binding(
                gui_status,
                project_id=str(context["project_id"]),
                revision=int(context["revision"]),
                expected_window_handle=expected_window_handle,
                expected_window_title=expected_window_title,
            )
            if not replay_binding["ok"]:
                return _compact_live_response(
                    {
                        "ok": False,
                        "status": "view_replay_confirmation_rejected",
                        "error": (
                            "View replay evidence was not persisted because the observed window was not "
                            "the verified current wrapper window."
                        ),
                        "project_id": str(context["project_id"]),
                        "revision": int(context["revision"]),
                        "project_resolution": context.get("project_resolution"),
                        "view_name": view_name.strip(),
                        "view_replay_binding": replay_binding,
                        "gui_status": gui_status,
                    },
                    response_mode,
                )
        replay = gui.record_view_replay(
            project_id=str(context["project_id"]),
            revision=int(context["revision"]),
            view_name=view_name.strip(),
            source=source.strip(),
            model_visible=model_visible,
            camera_matches_manifest=camera_matches_manifest,
            note=note,
            screenshot_path=screenshot_path,
            reviewed_copy_script_evidence=(
                GuiReviewedCopyScriptEvidenceInput.model_validate(
                    reviewed_copy_script_evidence
                ).model_dump(mode="json")
                if reviewed_copy_script_evidence is not None
                else None
            ),
            expected_window_handle=expected_window_handle,
            expected_window_title=expected_window_title,
            native_command_id=native_command_id,
            accessibility_command_uses=(
                [
                    GuiViewReplayAccessibilityCommandUseInput.model_validate(
                        item
                    ).model_dump(mode="json")
                    for item in accessibility_command_uses
                ]
                if accessibility_command_uses is not None
                else None
            ),
            key_sequence=key_sequence,
            reset_before_key_sequence=reset_before_key_sequence,
            rotation_increment_degrees=rotation_increment_degrees,
            modifier_keys=modifier_keys,
            keyboard_stages=(
                [
                    GuiViewReplayKeyboardStageInput.model_validate(stage).model_dump(mode="json")
                    for stage in keyboard_stages
                ]
                if keyboard_stages is not None
                else None
            ),
            rotation_increment_restored_degrees=rotation_increment_restored_degrees,
            movement_options_command_id=movement_options_command_id,
            movement_angle_control_id=movement_angle_control_id,
            movement_screen_factor_control_id=movement_screen_factor_control_id,
            movement_screen_factor=movement_screen_factor,
            movement_dialog_closed=movement_dialog_closed,
            crystal_camera_evidence=(
                _dump_crystal_camera_evidence(crystal_camera_evidence)
                if crystal_camera_evidence is not None
                else None
            ),
            miller_plane_evidence=(
                _dump_miller_plane_replay_evidence(miller_plane_evidence)
                if miller_plane_evidence is not None
                else None
            ),
        )
        event = replay.get("event") if isinstance(replay.get("event"), dict) else {}
        if replay_binding is None and isinstance(event.get("window_binding"), dict):
            replay_binding = event["window_binding"]
        replay_confirmation = {
            "view_name": replay.get("view_name"),
            "source": source.strip(),
            "model_visible": bool(model_visible),
            "camera_matches_manifest": bool(camera_matches_manifest),
            "note": note,
            "screenshot_path": event.get("screenshot_path"),
            "reviewed_copy_script_evidence": event.get(
                "reviewed_copy_script_evidence"
            ),
            "reviewed_copy_script_evidence_complete": event.get(
                "reviewed_copy_script_evidence_complete"
            ),
            "evidence_integrity": event.get("evidence_integrity"),
            "event_record_sha256": event.get("event_record_sha256"),
            "journal_consistency": event.get("journal_consistency"),
            "expected_revision": int(context["revision"]),
            "expected_window_handle": expected_window_handle,
            "expected_window_title": expected_window_title,
            "native_command_id": native_command_id,
            "accessibility_command_uses": event.get(
                "accessibility_command_uses"
            ),
            "accessibility_command_uses_complete": event.get(
                "accessibility_command_uses_complete"
            ),
            "key_sequence": event.get("key_sequence"),
            "reset_before_key_sequence": event.get("reset_before_key_sequence"),
            "rotation_increment_degrees": event.get("rotation_increment_degrees"),
            "modifier_keys": event.get("modifier_keys"),
            "keyboard_stages": event.get("keyboard_stages"),
            "rotation_increment_restored_degrees": event.get(
                "rotation_increment_restored_degrees"
            ),
            "movement_options_command_id": event.get("movement_options_command_id"),
            "movement_angle_control_id": event.get("movement_angle_control_id"),
            "movement_screen_factor_control_id": event.get(
                "movement_screen_factor_control_id"
            ),
            "movement_screen_factor": event.get("movement_screen_factor"),
            "movement_dialog_closed": event.get("movement_dialog_closed"),
            "keyboard_evidence_status": event.get("keyboard_evidence_status"),
            "crystal_camera_evidence": event.get("crystal_camera_evidence"),
            "crystal_camera_evidence_complete": event.get(
                "crystal_camera_evidence_complete"
            ),
            "crystal_camera_screenshot_verified": event.get(
                "crystal_camera_screenshot_verified"
            ),
            "miller_plane_evidence": event.get("miller_plane_evidence"),
            "miller_plane_evidence_complete": event.get("miller_plane_evidence_complete"),
            "accepted": replay.get("accepted") is True,
            "event_id": event.get("event_id"),
        }
        response: dict[str, Any] = {
            **replay,
            "project_resolution": context.get("project_resolution"),
            "resolved_latest_current_for_view_replay_record": (
                project_id is None and revision is None and context.get("reason") == "latest_current_project"
            ),
            "gui_modified_by_tool": False,
            "structure_modified": False,
            "view_replay_confirmation": replay_confirmation,
            "view_replay_binding": replay_binding,
        }
        if replay.get("accepted") is True:
            confirmation = {
                "project_id": replay["project_id"],
                "revision": replay["revision"],
                "source": source.strip(),
                "model_visible": True,
                "note": note,
                "screenshot_path": event.get("screenshot_path"),
                "recorded_at": event.get("recorded_at"),
                "window": event.get("window"),
                "gui_status_ok": (replay.get("gui_status") or {}).get("ok"),
                "single_window_policy_ok": event.get("single_window_policy_ok"),
                "single_window_violation_reasons": [],
                "replay_manifest_path": replay.get("manifest_path"),
                "replay_view_name": replay.get("view_name"),
                "replay_camera_matches_manifest": True,
                "replay_event_id": event.get("event_id"),
                "window_binding": replay_binding,
                "native_command_id": event.get("native_command_id"),
                "native_command": event.get("native_command"),
                "accessibility_command_uses": event.get(
                    "accessibility_command_uses"
                ),
                "accessibility_command_uses_complete": event.get(
                    "accessibility_command_uses_complete"
                ),
                "key_sequence": event.get("key_sequence"),
                "reset_before_key_sequence": event.get("reset_before_key_sequence"),
                "rotation_increment_degrees": event.get("rotation_increment_degrees"),
                "modifier_keys": event.get("modifier_keys"),
                "keyboard_stages": event.get("keyboard_stages"),
                "rotation_increment_restored_degrees": event.get(
                    "rotation_increment_restored_degrees"
                ),
                "movement_options_command_id": event.get("movement_options_command_id"),
                "movement_angle_control_id": event.get("movement_angle_control_id"),
                "movement_screen_factor_control_id": event.get(
                    "movement_screen_factor_control_id"
                ),
                "movement_screen_factor": event.get("movement_screen_factor"),
                "movement_dialog_closed": event.get("movement_dialog_closed"),
                "keyboard_evidence_status": event.get("keyboard_evidence_status"),
                "reviewed_copy_script_evidence": event.get(
                    "reviewed_copy_script_evidence"
                ),
                "reviewed_copy_script_evidence_complete": event.get(
                    "reviewed_copy_script_evidence_complete"
                ),
                "evidence_integrity": event.get("evidence_integrity"),
                "event_record_sha256": event.get("event_record_sha256"),
                "journal_consistency": event.get("journal_consistency"),
                "crystal_camera_evidence": event.get("crystal_camera_evidence"),
                "crystal_camera_evidence_complete": event.get(
                    "crystal_camera_evidence_complete"
                ),
                "crystal_camera_screenshot_verified": event.get(
                    "crystal_camera_screenshot_verified"
                ),
                "miller_plane_evidence": event.get("miller_plane_evidence"),
                "miller_plane_evidence_complete": event.get("miller_plane_evidence_complete"),
            }
            structured = _persist_gui_visual_confirmation_report(
                project_id=str(replay["project_id"]),
                revision=int(replay["revision"]),
                confirmation=confirmation,
                gui_status=replay.get("gui_status") or {},
                working_dir=working_dir,
                views=list(replay.get("manifest_view_names") or []) or None,
                project_resolution=context.get("project_resolution"),
                evidence_request=evidence_request,
            )
            response.update(structured)
            response["view_replay"] = replay
        else:
            response["structured_sync"] = {
                "persisted": False,
                "reason": "replay_evidence_not_accepted",
                "rejection_reasons": replay.get("rejection_reasons") or [],
            }
        return _compact_live_response(_ok(response), response_mode)
    except Exception as exc:
        return _compact_live_response(_error(exc), response_mode)


@mcp.tool(
    name="material_studio_gui_apply_current_revision",
    annotations={
        "title": "Execute current structured revision and open it in the GUI",
        "readOnlyHint": False,
        "destructiveHint": True,
        "idempotentHint": False,
        "openWorldHint": False,
    },
)
def material_studio_gui_apply_current_revision(
    project_id: Annotated[str | None, Field(description="要应用的结构化项目 ID；省略时使用最近 current 项目。", min_length=1, max_length=120)] = None,
    execution_mode: Annotated[ExecutionMode, Field(description="preview 或 execute。默认为 preview。")] = ExecutionMode.PREVIEW,
    open_in_gui: Annotated[bool, Field(description="成功执行后在现有 GUI 中打开生成的结构。")] = True,
    take_snapshot: Annotated[bool, Field(description="打开后尽可能捕获 GUI 快照。")] = True,
    export_view_audit: Annotated[bool, Field(description="导出当前 revision 的 view_audit.json 和 modeling_health。")] = True,
    views: Annotated[list[str] | None, Field(description="可选的标准视角名称，例如 front/back/right/left/top/bottom/isometric。")] = None,
    working_dir: Annotated[str | None, Field(description="可选的结构化/GUI 工作区根目录。")] = None,
    timeout_seconds: Annotated[int | None, Field(description="执行超时时间（秒）。", ge=1, le=7 * 24 * 3600)] = None,
    response_mode: Annotated[McpResponseMode, Field(description="full diagnostics or compact MCP GUI receipt.")] = McpResponseMode.FULL,
) -> dict[str, Any]:
    """Preview or execute the current structured revision, then optionally open its output in the GUI."""

    orchestration_context = dict(
        _ACTIVE_LIVE_ORCHESTRATION_CONTEXT.get() or {}
    )

    def enrich(result: dict[str, Any]) -> dict[str, Any]:
        if orchestration_context:
            result.update(orchestration_context)
        return result

    def finish(result: dict[str, Any]) -> dict[str, Any]:
        return _compact_live_response(enrich(result), response_mode)

    try:
        mode = _execution_mode(execution_mode)
        store = _structured_store(working_dir)
        if project_id is None:
            latest = _latest_live_project(store)
            if latest is None:
                return finish(
                    _error(
                        ValueError(
                            "No current structured project exists. Create a model before applying the current revision."
                        )
                    )
                )
            spec, project_resolution = latest
            project_id = spec.project_id
        else:
            spec, current_resolution = store.resolve_current(project_id)
            project_resolution = _explicit_project_resolution(spec, current_resolution)
        audit_artifacts: list[dict[str, Any]] = []
        gui = _gui_controller(working_dir)
        script_path = store.project_dir(project_id) / "scripts" / f"r{spec.revision:03d}_build.pl"
        if not script_path.exists():
            response: dict[str, Any] = enrich({
                "ok": False,
                "error": (
                    "当前修订版本没有保存的预览脚本。"
                    "请先运行 material_studio_model_create_from_spec 或 material_studio_model_modify_with_patch。"
                ),
                "project_id": project_id,
                "project_resolution": project_resolution,
                "revision": spec.revision,
                "script_path": str(script_path),
            })
            if export_view_audit:
                response["view_audit"] = model_view_audit(spec, views)
            return finish(
                _attach_modeling_health(response, execution_mode=mode, store=store, spec=spec, gui_artifacts=audit_artifacts)
            )
        script = script_path.read_text(encoding="utf-8")
        script_validation = validate_generated_script(script)
        generated = _generate_structured_script(spec, store)
        response: dict[str, Any] = enrich({
            "ok": True,
            "project_id": project_id,
            "project_resolution": project_resolution,
            "revision": spec.revision,
            "execution_mode": mode.value,
            "script_path": str(script_path),
            "validation": script_validation,
            "warnings": generated["warnings"],
            "planned_outputs": generated["planned_outputs"],
            "calculation_preview": _calculation_preview_receipt(
                generated,
                include_script=False,
            ),
            "gui_status": gui.status(project_id=project_id, revision=spec.revision),
        })
        if export_view_audit:
            response["view_audit"] = model_view_audit(spec, views)
        if not script_validation.get("valid", False):
            response = {**response, "ok": False, "error": "保存的预览脚本未通过安全验证。"}
            return finish(
                _attach_modeling_health(response, execution_mode=mode, store=store, spec=spec, gui_artifacts=audit_artifacts)
            )
        if mode == ExecutionMode.PREVIEW:
            return finish(
                _attach_modeling_health(response, execution_mode=mode, store=store, spec=spec, gui_artifacts=audit_artifacts)
            )
        if not generated["executable"] and not isinstance(spec.model, CrystalSpec):
            response = {**response, "ok": False, "error": "当前修订版本仅用于预览，无法安全执行。"}
            return finish(
                _attach_modeling_health(response, execution_mode=mode, store=store, spec=spec, gui_artifacts=audit_artifacts)
            )

        if open_in_gui:
            blocked_response = _with_single_window_hotload_block(response, response.get("gui_status"))
            if blocked_response is not response:
                return finish(
                    _attach_modeling_health(
                        blocked_response,
                        execution_mode=mode,
                        store=store,
                        spec=spec,
                        gui_artifacts=audit_artifacts,
                    )
                )

        execution = _execute_or_materialize_structure(
            store=store,
            spec=spec,
            generated=generated,
            script=script,
            timeout_seconds=timeout_seconds,
        )
        response.update(execution)
        result = execution.get("result", {})
        if not result.get("success", False):
            response["ok"] = False
        structure_path = Path(str(generated["planned_outputs"].get("structure", ""))).expanduser()
        if result.get("success") and open_in_gui:
            if structure_path.exists():
                return finish(
                    _finalize_high_level_gui_hotload(
                        response=response,
                        store=store,
                        spec=spec,
                        gui=gui,
                        structure_path=structure_path,
                        take_snapshot=take_snapshot,
                        audit_artifacts=audit_artifacts,
                        execution_mode=mode,
                        working_dir=working_dir,
                        workflow=str(
                            orchestration_context.get("workflow")
                            or "gui_apply_current_revision"
                        ),
                        record_gui_open_artifact=True,
                        refresh_view_audit_report=False,
                    )
                )
            else:
                response["gui_open_warning"] = f"未找到计划的输出结构: {structure_path}"
        return finish(
            _attach_modeling_health(response, execution_mode=mode, store=store, spec=spec, gui_artifacts=audit_artifacts)
        )
    except ValidationError as exc:
        return finish(_validation_error(exc))
    except Exception as exc:
        return finish(_error(exc))


def main() -> None:
    """Run the Materials Studio MCP server over stdio."""

    mcp.run()


if __name__ == "__main__":
    main()
